    function iconGlyph(name) {
        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.setAttribute('viewBox', '0 0 16 16');
        svg.setAttribute('fill', 'none');
        svg.setAttribute('stroke', 'currentColor');
        svg.setAttribute('stroke-width', '1.4');
        svg.setAttribute('stroke-linecap', 'round');
        svg.setAttribute('stroke-linejoin', 'round');
        svg.setAttribute('aria-hidden', 'true');
        svg.innerHTML = '<path d="' + (GLYPHS[name] || '') + '"/>';
        return svg;
    }

    /* Заглушка на время загрузки. Крутящийся кружок говорит «жди», но не
       говорит, чего именно, и экран прыгает, когда данные приходят.
       Серые полосы держат ту же разметку, что и готовый экран: глаз уже
       знает, где будет таблица, и не ищет её заново. */
    function skeleton(rows, kind) {
        const lines = [];
        for (let n = 0; n < (rows || 5); n += 1) {
            lines.push(h('div', { class: 'sk-line' }));
        }
        return h('div', { class: 'sk' + (kind ? ' sk--' + kind : '') },
            kind === 'page' ? h('div', { class: 'sk-line sk-line--head' }) : null,
            lines);
    }

    function fmtNumber(value, digits) {
        const number = Number(value);
        if (!isFinite(number)) return '—';
        return number.toFixed(digits === undefined ? 0 : digits).replace('.', ',');
    }

    function fmtBytes(bytes) {
        const units = ['Б', 'КБ', 'МБ', 'ГБ'];
        let value = Number(bytes) || 0;
        let index = 0;
        while (value >= 1024 && index < units.length - 1) {
            value /= 1024;
            index += 1;
        }
        return (index === 0 ? value.toFixed(0) : value.toFixed(1).replace('.', ',')) + ' ' + units[index];
    }

    function clone(value) {
        return value === undefined ? value : JSON.parse(JSON.stringify(value));
    }

    function debounce(fn, ms) {
        let timer = null;
        return function () {
            const args = arguments;
            clearTimeout(timer);
            timer = setTimeout(() => fn.apply(null, args), ms);
        };
    }

    function encodePath(value) {
        return String(value).split('/').map(encodeURIComponent).join('/');
    }

    /** Поле пароля с кнопкой «показать»: вслепую его набирают с ошибками. */
    function passwordField(placeholder) {
        const input = h('input', { type: 'password', placeholder: placeholder || '' });
        const toggle = h('button', {
            class: 'btn btn--ghost btn--sm pw-toggle', type: 'button',
            title: 'Показать пароль',
            onclick: () => {
                const shown = input.type === 'text';
                input.type = shown ? 'password' : 'text';
                toggle.textContent = shown ? 'Показать' : 'Скрыть';
                toggle.title = shown ? 'Показать пароль' : 'Скрыть пароль';
                input.focus();
            },
        }, 'Показать');
        const box = h('div', { class: 'pw-field' }, input, toggle);
        box.input = input;
        return box;
    }

    function domId(prefix, value) {
        return prefix + String(value).replace(/[^\w-]/g, '_');
    }

    function normalizeTitle(value) {
        return String(value || '').replace(/^\s*\d+[.)]\s*/, '').trim().toLowerCase();
    }

    // =====================================================================
    // 2. Клиент REST API
    // =====================================================================

    class ApiError extends Error {
        constructor(status, message) {
            super(message);
            this.name = 'ApiError';
            this.status = status;
        }
    }

    let leavingToLogin = false;

    function goToLogin() {
        if (leavingToLogin) return;
        leavingToLogin = true;
        const next = encodeURIComponent(location.hash || '#/board');
        location.href = '/login?next=' + next;
    }

    async function request(path, options) {
        const opts = options || {};
        const init = {
            method: opts.method || 'GET',
            credentials: 'same-origin',
            headers: Object.assign({ 'Accept': 'application/json' }, opts.headers || {}),
        };
        if (opts.body !== undefined) {
            init.headers['Content-Type'] = 'application/json';
            init.body = JSON.stringify(opts.body);
        }

        let response;
        try {
            response = await fetch(path, init);
        } catch (error) {
            throw new ApiError(0, 'сервер недоступен: проверьте, запущен ли reportgen');
        }

        if (response.status === 401) {
            goToLogin();
            throw new ApiError(401, 'требуется вход в систему');
        }

        if (!response.ok) {
            let message = 'ошибка сервера (код ' + response.status + ')';
            try {
                const data = await response.json();
                if (data && data.error) message = data.error;
            } catch (error) {
                /* тело не JSON — оставляем сообщение по коду */
            }
            throw new ApiError(response.status, message);
        }

        if (opts.expect === 'blob') {
            return { blob: await response.blob(), filename: filenameFrom(response) };
        }
        if (response.status === 204) return null;
        return response.json();
    }

    function filenameFrom(response) {
        const header = response.headers.get('Content-Disposition') || '';
        const utf8 = /filename\*=UTF-8''([^;]+)/i.exec(header);
        if (utf8) {
            try {
                return decodeURIComponent(utf8[1]);
            } catch (error) {
                /* игнорируем и пробуем простой вариант */
            }
        }
        const simple = /filename="?([^";]+)"?/i.exec(header);
        return simple ? simple[1] : 'report.docx';
    }

    /* Номер отрисовки раздела: растёт при каждом переходе.

       Отрисовка раздела асинхронна — она ждёт сервер, — и прежде ничто не
       мешало ей дорисоваться ПОСЛЕ того, как человек ушёл в другой раздел.
       Замер на стенде с задержкой сервера в 0,4 с: из четырёх быстрых
       переходов два показали чужой экран под правильным заголовком. Ушли из
       помощника в «Письма» — а на экране по-прежнему переписка; ушли из
       библиотеки в «Сообщения» — а там библиотека. На загруженной машине
       отдела это случалось при каждом быстром клике, и удалить можно было
       не то, что видишь в заголовке.

       Лечится в одном месте, а не в каждом разделе: ответ, запрошенный для
       прежнего раздела, отвергается, а не отдаётся отрисовке. Опоздавшая
       отрисовка падает на первом же ожидании, ничего не нарисовав и не
       переписав общего состояния. */
    let поколениеВида = 0;

    /** Ответ пришёл, но раздел, для которого его просили, уже закрыт. */
    class Устарело extends Error {
        constructor(path) {
            super('раздел сменился, ответ ' + path + ' больше не нужен');
            this.name = 'Устарело';
        }
    }

    function дляРаздела(path) {
        const поколение = поколениеВида;
        return request(path).then((ответ) => {
            if (поколение !== поколениеВида) throw new Устарело(path);
            return ответ;
        });
    }

    // Отвергнутый ответ — не ошибка: никто его уже не ждёт. Без этого каждый
    // быстрый переход оставлял в консоли «Uncaught (in promise)».
    window.addEventListener('unhandledrejection', (event) => {
        if (event.reason instanceof Устарело) event.preventDefault();
    });

    const api = {
        // Чтение для раздела — отвергается, если раздел сменился.
        get: (path) => дляРаздела(path),
        // Чтение для всего окна: колокол, состояние модели, учётная запись.
        // Им смена раздела безразлична, и отвергать их ответ нельзя — колокол
        // перестал бы обновляться, а точка модели краснела бы без причины.
        getGlobal: (path) => request(path),
        post: (path, body) => request(path, { method: 'POST', body: body || {} }),
        put: (path, body) => request(path, { method: 'PUT', body: body || {} }),
        patch: (path, body) => request(path, { method: 'PATCH', body: body || {} }),
        del: (path) => request(path, { method: 'DELETE' }),
        download: (path) => request(path, { expect: 'blob' }),
    };

    /** Загрузка файла с индикатором прогресса (fetch прогресса отдачи не даёт). */
    function uploadFile(path, formData, onProgress) {
        return new Promise((resolve, reject) => {
            const xhr = new XMLHttpRequest();
            xhr.open('POST', path, true);
            xhr.withCredentials = true;
            xhr.setRequestHeader('Accept', 'application/json');
            xhr.upload.addEventListener('progress', (event) => {
                if (event.lengthComputable && onProgress) onProgress(event.loaded / event.total);
            });
            xhr.addEventListener('load', () => {
                let data = null;
                try {
                    data = JSON.parse(xhr.responseText);
                } catch (error) {
                    data = null;
                }
                if (xhr.status === 401) {
                    goToLogin();
                    reject(new ApiError(401, 'требуется вход в систему'));
                    return;
                }
                if (xhr.status >= 200 && xhr.status < 300) {
                    resolve(data || {});
                    return;
                }
                reject(new ApiError(xhr.status, (data && data.error) ||
                    ('не удалось загрузить файл (код ' + xhr.status + ')')));
            });
            xhr.addEventListener('error', () => reject(new ApiError(0, 'сеть недоступна при загрузке файла')));
            xhr.addEventListener('abort', () => reject(new ApiError(0, 'загрузка прервана')));
            xhr.send(formData);
        });
    }

    function errorText(error) {
        if (!error) return 'неизвестная ошибка';
        if (error instanceof ApiError) return error.message;
        return error.message || String(error);
    }

    // -- три вида пустого места --------------------------------------------
    //
    // На месте списка человек видит одно из трёх: «ещё грузится», «тут
    // ничего нет» и «не получилось». Раньше все три собирались одним и тем
    // же .empty и выглядели одинаково — серой строкой посреди белого поля.
    // Разница между ними для работающего огромна: ждать, заводить или звать
    // администратора. Поэтому вид у каждого свой, и собираются они здесь, а
    // не двадцатью восемью способами по всему файлу.

    /** Ничего нет. Заголовок обязателен, объяснение — почти всегда. */
    function emptyBox(head, note, action) {
        return h('div', { class: 'empty' },
            h('h3', {}, head),
            note ? h('div', { class: 'empty-note' }, note) : null,
            action ? h('div', { class: 'empty-act' }, action) : null);
    }

    /** Ещё грузится. Рамки нет: пустое место здесь временное. */
    function loadingBox(note) {
        return h('div', { class: 'empty empty--loading' },
            h('div', { class: 'spinner' }),
            h('div', { class: 'empty-note' }, note || 'Загружаем…'));
    }

    /** Не получилось. Это не пустота, и выглядеть как пустота не должно. */
    function errorBox(error, note) {
        return h('div', { class: 'empty empty--error' },
            h('h3', {}, 'Не удалось загрузить'),
            h('div', { class: 'empty-note' }, errorText(error)),
            note ? h('div', { class: 'empty-note faint' }, note) : null);
    }

    // =====================================================================
    // 3. Уведомления, модальные окна, индикатор длительных операций
    // =====================================================================

    /** Всплывающее сообщение. Возвращает {set(текст), close()} — для сообщений с ходом работы. */
    function toast(message, kind, ttl) {
        const box = $('#toasts');
        if (!box) return { set() {}, close() {} };
        const text = h('div', {}, message);
        const node = h('div', { class: 'toast' + (kind ? ' is-' + kind : '') },
            text,
            h('button', { class: 'close', title: 'Закрыть', onclick: () => node.remove() }, '×'));
        box.appendChild(node);
        const lifetime = ttl || (kind === 'error' ? 12000 : 5000);
        setTimeout(() => node.remove(), lifetime);
        return { set: (value) => { text.textContent = value; }, close: () => node.remove() };
    }

    function toastError(error) {
        // Отвергнутый ответ прежнего раздела — не беда, о ней не кричим.
        if (error instanceof Устарело) return;
        toast(errorText(error), 'error');
    }

    /** Модальное окно. Возвращает объект с методом close(). */
    function openModal(options) {
        const root = $('#modal-root');
        const footer = h('footer', {});
        const body = h('div', { class: 'modal-body' });
        const modal = h('div', {
            class: 'modal' + (options.narrow ? ' modal--narrow' : '')
                + (options.wide ? ' modal--wide' : ''),
        },
            h('header', {},
                options.title,
                h('button', { class: 'btn btn--ghost btn--icon', title: 'Закрыть', onclick: () => close() }, '×')),
            body, footer);
        const backdrop = h('div', { class: 'modal-backdrop' }, modal);

        append(body, [options.body]);
        append(footer, [options.footer]);

        function onKey(event) {
            if (event.key === 'Escape') {
                event.stopPropagation();
                close();
            }
        }

        function close() {
            document.removeEventListener('keydown', onKey, true);
            backdrop.remove();
            if (options.onClose) options.onClose();
        }

        backdrop.addEventListener('mousedown', (event) => {
            if (event.target === backdrop && options.closeOnBackdrop !== false) close();
        });
        document.addEventListener('keydown', onKey, true);
        root.appendChild(backdrop);
        if (options.focus) setTimeout(() => { const node = $(options.focus, modal); if (node) node.focus(); }, 30);
        return { close: close, modal: modal, body: body, footer: footer };
    }

    /** Подтверждение действия. Возвращает Promise<boolean>. */
    /** Спросить одну строку. Для пароля — со скрытым вводом. */
    function promptDialog(options) {
        return new Promise((resolve) => {
            const box = options.password ? passwordField(options.placeholder) : null;
            // Замечание проверяющего в одну строку не помещается: это текст
            // «что исправить», а не значение поля.
            const input = box ? box.input : h(options.multiline ? 'textarea' : 'input',
                Object.assign(
                    { placeholder: options.placeholder || '', value: options.value || '' },
                    options.multiline ? { rows: '4' } : { type: 'text' }));
            let answered = false;
            const finish = (value) => {
                if (answered) return;
                answered = true;
                dialog.close();
                resolve(value);
            };
            input.addEventListener('keydown', (event) => {
                // В многострочном поле Enter — это перевод строки.
                if (event.key === 'Enter' && !options.multiline) finish(input.value);
            });
            const dialog = openModal({
                title: options.title || 'Введите значение',
                narrow: true,
                body: h('div', { class: 'form-grid' },
                    options.message ? h('div', { class: 'muted' }, options.message) : null,
                    box || input,
                    options.note ? h('div', { class: 'small muted' }, options.note) : null),
                footer: [
                    h('button', { class: 'btn', onclick: () => finish(null) }, 'Отмена'),
                    h('button', {
                        class: 'btn btn--primary', onclick: () => finish(input.value),
                    }, options.confirmText || 'Готово'),
                ],
                onClose: () => finish(null),
            });
            setTimeout(() => input.focus(), 0);
        });
    }

    function confirmDialog(options) {
        return new Promise((resolve) => {
            let answered = false;
            const finish = (value) => {
                if (answered) return;
                answered = true;
                dialog.close();
                resolve(value);
            };
            const confirmButton = h('button', {
                class: 'btn ' + (options.danger ? 'btn--danger' : 'btn--primary'),
                onclick: () => finish(true),
            }, options.confirmText || 'Подтвердить');

            const dialog = openModal({
                narrow: true,
                title: options.title || 'Подтверждение',
                body: h('div', {}, options.message ? h('div', {}, options.message) : null,
                    options.note ? h('div', { class: 'small muted', style: { marginTop: '8px' } }, options.note) : null),
                footer: [
                    h('button', { class: 'btn', onclick: () => finish(false) }, options.cancelText || 'Отмена'),
                    confirmButton,
                ],
                onClose: () => finish(false),
            });
            setTimeout(() => confirmButton.focus(), 30);
        });
    }

    let overlayTimer = null;

    function showOverlay(what, note) {
        const overlay = $('#overlay');
        $('#overlay-what').textContent = what;
        $('#overlay-note').textContent = note || '';
        const started = Date.now();
        const elapsed = $('#overlay-elapsed');
        const tick = () => {
            const seconds = Math.round((Date.now() - started) / 1000);
            const mm = Math.floor(seconds / 60);
            const ss = seconds % 60;
            elapsed.textContent = 'прошло ' + mm + ':' + String(ss).padStart(2, '0');
        };
        tick();
        clearInterval(overlayTimer);
        overlayTimer = setInterval(tick, 1000);
        overlay.hidden = false;
    }

    function hideOverlay() {
        clearInterval(overlayTimer);
        overlayTimer = null;
        $('#overlay').hidden = true;
    }

    async function withOverlay(what, note, fn) {
        showOverlay(what, note);
        try {
            return await fn();
        } finally {
            hideOverlay();
        }
    }

    // =====================================================================
    // 4. Состояние, шапка, темы, маршрутизация
    // =====================================================================

    const state = {
        user: null,
        authEnabled: true,
        config: { outlines: [], doc_types: [], llm: {} },
        // Поддержка форматов зависит от того, какие программы установлены
        // на этой машине, поэтому запрашивается у сервера, а не зашита.
        formats: null,
        route: { name: 'board', id: null },
    };

    /* Права приходят с сервера вместе с записью военнослужащего: держать здесь
       второй список должностей — верный способ разойтись с бэкендом. */
    function canEdit() {
        return !!state.user;
    }

    function isAdmin() {
        return !!state.user && state.user.is_admin === true;
    }

    /* Гость: ему открыт один помощник.

       Переписка гостя не сохраняется — она стирается на сервере и при входе,
       и при выходе. Личного кабинета у гостя нет: заполнять объективку и
       телефоны тому, кого в отделе нет, незачем. Разделы отдела гостю не
       показываются вовсе — дверь, которая не открывается, хуже отсутствия
       двери; сервер их всё равно закрыл бы, но человек не должен упираться
       в отказ, чтобы это узнать. */
    function isGuest() {
        return !!state.user && state.user.is_guest === true;
    }

    /** Может ли этот человек заводить письма. Техник и гость — нет. */
    function canRegister() {
        return canEdit() && !isGuest() && state.user.role !== 'viewer';
    }

    /** Может ли этот человек проверять отчёты: начальник отдела или зам.
     *
     * Это не то же самое, что права администратора: начальник группы заводит
     * людей, а отчёты проверяет не он.
     */
    function canReview() {
        return !!state.user && state.user.can_review === true;
    }

    function isOwner() {
        return !!state.user && state.user.is_owner === true;
    }

    function outlineFor(reportType) {
        return (state.config.outlines || []).find((item) => item.report_type === reportType) || null;
    }

    function reportTypeTitle(reportType) {
        const outline = outlineFor(reportType);
        return outline ? outline.title : reportType;
    }

    /* Короткое имя направления работы для узких мест — списков и колонок.
       Полные названия шаблонов начинаются одинаково («Технический отчёт по
       результатам анализа…»), и в закрытом списке видно только общее начало:
       выбрать не из чего. Короткое имя задаёт сам шаблон-план полем
       short_title, чтобы отдел называл направления своими словами. */
    function reportTypeShort(outline) {
        if (!outline) return '';
        return outline.short_title || outline.title || outline.report_type;
    }

    function docTypeLabel(value) {
        return DOC_TYPE_LABEL[value] || value;
    }

    function domains() {
        return state.config.domains || [];
    }

    /** Название направления по идентификатору; пустое значение — «все направления». */
    function domainTitle(value) {
        if (!value) return 'не указано';
        const found = domains().find((item) => item.id === value);
        return found ? found.title : value;
    }

    /** Выпадающий список направлений с первым пунктом «всё». */
    const DEFAULT_STATUSES = [
        { id: 'current', title: 'действующий' },
        { id: 'superseded', title: 'заменён' },
        { id: 'archived', title: 'архив' },
        { id: 'draft', title: 'проект' },
    ];

    function domainSelect(options) {
        const opts = options || {};
        return h('select', {
            title: opts.title || 'Направление техники',
            disabled: opts.disabled,
            onchange: (event) => opts.onchange && opts.onchange(event.target.value),
        }, h('option', { value: '', selected: !opts.value }, opts.anyLabel || 'Все направления'),
            domains().map((item) => h('option', {
                value: item.id, selected: opts.value === item.id,
            }, item.title)));
    }

    // -- темы ---------------------------------------------------------------

    const THEME_LABEL = { auto: 'Авто', light: 'Светлая', dark: 'Тёмная' };

    function storageGet(key, fallback) {
        try {
            const value = localStorage.getItem(key);
            return value === null ? fallback : value;
        } catch (error) {
            return fallback;
        }
    }

    function storageSet(key, value) {
        try {
            localStorage.setItem(key, value);
        } catch (error) {
            /* приватный режим браузера — молча продолжаем */
        }
    }

    /** Складной раздел, который помнит, оставили его открытым или закрытым.
     *
     * Обслуживание нужно раз в месяц, а смотрят экран каждый день. Держать
     * его развёрнутым — значит каждый день отодвигать вниз то, ради чего
     * пришли; прятать насовсем — значит потерять. Складываем и запоминаем
     * выбор: тот, кто занимается библиотекой, раскроет раздел один раз.
     */
    function foldCard(key, title, note, ...content) {
        const storageKey = 'reportgen.fold.' + key;
        const block = h('details', {
            class: 'card card-pad fold fold--card',
            open: storageGet(storageKey, '') === '1',
            style: { marginTop: '14px' },
        },
            h('summary', {},
                h('b', {}, title),
                note ? h('span', { class: 'fold-note' }, note) : null),
            h('div', { class: 'fold-body' }, ...content));
        block.addEventListener('toggle', () => {
            storageSet(storageKey, block.open ? '1' : '0');
        });
        return block;
    }

    // -- изменяемые колонки таблиц ------------------------------------------

    /** Сделать колонки таблицы перетаскиваемыми по ширине.

        Ширины, подобранные разработчиком, подходят не всем: у одного длинные
        названия документов, у другого — длинные идентификаторы. Поэтому
        границу столбца можно тянуть, а выбранная ширина запоминается в
        браузере и переживает перезагрузку. Двойной щелчок по границе
        возвращает столбцу исходную ширину.
    */
    function makeResizable(table, key) {
        if (!table || table.dataset.resizable === '1') return table;
        table.dataset.resizable = '1';
        const headers = $$('thead th', table);
        if (headers.length < 2) return table;

        // В ключ входит состав заголовков: ширины хранятся по номеру
        // столбца, и после удаления или перестановки столбца сохранённые
        // значения съезжали на соседние. При смене набора начинаем заново.
        const shape = headers.map((th) => (th.textContent || '').trim()).join('|');
        const storageKey = 'reportgen.cols.' + key + '.' + hashString(shape);
        let saved = {};
        try {
            saved = JSON.parse(storageGet(storageKey, '{}')) || {};
        } catch (error) {
            saved = {};
        }

        headers.forEach((th, index) => {
            const width = saved[index];
            if (width) th.style.width = width + 'px';
            if (index === headers.length - 1) return;

            const grip = h('span', {
                class: 'col-grip',
                title: 'Потяните, чтобы изменить ширину. Двойной щелчок — вернуть исходную',
            });
            // Перетаскивание не должно превращаться в сортировку или щелчок
            // по заголовку, поэтому события гасим здесь же.
            grip.addEventListener('click', (event) => event.stopPropagation());
            grip.addEventListener('dblclick', (event) => {
                event.stopPropagation();
                th.style.width = '';
                delete saved[index];
                storageSet(storageKey, JSON.stringify(saved));
            });
            grip.addEventListener('pointerdown', (event) => {
                event.preventDefault();
                event.stopPropagation();
                const startX = event.clientX;
                const startWidth = th.getBoundingClientRect().width;
                table.classList.add('is-resizing');

                // Слушаем документ, а не саму ручку: указатель во время
                // перетаскивания уходит за её пределы, и захват указателя
                // ведёт себя по-разному в разных браузерах.
                const move = (moveEvent) => {
                    const next = Math.max(56, Math.round(startWidth + moveEvent.clientX - startX));
                    th.style.width = next + 'px';
                };
                const stop = () => {
                    table.classList.remove('is-resizing');
                    document.removeEventListener('pointermove', move, true);
                    document.removeEventListener('pointerup', stop, true);
                    document.removeEventListener('pointercancel', stop, true);
                    saved[index] = Math.round(th.getBoundingClientRect().width);
                    storageSet(storageKey, JSON.stringify(saved));
                };
                document.addEventListener('pointermove', move, true);
                document.addEventListener('pointerup', stop, true);
                document.addEventListener('pointercancel', stop, true);
            });
            th.appendChild(grip);
        });
        return table;
    }

    function applyTheme(mode) {
        const root = document.documentElement;
        if (mode === 'light' || mode === 'dark') root.setAttribute('data-theme', mode);
        else root.removeAttribute('data-theme');
    }

    // -- каркас: боковое меню и шапка ---------------------------------------

    /* Значки разделов. Рисуем контуром в одном стиле: заливка спорит
       с текстом, а готовых наборов в изолированном контуре нет. */
    const ICONS = {
        board: '<path d="M2.5 2.5h5v5h-5zM10 2.5h5.5v3h-5.5zM10 8h5.5v5.5h-5.5zM2.5 10h5v3.5h-5z"/>',
        letters: '<path d="M2 4.5h14v9H2zM2 4.5l7 5 7-5"/>',
        chat: '<path d="M2.5 3.5h13v8.5h-8L4 15v-3H2.5z"/>',
        library: '<path d="M3 2.5h3v13H3zM7 2.5h3v13H7zM11.4 3.2l2.8.8-3.2 12.5-2.8-.8z"/>',
        stats: '<path d="M2.5 13.5h13M4.5 13.5V8M8 13.5V3.5M11.5 13.5V6.5M15 13.5v-3"/>',
        users: '<path d="M6.2 8.5a2.6 2.6 0 1 0 0-5.2 2.6 2.6 0 0 0 0 5.2zM1.8 15c0-2.4 2-4 4.4-4s4.4 1.6 4.4 4M11.5 4a2.3 2.3 0 0 1 0 4.6M13 11.2c1.6.5 2.7 1.8 2.7 3.8"/>',
        roster: '<path d="M2.5 4h13v11.5h-13zM2.5 7.5h13M6 2.5v3M12 2.5v3M5.5 10.5h2M8.5 10.5h2M11.5 10.5h2M5.5 13h2M8.5 13h2"/>',
        talks: '<path d="M2.5 3.5h10v7h-6l-4 3zM12.5 6h3v7h-2.5l-3 2.2V13"/>',
        plus: '<path d="M9 3.5v11M3.5 9h11"/>',
        search: '<path d="M12.6 12.6 15.5 15.5M8.2 3.4a4.8 4.8 0 1 0 0 9.6 4.8 4.8 0 0 0 0-9.6z"/>',
        clock: '<path d="M9 2.6a6.4 6.4 0 1 0 0 12.8A6.4 6.4 0 0 0 9 2.6zM9 5.5V9l2.4 1.6"/>',
        // Значки смысла для плиток сводки и действий под ответом.
        alert: '<path d="M9 2.8 16 15H2zM9 7.2v3.6M9 12.9v.1"/>',
        flame: '<path d="M9 16c-3 0-5-2-5-4.8C4 8 6.6 6.8 7.4 3c2.2 1.3 3.2 3.2 3 5 1-.5 1.6-1.4 1.8-2.4C13.6 7 14 8.6 14 11.2 14 14 12 16 9 16z"/>',
        send: '<path d="M2.5 9 15.5 3 11 15.5 8.6 10.2zM8.6 10.2l6.9-7.2"/>',
        check: '<path d="M3.5 9.5 7.2 13 14.5 5"/>',
        copy: '<path d="M6 6h9v9.5H6zM3 12V2.8h9"/>',
        print: '<path d="M4.5 7V2.5h9V7M4.5 13H2.5V7h13v6h-2M4.5 10.5h9v5h-9z"/>',
        table: '<path d="M2.5 3h13v12h-13zM2.5 7h13M2.5 11h13M7 3v12"/>',
        book: '<path d="M9 4.5C7.5 3.3 5.2 3 2.5 3.2v11C5.2 14 7.5 14.4 9 15.5c1.5-1.1 3.8-1.5 6.5-1.3v-11C12.8 3 10.5 3.3 9 4.5zM9 4.5v11"/>',
        spark: '<path d="M9 2.5 10.5 7.5 15.5 9 10.5 10.5 9 15.5 7.5 10.5 2.5 9 7.5 7.5z"/>',
        clip: '<path d="M13 7.3 7.7 12.6a2.6 2.6 0 0 1-3.7-3.7l5.9-5.9a1.8 1.8 0 0 1 2.6 2.6l-5.9 5.9a.9.9 0 0 1-1.3-1.3l5.3-5.3"/>',
        keys: '<path d="M2 5h14v9H2zM4.5 7.5h1M7 7.5h1M9.5 7.5h1M12 7.5h1.5M4.5 10h1M7 10h1M9.5 10h1M12 10h1.5M6 12h6"/>',
        refresh: '<path d="M14.5 5.5A6 6 0 0 0 3.2 7.5M3.5 12.5a6 6 0 0 0 11.3-2M14.8 2.8v2.9h-2.9M3.2 15.2v-2.9h2.9"/>',
        wave: '<path d="M1.5 9h2l1.5-5 2.5 10 2.5-8 2 5 1.5-2h3"/>',
        desk: '<rect x="2" y="2.5" width="14" height="10" rx="1.5"/><path d="M5 5.5h3M5 8h6M6 15.5h6M9 12.5v3"/>',
        net: '<path d="M3 3h4v3H3zM11 3h4v3h-4zM7 12h4v3H7zM5 6v2.5h8V6M9 8.5V12"/>',
    };

    /** Разделы бокового меню. Порядок — от «что сегодня» к справочникам. */
    //: Разделы, разложенные по смыслу работы. Восемь пунктов подряд человек
    //: перечитывает каждый раз заново: список без групп не запоминается, и
    //: глаз ищет «Библиотеку» между «Расходом» и «Метриками» по буквам.
    //: Три группы отвечают трём разным вопросам: что у нас в работе, где
    //: посмотреть, и кто чем занят.
    const SECTIONS = [
        { group: 'work', route: 'board', href: '#/board', title: 'Сводка', icon: 'board' },
        { group: 'work', route: 'cases', href: '#/cases', title: 'Письма', icon: 'letters', count: 'letters' },
        { group: 'work', route: 'roster', href: '#/roster', title: 'Расход', icon: 'roster' },
        { group: 'know', route: 'chat', href: '#/chat', title: 'Помощник', icon: 'chat' },
        { group: 'know', route: 'library', href: '#/library', title: 'Библиотека', icon: 'library' },
        // Сессии: файлы потоков на общем столе — битовый просмотр, операции, общий доступ.
        // Отдельного пункта «Разбор потока» в меню нет: автоанализ — операция на столе
        // (правая кнопка на массиве), помощник — в панели стола. Страница разборов
        // осталась по адресу #/potok — на неё ведут «Разборы без сессии» и старые закладки.
        { group: 'know', route: 'sessions', href: '#/sessions', title: 'Сессии потоков', icon: 'desk' },
        { group: 'know', route: 'pakety', href: '#/pakety', title: 'Пакеты', icon: 'net' },
        { group: 'dept', route: 'talks', href: '#/talks', title: 'Сообщения', icon: 'talks', count: 'talks' },
        { group: 'dept', route: 'users', href: '#/users', title: 'Военнослужащие', icon: 'users', adminOnly: true },
        // Метрики — сводка по работе отдела целиком: сколько писем, чьи
        // отчёты правят и насколько сильно, о чём спрашивают помощника.
        // Распоряжение начальника отдела: только администратору.
        { group: 'dept', route: 'stats', href: '#/stats', title: 'Метрики', icon: 'stats', adminOnly: true },
    ];

    //: Подписи групп. Порядок здесь и есть порядок в меню.
    const SECTION_GROUPS = [
        { id: 'work', title: 'Работа' },
        { id: 'know', title: 'Знание' },
        { id: 'dept', title: 'Отдел' },
    ];

    /** Какой пункт меню подсвечивать для вложенного экрана. Стол разбора и страница
     *  разборов без сессии — часть «Сессий потоков»: своего пункта у них нет. */
    const SECTION_OF = { case: 'cases', stol: 'sessions', session: 'sessions', potok: 'sessions' };

    function icon(name) {
        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.setAttribute('viewBox', '0 0 18 18');
        svg.setAttribute('fill', 'none');
        svg.setAttribute('stroke', 'currentColor');
        svg.setAttribute('stroke-width', '1.4');
        svg.setAttribute('stroke-linecap', 'round');
        svg.setAttribute('stroke-linejoin', 'round');
        svg.setAttribute('aria-hidden', 'true');
        svg.innerHTML = ICONS[name] || '';
        return svg;
    }

    function buildNav() {
        const nav = $('#nav');
        if (!nav) return;
        clear(nav);

        // Гостю показывать нечего, кроме помощника: ни главного действия, ни
        // недавнего у него нет, и пустые заголовки групп только мешают.
        if (!isGuest()) {
            nav.appendChild(buildNavHead());
        }

        SECTION_GROUPS.forEach((group) => {
            const пункты = SECTIONS.filter((section) => {
                if (section.group !== group.id) return false;
                if (section.adminOnly && !isAdmin()) return false;
                if (isGuest() && section.route !== 'chat') return false;
                return true;
            });
            if (!пункты.length) return;
            // Подпись группы прячется в свёрнутом меню: там от неё остаётся
            // обрубок в два знака, который читается как мусор.
            nav.appendChild(h('div', { class: 'side-group' }, group.title));
            пункты.forEach((section) => nav.appendChild(navLink(section)));
        });

        if (!isGuest()) {
            renderRecent(nav);
        }
        setActiveNav(state.route ? state.route.name : 'board');
    }

    function navLink(section) {
        const link = h('a', {
            href: section.href,
            dataset: { route: section.route },
            title: section.title,
        }, icon(section.icon), h('span', {}, section.title));
        if (section.count) {
            link.appendChild(h('b', {
                class: 'side-count', hidden: true,
                dataset: { count: section.count },
            }));
        }
        return link;
    }

    /**
     * Шапка меню: главное действие и вход в поиск.
     *
     * Работа отдела начинается с письма — значит, кнопка «Зарегистрировать»
     * должна быть там, где её ищут не глядя, а не третьей в ряду на экране
     * писем. Поиск рядом с ней, с подписью сочетания клавиш: человек,
     * увидевший «Ctrl K» один раз, дальше пользуется им, а не мышью.
     */
    function buildNavHead() {
        const голова = h('div', { class: 'side-head' });
        if (canRegister()) {
            голова.appendChild(h('a', {
                class: 'btn btn--primary side-new',
                href: '#/cases',
                title: 'Зарегистрировать входящее письмо',
                onclick: () => { casesState.pendingNew = true; },
            }, icon('plus'), h('span', {}, 'Новое письмо')));
        }
        голова.appendChild(h('button', {
            class: 'side-search',
            type: 'button',
            title: 'Поиск по системе (Ctrl+K)',
            onclick: () => openPalette(),
        }, icon('search'), h('span', {}, 'Поиск'), h('kbd', {}, 'Ctrl K')));
        return голова;
    }

    //: Куда человек заходил в последний раз. Хранится у него в браузере:
    //: список личный, на сервере ему делать нечего.
    const RECENT_KEY = 'reportgen.recent';
    const RECENT_MAX = 4;

    function recentList() {
        try {
            const сырое = JSON.parse(localStorage.getItem(RECENT_KEY) || '[]');
            return Array.isArray(сырое) ? сырое.filter((item) => item && item.href) : [];
        } catch (error) {
            return [];
        }
    }

    /** Запомнить открытое: письмо или разговор, по названию и адресу. */
    function rememberRecent(href, title) {
        if (!href || !title) return;
        const список = recentList().filter((item) => item.href !== href);
        список.unshift({ href: href, title: String(title).slice(0, 80) });
        try {
            localStorage.setItem(RECENT_KEY, JSON.stringify(список.slice(0, RECENT_MAX)));
        } catch (error) { /* приватный режим — обойдёмся без списка */ }
        const nav = $('#nav');
        if (nav) renderRecent(nav);
    }

    function renderRecent(nav) {
        const прежнее = nav.querySelector('.side-recent');
        if (прежнее) прежнее.remove();
        const прежняя = nav.querySelector('.side-group--recent');
        if (прежняя) прежняя.remove();
        const список = recentList();
        if (!список.length) return;
        nav.appendChild(h('div', { class: 'side-group side-group--recent' }, 'Недавнее'));
        nav.appendChild(h('div', { class: 'side-recent' }, список.map((item) =>
            h('a', { href: item.href, title: item.title },
                icon('clock'), h('span', {}, item.title)))));
    }

    /** Показать счётчик у раздела: сколько писем в работе и сколько просрочено. */
    function setNavCount(name, value, late) {
        const badge = $('#nav .side-count[data-count="' + name + '"]');
        if (!badge) return;
        const number = Number(value) || 0;
        badge.hidden = number === 0;
        badge.textContent = String(number);
        badge.classList.toggle('is-late', !!late);
        badge.title = late ? 'из них просрочено: ' + late : '';
    }

    /** Название приложения. Оно одно на всю систему и живёт в настройках.
     *
     * Распоряжение начальника отдела: назвать приложение нейтрально и убрать
     * знак отовсюду. Название по умолчанию ничего не сообщает об
     * организации; своё ставится настройкой brand_name без правки кода.
     */
    function brandName() {
        const brand = (state.config && state.config.brand) || {};
        return brand.name || 'Рабочее место';
    }

    // =====================================================================
    // 4а. Уведомления
    // =====================================================================

    /* Что человеку нужно знать: начальник вернул отчёт, письмо назначили на
       вас, вас вызывают в кабинет, пришло сообщение.

       Машина изолирована — ни почты, ни телефона, — и единственное место,
       куда можно положить «вам сообщение», это та же база. Экран спрашивает
       её раз в двадцать секунд: постоянного соединения в проекте нет и
       заводить его ради колокольчика незачем.

       Звук делаем сами через Web Audio: файла со звонком нет и быть не
       может — ни одной внешней загрузки в системе. Звучит только громкое:
       вызов в кабинет и возврат отчёта. Остальное ждёт молча. */

    /* Как часто спрашиваем про новое.

       Было двадцать секунд, и человек жаловался справедливо: сообщение
       написали, а уведомление приходит через полминуты. Запрос дешёвый —
       выборка по своим уведомлениям, — поэтому на виду спрашиваем раз в пять
       секунд. Свёрнутое окно опрашиваем реже: там браузер всё равно тормозит
       таймеры фоновых вкладок, а рабочий стол получит уведомление и с
       задержкой. */
    const NOTICE_POLL_MS = 5000;
    const NOTICE_POLL_HIDDEN_MS = 30000;
    const NOTICE_ICON = {
        'report.rework': '!',
        'report.review': '→',
        'report.approved': '✓',
        'case.assigned': '✉',
        'case.note': '…',
        'case.sent': '✓',
        'call': '☎',
        'message': '✉',
        'user.approved': '✓',
    };

    const notices = { items: [], unseen: 0, messages: 0, timer: null,
                      seenLoud: 0, filter: 'all' };

    /* Звук — свойство рабочего места, а не учётной записи: в аппаратной
       он нужен, в кабинете рядом со спящим начальником — нет, и это не
       повод носить настройку за собой на другую машину. Поэтому храним
       её в браузере. По умолчанию звук включён: человек, которому он
       мешает, его выключит, а тот, кто о нём не знает, пропустит вызов. */
    function soundOn() {
        return storageGet('rg-notice-sound', '1') !== '0';
    }

    function setSoundOn(on) {
        storageSet('rg-notice-sound', on ? '1' : '0');
    }

    /* Громкость. Сигнал звучал на одной десятой мощности — в аппаратной, где
       гудят стойки, его попросту не было слышно. Теперь громкость выставляет
       человек, и по умолчанию она полная: тот, кому громко, убавит, а тот,
       кто о настройке не знает, вызов не пропустит. */
    const SOUND_LOUDEST = 0.9;

    function soundLevel() {
        const raw = Number(storageGet('rg-notice-volume', '100'));
        if (!isFinite(raw)) return 1;
        return Math.min(1, Math.max(0, raw / 100));
    }

    function setSoundLevel(percent) {
        storageSet('rg-notice-volume', String(Math.round(percent)));
    }

    /** Короткий сигнал. Ни файла, ни библиотеки: два тона встроенным синтезом. */
    /* Звук уведомления. Браузер не даёт странице звучать, пока человек её не
       тронул: свежесозданный AudioContext стоит «приостановленным», и всё,
       что в него расписали, уходит в тишину. Поэтому контекст держим один,
       будим его первым же касанием страницы и на всякий случай будим ещё раз
       перед самим сигналом. */
    let audioCtx = null;

    function wakeAudio() {
        const Audio = window.AudioContext || window.webkitAudioContext;
        if (!Audio) return null;
        try {
            if (!audioCtx) audioCtx = new Audio();
            if (audioCtx.state === 'suspended') audioCtx.resume();
        } catch (error) {
            audioCtx = null;      // звук — вещь необязательная
        }
        return audioCtx;
    }

    function armAudio() {
        // Одного касания хватает на весь сеанс — дальше слушать незачем.
        const once = { once: true, passive: true };
        ['pointerdown', 'keydown'].forEach((name) =>
            document.addEventListener(name, wakeAudio, once));
    }

    /* Уведомление на рабочем столе, когда окно свёрнуто.

       Браузер показывает такие уведомления только «защищённой» странице:
       https или localhost. Отдел работает по http на адрес машины в сети,
       и для клиентских мест это условие не выполняется — окна Notification
       там нет вовсе. Поэтому: где можно — показываем, где нельзя — честно
       говорим об этом в настройке и не притворяемся, что работает.

       Что работает всегда, при любом браузере и любом адресе, — счётчик в
       заголовке вкладки: свёрнутое окно в панели задач само показывает
       «(3) РМ» — сокращённое название из настроек с числом непрочитанного
       впереди, и это видно, не разворачивая. */
    function deskAllowed() {
        // Решает НЕ наличие window.Notification, а защищённость страницы, и
        // это не придирка. Firefox по http объект Notification прячет, а
        // Chrome и Edge — оставляют: проверка «есть ли объект» в них
        // проходила, отметка в настройках выглядела рабочей, разрешение
        // «выдавалось», а окон не было никогда. Отдел это и получил:
        // «уведомления на рабочем столе отсутствуют даже при включённом
        // разрешении».
        //
        // isSecureContext истинно для https и для localhost — то есть ровно
        // там, где браузер вообще согласен показывать такие окна.
        return typeof window.Notification === 'function'
            && window.isSecureContext === true;
    }

    /** Почему окна на рабочем столе нет. Пусто — оно доступно. */
    function deskTrouble() {
        if (typeof window.Notification !== 'function') {
            return 'этот браузер таких уведомлений не показывает вовсе';
        }
        if (window.isSecureContext !== true) {
            return 'страница открыта по обычному адресу (http). Окно на '
                + 'рабочем столе браузер показывает только защищённой '
                + 'странице — https или адресу самой машины. Разрешение в '
                + 'настройках браузера искать не нужно: по этому адресу его '
                + 'там нет вовсе';
        }
        if (window.Notification.permission === 'denied') {
            return 'браузер отказал в уведомлениях для этого адреса — '
                + 'разрешите их в его настройках';
        }
        if (window.Notification.permission !== 'granted') {
            return 'разрешение у браузера ещё не спрошено';
        }
        return '';
    }

    function deskOn() {
        return deskAllowed() && storageGet('rg-notice-desk', '1') !== '0'
            && window.Notification.permission === 'granted';
    }

    function setDeskOn(on) {
        storageSet('rg-notice-desk', on ? '1' : '0');
    }

    async function askDesk() {
        if (!deskAllowed()) return 'unavailable';
        if (window.Notification.permission === 'granted') return 'granted';
        try {
            return await window.Notification.requestPermission();
        } catch (error) {
            return 'denied';
        }
    }

    function showDesk(item) {
        // Показываем только когда окно не на виду: иначе получается два
        // уведомления об одном — на экране и рядом с ним.
        if (!deskOn() || !document.hidden) return;
        try {
            const note = new window.Notification(
                (item.title || 'Уведомление') + ' — ' + brandShort(),
                { body: item.text || '', tag: 'rg-' + (item.id || ''),
                  lang: 'ru', renotify: false });
            note.onclick = () => {
                window.focus();
                if (item.link) location.hash = item.link;
                note.close();
            };
            setTimeout(() => note.close(), 15000);
        } catch (error) {
            /* уведомление на столе — удобство, а не условие работы */
        }
    }

    /** Короткое название отдела для заголовка вкладки и уведомлений. */
    function brandShort() {
        const brand = (state.config && state.config.brand) || {};
        return String(brand.short || brand.name || 'РМ');
    }

    /* Счётчик непрочитанного в заголовке вкладки. Свёрнутое окно показывает
       заголовок в панели задач — и «(3)» там видно, не разворачивая. */
    let titleBase = '';

    function paintTitle(count) {
        if (!titleBase) titleBase = document.title || brandShort();
        // Пока мигает срочное, заголовок держит тревога: обычный счётчик
        // вернётся сам, когда человек прочтёт.
        if (alarm.timer) return;
        document.title = count > 0 ? '(' + count + ') ' + titleBase : titleBase;
    }

    /* Срочное, когда окно свёрнуто.

       Окно уведомления Windows браузер показывает только защищённой
       странице — https или адрес самой машины. Отдел работает по http на
       адрес в сети, и на рабочих местах такого окна нет вовсе. Значит,
       достучаться надо тем, что работает ВЕЗДЕ и всегда:

       * заголовок вкладки. Свёрнутое окно показывает его в панели задач, и
         мигающая надпись «ВЫЗОВ В КАБИНЕТ» видна там, не разворачивая;
       * звук. Он играет и при свёрнутом окне — лишь бы вкладка была открыта.
         Один сигнал можно прослушать, поэтому срочное повторяется, пока
         человек не вернётся к окну, но не больше десятка раз: сигнализация,
         которая воет вечно, кончается выключенным звуком.

       Оба способа не требуют ни https, ни разрешений, ни установки чего бы
       то ни было на рабочем месте. */
    const ALARM_BLINK_MS = 1100;
    const ALARM_SOUND_EVERY = 8;             // тактов между сигналами
    const ALARM_MAX_SOUNDS = 10;

    const alarm = { timer: null, text: '', ticks: 0, sounds: 0, показ: false };

    function startAlarm(text, показ) {
        stopAlarm();
        if (!titleBase) titleBase = document.title || brandShort();
        alarm.text = String(text || 'СРОЧНОЕ').toUpperCase();
        alarm.ticks = 0;
        alarm.sounds = 0;
        // Показ по просьбе человека («Проверить вызов»): он смотрит на экран,
        // и останавливаться из-за этого нельзя — иначе проверять нечего.
        alarm.показ = Boolean(показ);
        playAlert();
        alarm.sounds += 1;
        alarm.timer = setInterval(() => {
            if (alarm.показ && alarm.ticks >= 6) {
                stopAlarm();
                paintTitle(notices.unseen);
                return;
            }
            // Человек вернулся к окну — он уже видит карточку, дальше выть
            // незачем.
            if (!alarm.показ && !document.hidden) {
                stopAlarm();
                paintTitle(notices.unseen);
                return;
            }
            alarm.ticks += 1;
            document.title = (alarm.ticks % 2)
                ? '‼ ' + alarm.text
                : titleBase;
            if (alarm.ticks % ALARM_SOUND_EVERY === 0
                    && alarm.sounds < ALARM_MAX_SOUNDS) {
                alarm.sounds += 1;
                playAlert();
            }
            if (alarm.sounds >= ALARM_MAX_SOUNDS
                    && alarm.ticks > ALARM_SOUND_EVERY * ALARM_MAX_SOUNDS) {
                stopAlarm();
                paintTitle(notices.unseen);
            }
        }, ALARM_BLINK_MS);
    }

    function stopAlarm() {
        if (alarm.timer) clearInterval(alarm.timer);
        alarm.timer = null;
        alarm.ticks = 0;
        alarm.sounds = 0;
        alarm.показ = false;
    }

    function playAlert() {
        if (!soundOn()) return;
        const ctx = wakeAudio();
        if (!ctx) return;
        const level = soundLevel();
        if (level <= 0) return;
        try {
            const now = ctx.currentTime;
            // Три тона вместо двух и треугольная волна вместо синуса: у
            // синуса нет обертонов, и в шуме аппаратной он тонет первым.
            const peak = Math.max(0.0002, SOUND_LOUDEST * level);
            [880, 1170, 1480].forEach((hz, index) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = 'triangle';
                osc.frequency.value = hz;
                // Резкий старт и мягкий спад: щелчка нет, а слышно сразу.
                gain.gain.setValueAtTime(0.0001, now + index * 0.16);
                gain.gain.exponentialRampToValueAtTime(peak, now + index * 0.16 + 0.02);
                gain.gain.exponentialRampToValueAtTime(0.0001, now + index * 0.16 + 0.15);
                osc.connect(gain).connect(ctx.destination);
                osc.start(now + index * 0.16);
                osc.stop(now + index * 0.16 + 0.17);
            });
        } catch (error) {
            /* звук — вещь необязательная: уведомление и так на экране */
        }
    }

    /* Когда именно. «Сегодня 18:45» человек читает мгновенно, а
       «01.09.2026 18:45» приходится сверять с календарём в голове. Полная
       дата остаётся подсказкой при наведении. */
    function fmtWhen(value) {
        const date = new Date(value);
        if (isNaN(date.getTime())) return fmtDateTime(value);
        const pad = (n) => String(n).padStart(2, '0');
        const clock = pad(date.getHours()) + ':' + pad(date.getMinutes());
        const day = new Date(date.getFullYear(), date.getMonth(), date.getDate());
        const now = new Date();
        const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        const days = Math.round((today - day) / 86400000);
        if (days === 0) return 'сегодня ' + clock;
        if (days === 1) return 'вчера ' + clock;
        if (days > 1 && days < 7) return days + ' дн. назад';
        return fmtDateTime(value);
    }

    /* «В сети» или «был в сети…».

       Обычный вопрос отдела — писать человеку сейчас или он ушёл и прочтёт
       завтра. Пока страница открыта, отметка обновляется сама, поэтому три
       минуты без неё — это уже «не в сети»: браузер закрыт или человек
       отошёл. Меньше брать нельзя: отметка пишется не чаще раза в минуту. */
    const ONLINE_WITHIN_MS = 3 * 60 * 1000;

    function lastSeen(value) {
        if (!value) return { text: 'ещё не заходил', online: false };
        const date = new Date(value.endsWith('Z') || value.includes('+')
            ? value : value + 'Z');
        if (isNaN(date.getTime())) return { text: '', online: false };
        const ago = Date.now() - date.getTime();
        if (ago < ONLINE_WITHIN_MS) return { text: 'в сети', online: true };
        const minutes = Math.round(ago / 60000);
        if (minutes < 60) return { text: 'был в сети ' + minutes + ' мин. назад', online: false };
        return { text: 'был в сети ' + fmtWhen(date.toISOString()), online: false };
    }

    /** Только часы и минуты: у реплики в переписке дата уже сказана выше. */
    function clockOf(value) {
        const date = new Date(value);
        if (isNaN(date.getTime())) return '';
        const pad = (n) => String(n).padStart(2, '0');
        return pad(date.getHours()) + ':' + pad(date.getMinutes());
    }

    /** Заголовок дня для списка уведомлений. */
    function whenGroup(value) {
        const date = new Date(value);
        if (isNaN(date.getTime())) return 'Ранее';
        const day = new Date(date.getFullYear(), date.getMonth(), date.getDate());
        const now = new Date();
        const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        const days = Math.round((today - day) / 86400000);
        if (days <= 0) return 'Сегодня';
        if (days === 1) return 'Вчера';
        if (days < 7) return 'На этой неделе';
        return 'Ранее';
    }

    async function pollNotices(loud) {
        if (!state.user) return;
        let data;
        try {
            data = await api.getGlobal('/api/notifications?limit=50');
        } catch (error) {
            return;                     // сеть моргнула — спросим через двадцать секунд
        }
        const fresh = (data.items || []).filter((item) => !item.seen && item.loud);
        const before = new Set(notices.items.map((item) => item.id));
        notices.items = data.items || [];
        notices.unseen = data.unseen || 0;
        notices.messages = data.messages || 0;
        paintBell();
        paintTitle(notices.unseen);
        if (!$('#notice-panel').hidden) paintNotices();

        // Звук и всплывающее — только на новое и только если это не первая
        // загрузка страницы: заходить утром под звонок недельной давности
        // человеку незачем.
        if (!loud) {
            notices.seenLoud = fresh.length ? fresh[0].id : notices.seenLoud;
            return;
        }
        const arrived = notices.items.filter(
            (item) => !item.seen && !before.has(item.id));
        arrived.slice(0, 3).reverse().forEach((item) => liveNotice(item));
        // Окно свёрнуто — карточку над колокольчиком человек не увидит.
        // Значит, уведомление показывает рабочий стол, а счётчик в заголовке
        // вкладки видно прямо в панели задач.
        if (document.hidden) arrived.slice(0, 3).forEach((item) => showDesk(item));
        const newest = fresh.length ? fresh[0].id : 0;
        if (newest && newest > notices.seenLoud) {
            // Окно свёрнуто — поднимаем тревогу заголовком и повторным
            // сигналом: это работает по любому адресу, без https. Окно на
            // виду — довольно одного сигнала, человек и так смотрит.
            if (document.hidden) startAlarm(alarmWord(fresh[0]));
            else playAlert();
        }
        if (newest > notices.seenLoud) notices.seenLoud = newest;
    }

    /* Что мигает в панели задач.

       Место там узкое, а взгляд по нему скользит мельком, поэтому первое
       слово должно говорить, ЧТО случилось: «ВЫЗОВ» или «ОТЧЁТ ВЕРНУЛИ».
       Кто вызывает — вторым, если помещается: «ВЫЗОВ: НИКИТИН В. П.» человек
       понимает целиком, не разворачивая окна. */
    function alarmWord(item) {
        const title = String((item && item.title) || '');
        const низом = title.toLowerCase();
        if (низом.indexOf('вызыва') !== -1 || низом.indexOf('кабинет') !== -1) {
            const кто = title.replace(/^[Вв]ас вызывает\s*/, '').trim();
            return кто ? 'ВЫЗОВ: ' + кто : 'ВЫЗОВ В КАБИНЕТ';
        }
        if (низом.indexOf('доработ') !== -1 || низом.indexOf('вернул') !== -1) {
            return 'ОТЧЁТ ВЕРНУЛИ';
        }
        return title || 'Срочное';
    }

    /* Карточка пришедшего уведомления. Всплывает над колокольчиком и уходит
       сама: перебивать работу окном ради «письмо передано вам» нельзя, а
       промолчать — значит заставить человека открывать список наугад. */
    function liveNotice(item) {
        const box = $('#toasts');
        if (!box) return;
        const card = h('div', {
            class: 'live-notice' + (item.loud ? ' is-loud' : ''),
            onclick: () => {
                if (!item.link) return;
                api.post('/api/notifications/read', { id: item.id }).catch(() => {});
                card.remove();
                navigate(item.link);
                pollNotices(false);
            },
        },
            h('span', { class: 'notice-mark kind-' + noticeTone(item) },
                NOTICE_ICON[item.kind] || '•'),
            h('div', { class: 'live-notice-body' },
                h('b', {}, item.title),
                item.body ? h('div', { class: 'small' }, item.body) : null,
                item.link ? h('div', { class: 'small faint' }, 'Открыть') : null),
            h('button', {
                class: 'close', title: 'Убрать',
                onclick: (event) => { event.stopPropagation(); card.remove(); },
            }, '×'));
        box.appendChild(card);
        // Громкое держим дольше: возврат отчёта и вызов в кабинет человек
        // должен успеть прочитать, даже если отвернулся к бумагам.
        setTimeout(() => card.remove(), item.loud ? 15000 : 8000);
    }

    /** Каким цветом уведомление: тревожное, доброе или обычное. */
    function noticeTone(item) {
        if (item.kind === 'call' || item.kind === 'report.rework') return 'alarm';
        if (item.kind === 'report.approved' || item.kind === 'case.sent'
            || item.kind === 'user.approved') return 'good';
        return 'plain';
    }

    function paintBell() {
        const dock = $('#dock');
        const bell = $('#bell');
        const count = $('#bell-count');
        if (!dock || !bell || !count) return;
        dock.hidden = !state.user;
        document.body.classList.toggle('has-dock', !!state.user);
        const total = (notices.unseen || 0) + (notices.messages || 0);
        count.hidden = !total;
        count.textContent = total > 99 ? '99+' : String(total);
        const loud = notices.items.some((item) => !item.seen && item.loud);
        bell.classList.toggle('has-loud', loud);
        bell.classList.toggle('has-new', !!total);
        bell.title = total ? 'Уведомлений: ' + total : 'Уведомлений нет';
    }

    function toggleNotices(open) {
        const panel = $('#notice-panel');
        const bell = $('#bell');
        if (!panel) return;
        const show = open === undefined ? panel.hidden : open;
        panel.hidden = !show;
        if (bell) bell.setAttribute('aria-expanded', show ? 'true' : 'false');
        if (show) {
            paintNotices();
            // Открытый список сам себя закрывает щелчком мимо и Escape —
            // так ведёт себя всё всплывающее, и рука это уже знает.
            setTimeout(() => document.addEventListener('pointerdown', outsideNotices), 0);
            document.addEventListener('keydown', escNotices);
        } else {
            document.removeEventListener('pointerdown', outsideNotices);
            document.removeEventListener('keydown', escNotices);
        }
    }

    function outsideNotices(event) {
        const dock = $('#dock');
        if (dock && !dock.contains(event.target)) toggleNotices(false);
    }

    function escNotices(event) {
        if (event.key === 'Escape') toggleNotices(false);
    }

    function paintNotices() {
        const panel = $('#notice-panel');
        if (!panel) return;
        const shown = notices.filter === 'new'
            ? notices.items.filter((item) => !item.seen)
            : notices.items;

        const list = h('div', { class: 'notice-list' });
        if (!shown.length) {
            list.appendChild(h('div', { class: 'notice-empty' },
                h('div', { class: 'notice-empty-mark' }, '✓'),
                h('b', {}, notices.filter === 'new'
                    ? 'Всё прочитано' : 'Уведомлений нет'),
                h('div', { class: 'small muted' },
                    'Сюда придёт возврат отчёта, вызов в кабинет, '
                    + 'сообщение и примечание к письму.')));
        } else {
            let group = '';
            shown.forEach((item) => {
                const title = whenGroup(item.created_at);
                if (title !== group) {
                    group = title;
                    list.appendChild(h('div', { class: 'notice-day' }, title));
                }
                list.appendChild(noticeRow(item));
            });
        }

        clear(panel);
        append(panel, [
            h('div', { class: 'notice-head' },
                h('b', { class: 'grow' }, 'Уведомления'),
                h('button', {
                    // Кнопка снимает и непрочитанные сообщения бесед: в числе
                    // у колокольчика они считаются наравне с уведомлениями, а
                    // уведомление о сообщении можно прочесть и удалить, не
                    // открыв беседу, — и тогда число висело, снять его было
                    // нечем.
                    class: 'btn btn--icon btn--sm',
                    title: 'Отметить прочитанным всё, включая сообщения бесед',
                    disabled: !notices.unseen && !notices.messages,
                    onclick: async () => {
                        await api.post('/api/notifications/read', {});
                        await pollNotices(false);
                        paintNotices();
                    },
                }, iconGlyph('check')),
                h('button', {
                    class: 'btn btn--icon btn--sm btn--danger-hover', title: 'Очистить список',
                    disabled: !notices.items.length,
                    onclick: async () => {
                        await api.del('/api/notifications');
                        notices.items = [];
                        notices.unseen = 0;
                        paintBell();
                        paintNotices();
                    },
                }, iconGlyph('trash')),
                h('button', {
                    class: 'btn btn--icon btn--sm', title: 'Закрыть',
                    onclick: () => toggleNotices(false),
                }, '×')),
            notices.messages
                // Число у колокольчика складывается из двух источников, и
                // второго в этом списке не видно. Тогда человек читает всё,
                // что видит, а число остаётся — и убрать его нечем.
                ? h('button', {
                    class: 'notice notice--link kind-info',
                    onclick: () => { toggleNotices(false); navigate('#/talks'); },
                },
                    h('span', { class: 'notice-mark kind-info' }, '✉'),
                    h('div', { class: 'notice-body' },
                        h('b', {}, 'Непрочитанных сообщений в беседах: '
                            + notices.messages),
                        h('div', { class: 'small' },
                            'Они тоже входят в число у колокольчика. '
                            + 'Щёлкните, чтобы открыть беседы.')))
                : null,
            h('div', { class: 'notice-tabs' },
                ['all', 'new'].map((key) => h('button', {
                    class: 'chip' + (notices.filter === key ? ' is-active' : ''),
                    onclick: () => { notices.filter = key; paintNotices(); },
                }, key === 'all' ? 'Все' : 'Непрочитанные'
                    + (notices.unseen ? ' · ' + notices.unseen : ''))),
                h('span', { class: 'grow' }),
                h('button', {
                    class: 'chip', title: 'Звук и что приходит со звуком',
                    onclick: () => openNoticeSettings(),
                }, soundOn() ? '🔔 звук' : '🔕 без звука')),
            list,
        ]);
    }

    /* Что приходит со звуком и как его выключить. Настройка одна, но без
       неё человек не знает ни того, что звук вообще есть, ни того, что его
       можно убрать: и то и другое кончается выключенными колонками. */
    function openNoticeSettings() {
        const toggle = h('input', { type: 'checkbox', checked: soundOn() });
        const level = h('input', {
            type: 'range', min: '0', max: '100', step: '5',
            value: String(Math.round(soundLevel() * 100)),
            class: 'volume',
            oninput: () => { levelText.textContent = level.value + ' %'; },
        });
        const levelText = h('span', { class: 'small mono nowrap' },
            Math.round(soundLevel() * 100) + ' %');
        const test = h('button', {
            class: 'btn btn--sm',
            onclick: () => {
                if (!toggle.checked) {
                    toast('Звук выключен — включите отметку выше', 'error');
                    return;
                }
                // Проверка звонит мимо настройки и на той громкости, что
                // сейчас на ползунке: человек нажал именно затем, чтобы
                // услышать, как будет звучать.
                const wasOn = soundOn();
                const wasLevel = Math.round(soundLevel() * 100);
                setSoundOn(true);
                setSoundLevel(Number(level.value));
                playAlert();
                setSoundOn(wasOn);
                setSoundLevel(wasLevel);
            },
        }, 'Проверить звук');

        // Уведомление на рабочем столе. Показать его может только
        // «защищённая» страница — https или localhost. Отдел работает по
        // http на адрес машины в сети, поэтому на клиентских местах такого
        // окна у браузера нет вовсе, и врать об этом нельзя.
        const desk = h('input', {
            type: 'checkbox',
            checked: deskOn(),
            onchange: async () => {
                if (!desk.checked) return;
                const answer = await askDesk();
                if (answer !== 'granted') {
                    desk.checked = false;
                    toast('Окна на рабочем столе не будет: ' + (deskTrouble()
                        || 'браузер отказал'), 'error', 9000);
                }
            },
        });

        // Проверка НАСТОЯЩИМ уведомлением. Без неё человек ставит отметку,
        // видит, что она встала, и уходит в уверенности, что теперь работает.
        // Окно на рабочем столе браузер показывает только свёрнутой вкладке,
        // поэтому сперва отсчёт: успеть переключиться.
        const пробаОкна = h('button', {
            class: 'btn btn--sm',
            onclick: async () => {
                const беда = deskTrouble();
                if (беда && window.Notification.permission !== 'granted') {
                    const ответ = await askDesk();
                    if (ответ !== 'granted') {
                        toast('Окна не будет: ' + (deskTrouble() || 'браузер '
                              + 'отказал'), 'error', 9000);
                        return;
                    }
                }
                let осталось = 5;
                пробаОкна.disabled = true;
                toast('Сверните окно — уведомление придёт через 5 с', 'ok', 6000);
                const тик = setInterval(() => {
                    осталось -= 1;
                    пробаОкна.textContent = 'Проверка… ' + осталось;
                    if (осталось > 0) return;
                    clearInterval(тик);
                    пробаОкна.disabled = false;
                    пробаОкна.textContent = 'Проверить окно на столе';
                    try {
                        const окно = new window.Notification(
                            'Проверка связи — ' + brandShort(),
                            { body: 'Если вы это видите, уведомления работают.',
                              tag: 'rg-proba', lang: 'ru' });
                        setTimeout(() => окно.close(), 10000);
                    } catch (error) {
                        toast('Браузер не дал показать окно: ' + error, 'error');
                    }
                }, 1000);
            },
        }, 'Проверить окно на столе');

        // Показать, как выглядит вызов. Человеку, у которого окно Windows
        // недоступно, нужно своими глазами увидеть, что вместо него: иначе он
        // идёт искать разрешение в настройках браузера, где его нет.
        const проба = h('button', {
            class: 'btn btn--sm',
            onclick: () => {
                startAlarm('ВЫЗОВ: ' + ((state.user || {}).short_name || 'НИКИТИН В. П.'),
                           true);
                toast('Смотрите на заголовок вкладки и в панель задач', 'ok', 7000);
            },
        }, 'Проверить вызов');

        const loud = [
            ['Отчёт вернули на доработку', true],
            ['Вас вызывают в кабинет', true],
            ['Сообщение в беседе', false],
            ['Примечание к письму', false],
            ['Отчёт сдан на проверку', false],
            ['Отчёт проверен', false],
            ['Ответ по письму отправлен', false],
            ['Письмо передано вам', false],
            ['Заявка на доступ одобрена', false],
        ];

        const dialog = openModal({
            title: 'Уведомления',
            narrow: true,
            body: [
                h('label', { class: 'check-line' }, toggle,
                    h('span', {},
                        h('b', {}, 'Звук'),
                        h('div', { class: 'small muted' },
                            'Короткий сигнал на срочное. Настройка держится '
                            + 'на этой машине: в аппаратной звук нужен, '
                            + 'в кабинете — не всегда.'))),
                h('label', { class: 'field field--row' },
                    h('span', { class: 'small' }, 'Громкость'),
                    level, levelText),
                h('div', { class: 'toolbar' }, h('span', { class: 'grow' }), test),
                // Мёртвого переключателя быть не должно. Там, где окна
                // Windows нет, человек видит не отключённую отметку, а
                // объяснение и кнопку проверки: иначе он идёт искать
                // разрешение в настройках браузера, где его нет вовсе.
                deskAllowed()
                    ? h('div', {},
                        h('label', { class: 'check-line' }, desk,
                            h('span', {},
                                h('b', {}, 'Уведомление на рабочем столе'),
                                h('div', { class: 'small muted' },
                                    'Когда окно свёрнуто, уведомление покажет '
                                    + 'сам Windows. Браузер спросит разрешение '
                                    + 'один раз.'))),
                        h('div', { class: 'toolbar' },
                            h('span', { class: 'grow' }), пробаОкна))
                    : h('div', { class: 'card card-pad' },
                        h('b', {}, 'Окно Windows поверх других: здесь недоступно'),
                        h('div', { class: 'small muted' },
                            'Причина: ' + deskTrouble() + '.'),
                        h('div', { class: 'small muted' },
                            'Разрешение в настройках браузера искать не нужно: '
                            + 'по этому адресу его там нет вовсе — ни в Firefox, '
                            + 'ни в Chrome. Ставить на эту машину тоже ничего не '
                            + 'надо.'),
                        h('div', { class: 'small' },
                            'Вместо окна вас найдёт вот что: при свёрнутом окне '
                            + 'в панели задач мигает «‼ ВЫЗОВ: ФАМИЛИЯ», а '
                            + 'сигнал повторяется, пока вы не вернётесь.'),
                        h('div', { class: 'toolbar' },
                            h('span', { class: 'grow' }), проба)),
                h('div', { class: 'card-title' }, 'Что приходит'),
                h('div', { class: 'notice-kinds' }, loud.map((pair) =>
                    h('div', { class: 'notice-kind' },
                        h('span', {}, pair[0]),
                        pair[1]
                            ? h('span', { class: 'badge badge--warn' }, 'со звуком')
                            : h('span', { class: 'small faint' }, 'молча')))),
                h('div', { class: 'small muted' },
                    'Звонить по каждому поводу — верный способ, чтобы звук '
                    + 'выключили насовсем. Поэтому громких всего два.'),
                h('div', { class: 'small muted' },
                    'Громкое при свёрнутом окне мигает в панели задач и '
                    + 'повторяет сигнал до десяти раз, пока вы не вернётесь к '
                    + 'окну. Это работает по любому адресу, ничего не требует '
                    + 'ни от браузера, ни от вашей машины и не просит ничего '
                    + 'устанавливать.'),
            ],
            footer: [
                h('button', {
                    class: 'btn btn--primary',
                    onclick: () => {
                        setSoundOn(toggle.checked);
                        setSoundLevel(Number(level.value));
                        setDeskOn(desk.checked);
                        dialog.close();
                        paintNotices();
                        toast(toggle.checked
                            ? 'Звук включён, громкость ' + level.value + ' %'
                            : 'Звук выключен', 'ok');
                    },
                }, 'Сохранить'),
                h('button', { class: 'btn', onclick: () => dialog.close() }, 'Отмена'),
            ],
        });
    }

    function noticeRow(item) {
        const open = async () => {
            if (!item.seen) {
                await api.post('/api/notifications/read', { id: item.id });
            }
            if (item.link) {
                toggleNotices(false);
                navigate(item.link);
            }
            await pollNotices(false);
            paintNotices();
        };
        return h('button', {
            class: 'notice kind-' + noticeTone(item) + (item.seen ? '' : ' is-new'),
            title: fmtDateTime(item.created_at)
                + (item.link ? ' · щёлкните, чтобы открыть' : ''),
            onclick: open,
        },
            h('span', { class: 'notice-mark kind-' + noticeTone(item) },
                NOTICE_ICON[item.kind] || '•'),
            h('div', { class: 'notice-body' },
                h('b', {}, item.title),
                item.body ? h('div', { class: 'small' }, item.body) : null,
                h('div', { class: 'small faint' },
                    fmtWhen(item.created_at)
                    + (item.from_name ? ' · ' + item.from_name : ''))),
            item.seen ? null : h('span', { class: 'notice-dot', title: 'Не прочитано' }));
    }

    function startNotices() {
        const bell = $('#bell');
        if (bell && !bell.dataset.ready) {
            bell.dataset.ready = '1';
            bell.onclick = () => toggleNotices();
        }
        if (notices.timer) return;
        armAudio();
        // Первый опрос — молча: человек только вошёл, звонить ему нечем.
        pollNotices(false);
        // Свёрнутое окно спрашиваем реже, развёрнутое — чаще. И спрашиваем
        // сразу же, как человек вернулся к окну: он мог отойти на час, и
        // ждать ещё пять секунд ради того, что уже случилось, незачем.
        let hiddenTicks = 0;
        notices.timer = setInterval(() => {
            if (!document.hidden) {
                hiddenTicks = 0;
                pollNotices(true);
                return;
            }
            hiddenTicks += NOTICE_POLL_MS;
            if (hiddenTicks >= NOTICE_POLL_HIDDEN_MS) {
                hiddenTicks = 0;
                pollNotices(true);
            }
        }, NOTICE_POLL_MS);
        document.addEventListener('visibilitychange', () => {
            if (document.hidden) return;
            stopAlarm();
            paintTitle(notices.unseen);
            pollNotices(true);
        });
    }

    /* ------------------------------------------------- поиск по системе ---

       Одна строка вместо блуждания по разделам: письмо по номеру, человек по
       фамилии, беседа, раздел. В отделе десяток людей и сотни писем, и путь
       «Письма → набор → поиск → строка» человек проходит по двадцать раз в
       день. Ctrl+K — общепринятое сочетание: тот, кто привык к нему в другой
       программе, попробует его и здесь.

       Ищем на сервере теми же маршрутами, что и разделы: своего второго
       поиска в браузере нет, иначе палитра находила бы не то же, что
       «Письма». Запрос отправляем не на каждую букву, а с задержкой —
       набирающий «ВХ-2026-0423» иначе шлёт двенадцать запросов подряд. */

    const CMD_DELAY_MS = 180;
    const cmd = { open: false, query: '', items: [], cursor: 0, seq: 0, timer: null };

    function cmdSections() {
        return SECTIONS
            .filter((section) => !section.adminOnly || isAdmin())
            .filter((section) => !isGuest() || section.route === 'chat')
            .map((section) => ({
                kind: 'Раздел', title: section.title, note: '',
                href: section.href, icon: section.icon,
            }));
    }

    function openPalette() {
        if (cmd.open) return;
        cmd.open = true;
        cmd.query = '';
        cmd.items = cmdSections();
        cmd.cursor = 0;

        const input = h('input', {
            type: 'text', class: 'cmd-input', autocomplete: 'off', spellcheck: false,
            placeholder: 'Письмо, человек, беседа, раздел…',
            oninput: () => schedule(input.value),
        });
        const list = h('div', { class: 'cmd-list' });
        const hint = h('div', { class: 'cmd-hint' },
            h('span', {}, h('kbd', {}, '↑'), h('kbd', {}, '↓'), ' выбрать'),
            h('span', {}, h('kbd', {}, 'Enter'), ' открыть'),
            h('span', {}, h('kbd', {}, 'Esc'), ' закрыть'),
            h('span', {}, h('kbd', {}, '?'), ' все клавиши'));

        const box = h('div', { class: 'cmd' },
            h('div', { class: 'cmd-field' },
                h('span', { class: 'cmd-mark' }, iconGlyph('search')),
                input),
            list, hint);
        const backdrop = h('div', { class: 'cmd-backdrop' }, box);

        function close() {
            cmd.open = false;
            if (cmd.timer) clearTimeout(cmd.timer);
            document.removeEventListener('keydown', onKey, true);
            backdrop.remove();
        }

        function schedule(text) {
            cmd.query = text;
            if (cmd.timer) clearTimeout(cmd.timer);
            cmd.timer = setTimeout(() => search(text), CMD_DELAY_MS);
        }

        async function search(text) {
            const mine = ++cmd.seq;
            const found = await paletteSearch(text);
            if (mine !== cmd.seq || !cmd.open) return;   // пришёл ответ на старый запрос
            cmd.items = found;
            cmd.cursor = 0;
            paint();
        }

        function paint() {
            clear(list);
            if (!cmd.items.length) {
                list.appendChild(h('div', { class: 'cmd-empty' },
                    cmd.query ? 'Ничего не нашлось по «' + cmd.query + '»'
                        : 'Наберите номер письма, фамилию или название раздела'));
                return;
            }
            let group = '';
            cmd.items.forEach((item, index) => {
                if (item.kind !== group) {
                    group = item.kind;
                    list.appendChild(h('div', { class: 'cmd-group' }, group));
                }
                list.appendChild(h('button', {
                    class: 'cmd-row' + (index === cmd.cursor ? ' is-active' : ''),
                    dataset: { index: String(index) },
                    onmousemove: () => {
                        if (cmd.cursor === index) return;
                        cmd.cursor = index;
                        paint();
                    },
                    onclick: () => go(item),
                },
                    h('span', { class: 'cmd-icon' },
                        item.icon ? icon(item.icon) : h('span', {}, item.glyph || '•')),
                    h('span', { class: 'cmd-text' },
                        h('b', {}, item.title),
                        item.note ? h('span', { class: 'small muted' }, item.note) : null)));
            });
            const active = list.querySelector('.cmd-row.is-active');
            if (active) active.scrollIntoView({ block: 'nearest' });
        }

        function go(item) {
            close();
            navigate(item.href);
        }

        function onKey(event) {
            if (event.key === 'Escape') {
                event.stopPropagation();
                close();
                return;
            }
            if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
                event.preventDefault();
                if (!cmd.items.length) return;
                const step = event.key === 'ArrowDown' ? 1 : -1;
                cmd.cursor = (cmd.cursor + step + cmd.items.length) % cmd.items.length;
                paint();
                return;
            }
            if (event.key === 'Enter' && cmd.items[cmd.cursor]) {
                event.preventDefault();
                go(cmd.items[cmd.cursor]);
            }
        }

        backdrop.addEventListener('mousedown', (event) => {
            if (event.target === backdrop) close();
        });
        document.addEventListener('keydown', onKey, true);
        $('#modal-root').appendChild(backdrop);
        paint();
        input.focus();
    }

    /** Что нашлось по строке: разделы, письма, люди, беседы. */
    async function paletteSearch(text) {
        const query = String(text || '').trim();
        const words = query.toLowerCase();
        const sections = cmdSections().filter(
            (item) => !words || item.title.toLowerCase().indexOf(words) !== -1);
        if (!query) return sections;

        const out = sections.slice();
        // Письма и людей спрашиваем разом: один медленный ответ не должен
        // задерживать другой.
        const [cases, people, talks] = await Promise.all([
            api.get('/api/cases?q=' + encodeURIComponent(query) + '&limit=6')
                .catch(() => ({ items: [] })),
            api.get('/api/board').catch(() => ({ people: [] })),
            api.get('/api/talks').catch(() => ({ items: [] })),
        ]);

        (cases.items || []).slice(0, 6).forEach((item) => out.push({
            kind: 'Письма', glyph: '✉',
            title: (item.incoming_no || item.case_id) + ' · ' + (item.title || 'без описания'),
            note: [item.assignee_name, CASE_STATUS[item.status] || item.status]
                .filter(Boolean).join(' · '),
            href: '#/case/' + item.id,
        }));

        (people.people || []).filter((person) =>
            (person.full_name || '').toLowerCase().indexOf(words) !== -1
            || (person.login || '').toLowerCase().indexOf(words) !== -1
        ).slice(0, 5).forEach((person) => out.push({
            kind: 'Военнослужащие', glyph: '☺',
            title: person.full_name || person.login,
            note: [person.role_title, person.team].filter(Boolean).join(' · '),
            // Человека открываем перепиской: это то, зачем его ищут чаще
            // всего. Личный состав и так рядом, в своём разделе.
            href: '#/talks?to=' + person.id,
        }));

        (talks.items || []).filter((item) =>
            talkTitle(item).toLowerCase().indexOf(words) !== -1
        ).slice(0, 4).forEach((item) => out.push({
            kind: 'Беседы', glyph: '✎',
            title: talkTitle(item),
            note: item.last_text || '',
            href: '#/talks/' + item.id,
        }));

        return out;
    }

    function armPalette() {
        const button = $('#cmd-open');
        if (button && !button.dataset.ready) {
            button.dataset.ready = '1';
            button.hidden = false;
            button.onclick = () => openPalette();
        }
        if (document.body.dataset.palette) return;
        document.body.dataset.palette = '1';
        document.addEventListener('keydown', (event) => {
            if (!state.user) return;
            const combo = (event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k';
            if (!combo) return;
            event.preventDefault();
            openPalette();
        });
    }

    /* ----------------------------------------------- шпаргалка клавиш ---

       Сочетаний в системе с десяток, и все они разбросаны по подписям
       кнопок: Ctrl+S знает тот, кто навёл мышь на «Сохранить». Клавиша «?»
       собирает их на одном листе — так принято в почте и трекерах, и там
       её пробуют первой. В поле ввода «?» — просто знак вопроса: вопрос
       помощнику им и заканчивается. */

    const КЛАВИШИ = [
        ['Везде', [
            [['Ctrl', 'K'], 'Поиск по системе: письмо, человек, беседа, раздел'],
            [['?'], 'Эта шпаргалка'],
            [['Esc'], 'Закрыть окно, выйти из режима чтения'],
        ]],
        ['Помощник', [
            [['Enter'], 'Отправить вопрос'],
            [['Shift', 'Enter'], 'Новая строка в вопросе'],
        ]],
        ['Отчёт по письму', [
            [['Ctrl', 'S'], 'Сохранить раздел или данные'],
            [['Ctrl', 'Enter'], 'Перегенерировать раздел'],
        ]],
        ['Беседы', [
            [['Ctrl', 'Enter'], 'Отправить сообщение'],
        ]],
    ];

    /** Набирает ли человек сейчас текст: там «?» — буква, а не команда. */
    function вводТекста(target) {
        if (!target || !target.closest) return false;
        return Boolean(target.closest('input, textarea, select, [contenteditable=""], [contenteditable="true"]'));
    }

    function шпаргалкаКлавиш() {
        if ($('.keys-sheet')) return;
        const body = h('div', { class: 'keys-sheet' }, КЛАВИШИ.map(([раздел, строки]) =>
            h('section', { class: 'keys-group' },
                h('h4', {}, раздел),
                строки.map(([клавиши, что]) => h('div', { class: 'keys-row' },
                    h('span', { class: 'keys-combo' }, клавиши.map((клавиша, i) => [
                        i ? h('span', { class: 'keys-plus' }, '+') : null,
                        h('kbd', {}, клавиша),
                    ])),
                    h('span', { class: 'keys-what' }, что))))));
        openModal({
            title: h('div', { class: 'modal-head keys-head' }, icon('keys'), 'Горячие клавиши'),
            body: body,
        });
    }

    document.addEventListener('keydown', (event) => {
        if (event.key !== '?' || event.ctrlKey || event.metaKey || event.altKey) return;
        if (!state.user || вводТекста(event.target)) return;
        if (cmd.open || $('.modal-backdrop')) return;
        event.preventDefault();
        шпаргалкаКлавиш();
    });

    /* Выход из режима чтения. Слушатель общий, как и у «?»: режим живёт на
       <body>, а не в разделе, и Esc должен снимать его откуда угодно. */
    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape' && document.body.classList.contains('reading')) {
            режимЧтения(false);
        }
    });

    function renderChrome() {
        const brand = (state.config && state.config.brand) || null;
        if (brand && brand.name) {
            const short = $('#brand-short');
            const full = $('#brand-name');
            if (short) short.textContent = brand.short || brand.name;
            if (full) full.textContent = brand.name;
            const home = $('.side-brand');
            if (home) home.title = brand.name
                + (brand.subtitle ? ' — ' + brand.subtitle : '');
            document.title = brand.name;
        }
        if (brand && typeof brand.accent === 'string' && /^#[0-9a-fA-F]{6}$/.test(brand.accent)) {
            applyBrandAccent(brand.accent);
        }

        // Модель — точка состояния. Пока состояние не выяснено, точка серая
        // и подписана «проверяем»: зелёная по умолчанию врала бы про
        // неподнятый llama-server, и инженер узнавал бы об этом, только
        // прождав минуту после первого вопроса.
        const dot = $('#llm-info');
        if (dot && !dot.dataset.asked) {
            dot.dataset.asked = '1';
            const llm = state.config.llm || {};
            dot.title = 'Проверяем сервер модели' + (llm.model ? ': ' + llm.model : '');
            api.getGlobal('/api/llm/status').then((data) => {
                dot.classList.toggle('is-up', !!data.available);
                dot.classList.toggle('is-down', !data.available);
                dot.title = (data.available
                    ? 'Модель отвечает'
                    : 'Сервер модели не отвечает — запустите start-llm.ps1') +
                    (data.model ? ': ' + data.model : '') +
                    (data.base_url ? ' (' + data.base_url + ')' : '');
            }).catch(() => {
                dot.title = 'Состояние сервера модели неизвестно';
            });
        }

        buildNav();
        // Уведомления гостю не приходят: писем, отчётов и вызовов в кабинет
        // у него нет. Колокол без содержимого — обещание, которое не
        // выполняется.
        if (!isGuest()) {
            startNotices();
            paintBell();
        } else {
            const bell = $('#bell');
            if (bell) bell.hidden = true;
        }
        armPalette();

        const chip = $('#user-chip');
        const logout = $('#logout-btn');
        if (state.user) {
            chip.hidden = false;
            const name = state.user.short_name || state.user.full_name
                || state.user.login;
            $('#user-name').textContent = name;
            $('#user-initials').textContent = initials(name);
            $('#user-role').textContent = roleLabel(state.user.role);
            if (isGuest()) {
                // Гостю личный кабинет не открывается: заводить объективку и
                // телефоны тому, кого в отделе нет, незачем. Ссылку убираем
                // совсем, а не делаем неработающей.
                chip.removeAttribute('href');
                chip.classList.add('user-chip--flat');
                chip.title = 'Гостевой вход: переписка с помощником не сохраняется';
            } else {
                chip.setAttribute('href', '#/me');
                chip.classList.remove('user-chip--flat');
                chip.title = (state.user.full_name || name) + ' — личный кабинет';
            }
        } else {
            chip.hidden = true;
        }
        logout.hidden = !state.authEnabled;
        logout.onclick = async () => {
            try {
                await api.post('/api/auth/logout', {});
            } catch (error) {
                /* выходим в любом случае */
            }
            location.href = '/login';
        };

        bindSidebar();
    }

    /** Инициалы для кружка рядом с именем: «Петров И. С.» → «ПИ». */
    function initials(name) {
        const words = String(name || '').trim().split(/[\s.]+/).filter(Boolean);
        if (!words.length) return '—';
        const first = words[0].charAt(0);
        const second = words.length > 1 ? words[1].charAt(0) : '';
        return (first + second).toUpperCase();
    }

    /* ---- цвет отдела в обеих темах -----------------------------------
     *
     * Цвет отдела приходит из настроек одним числом — тем, что годится для
     * белого листа. Прежде он ставился прямо на корневой узел стилем, а
     * стиль узла сильнее любого правила из файла: тёмная тема получала тот
     * же тёмно-синий, что и светлая, и активный пункт меню становился
     * синим по тёмно-синему. Замер в Chromium: 1,77:1 при норме 4,5:1 —
     * это не «плохо читается», это не читается.
     *
     * Поэтому шаг под тёмную панель считается, а не берётся. Тон отдела
     * сохраняется, светлота поднимается до той, на которой построена
     * тёмная палитра (#15507e → #5fa3dd), и результат проверяется на
     * контраст с тёмной панелью — пока не пройдёт норму. И ставится не
     * стилем узла, а правилами в обеих областях темы: и по настройке
     * системы, и по выбору человека.
     */

    /** hex → [тон 0..360, насыщенность 0..1, светлота 0..1]. */
    function hexToHsl(hex) {
        const n = parseInt(hex.slice(1), 16);
        const r = ((n >> 16) & 255) / 255;
        const g = ((n >> 8) & 255) / 255;
        const b = (n & 255) / 255;
        const max = Math.max(r, g, b);
        const min = Math.min(r, g, b);
        const l = (max + min) / 2;
        if (max === min) return [0, 0, l];
        const d = max - min;
        const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
        let h;
        if (max === r) h = ((g - b) / d + (g < b ? 6 : 0));
        else if (max === g) h = (b - r) / d + 2;
        else h = (r - g) / d + 4;
        return [h * 60, s, l];
    }

    function hslToHex(h, s, l) {
        const c = (1 - Math.abs(2 * l - 1)) * s;
        const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
        const m = l - c / 2;
        const шаг = Math.floor(((h % 360) + 360) % 360 / 60);
        const наборы = [[c, x, 0], [x, c, 0], [0, c, x], [0, x, c], [x, 0, c], [c, 0, x]];
        const [r, g, b] = наборы[шаг];
        const байт = (v) => {
            const число = Math.round((v + m) * 255);
            return (число < 16 ? '0' : '') + Math.max(0, Math.min(255, число)).toString(16);
        };
        return '#' + байт(r) + байт(g) + байт(b);
    }

    /** Относительная яркость по формуле WCAG. */
    function luminanceOf(hex) {
        const n = parseInt(hex.slice(1), 16);
        const канал = (v) => {
            const c = v / 255;
            return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
        };
        return 0.2126 * канал((n >> 16) & 255)
            + 0.7152 * канал((n >> 8) & 255)
            + 0.0722 * канал(n & 255);
    }

    function contrastOf(one, two) {
        const a = luminanceOf(one);
        const b = luminanceOf(two);
        return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
    }

    //: Тёмная панель, на которой стоит активный пункт меню (--accent-soft),
    //: и норма контраста для обычного текста.
    const DARK_SOFT = '#16283a';
    const TEXT_CONTRAST = 4.5;

    /** Шаг того же тона под тёмную панель: светлее, пока не станет читаемым. */
    function darkStepOf(hex) {
        const [h, s] = hexToHsl(hex);
        // Светлота тёмной палитры (#5fa3dd) — отправная точка, а не ответ:
        // у тона потемнее её может не хватить.
        for (let l = 0.62; l <= 0.86; l += 0.02) {
            const шаг = hslToHex(h, Math.max(s, 0.45), l);
            if (contrastOf(шаг, DARK_SOFT) >= TEXT_CONTRAST) return шаг;
        }
        return hslToHex(h, Math.max(s, 0.45), 0.86);
    }

    /** Осветлить или затемнить на долю светлоты — для наведения. */
    function shiftLightness(hex, delta) {
        const [h, s, l] = hexToHsl(hex);
        return hslToHex(h, s, Math.max(0, Math.min(1, l + delta)));
    }

    function applyBrandAccent(hex) {
        const светлый = hex.toLowerCase();
        const тёмный = darkStepOf(светлый);
        const правила = (accent, hover) =>
            '--accent: ' + accent + '; --accent-hover: ' + hover + ';';
        const текст = [
            ':root {' + правила(светлый, shiftLightness(светлый, -0.08)) + '}',
            '@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) {'
                + правила(тёмный, shiftLightness(тёмный, 0.08)) + '} }',
            ':root[data-theme="dark"] {'
                + правила(тёмный, shiftLightness(тёмный, 0.08)) + '}',
        ].join('\n');
        let узел = $('#brand-accent');
        if (!узел) {
            узел = h('style', { id: 'brand-accent' });
            document.head.appendChild(узел);
        }
        узел.textContent = текст;
    }

    function bindSidebar() {
        watchSideRail();
        const collapse = $('#side-btn');
        if (collapse && !collapse.dataset.bound) {
            collapse.dataset.bound = '1';
            collapse.onclick = () => {
                const min = !document.body.classList.contains('side-min');
                document.body.classList.toggle('side-min', min);
                storageSet('rg-side-min', min ? '1' : '0');
                collapse.title = min ? 'Развернуть меню' : 'Свернуть меню';
            };
        }
        const open = $('#side-open');
        if (open && !open.dataset.bound) {
            open.dataset.bound = '1';
            open.onclick = () => {
                const выдвинуто = document.body.classList.toggle('side-open');
                open.setAttribute('aria-expanded', выдвинуто ? 'true' : 'false');
            };
        }
        const scrim = $('#side-scrim');
        if (scrim && !scrim.dataset.bound) {
            scrim.dataset.bound = '1';
            scrim.onclick = () => closeSideDrawer();
        }
    }

    function roleLabel(role) {
        return ROLE_LABEL[role] || role;
    }

    function setActiveNav(name) {
        const section = SECTION_OF[name] || name;
        $$('#nav a').forEach((link) => {
            link.classList.toggle('is-active', link.dataset.route === section);
        });
        const chip = $('#user-chip');
        if (chip) chip.classList.toggle('is-active', name === 'me');
        const title = $('#topbar-title');
        if (title) {
            const found = SECTIONS.filter((item) => item.route === section)[0];
            title.textContent = name === 'me' ? 'Личный кабинет' : (found ? found.title : '');
        }
        // На узком экране меню закрывается сразу после выбора раздела.
        closeSideDrawer();
    }

    /* Меню живёт в трёх видах: полное, рельса из значков и выдвижной ящик.
       Рельса включается двумя путями — человек свернул меню сам или экран
       узок. Пути разные, вид один, и описан он один раз: класс side-min
       ставит кнопка, side-rail — вот этот наблюдатель, а правила оформления
       у них общие. Раньше узкий экран сжимал меню своим правилом, а подписи
       групп прятать забывал: от «Работы» оставалось «Рабо», от «Поиска» — «П».

       Ниже 900 px меню становится ящиком во всю ширину, и рельса снимается:
       в ящике подписи нужны. */
    const SIDE_RAIL = '(min-width: 901px) and (max-width: 1240px)';

    function watchSideRail() {
        let наблюдатель;
        try {
            наблюдатель = window.matchMedia(SIDE_RAIL);
        } catch (error) {
            return;
        }
        const применить = () => {
            document.body.classList.toggle('side-rail', наблюдатель.matches);
        };
        применить();
        if (наблюдатель.addEventListener) наблюдатель.addEventListener('change', применить);
        else if (наблюдатель.addListener) наблюдатель.addListener(применить);
    }

    /** Задвинуть меню на узком экране, не забыв сказать это читающему с экрана. */
    function closeSideDrawer() {
        document.body.classList.remove('side-open');
        const open = $('#side-open');
        if (open) open.setAttribute('aria-expanded', 'false');
    }

    // -- маршрутизация ------------------------------------------------------

    let currentHash = '#/board';
    let restoringHash = false;

    function parseHash(hash) {
        // Хвост «?to=5» отрезаем до разбора пути: он не часть адреса раздела,
        // а просьба открыть в нём что-то конкретное.
        const raw = String(hash || '').replace(/^#\/?/, '');
        const cut = raw.indexOf('?');
        const query = cut === -1 ? '' : raw.slice(cut + 1);
        const parts = (cut === -1 ? raw : raw.slice(0, cut)).split('/').filter(Boolean);
        const ask = (name) => new URLSearchParams(query).get(name) || '';
        if (!parts.length) return { name: 'board', id: null };
        if (parts[0] === 'case' && parts[1]) return { name: 'case', id: parts[1] };
        if (parts[0] === 'chat') return { name: 'chat', id: parts[1] ? decodeURIComponent(parts[1]) : null };
        if (parts[0] === 'talks') {
            return { name: 'talks', id: parts[1] ? parts[1] : null, to: ask('to') };
        }
        if (parts[0] === 'potok') return { name: 'potok', id: parts[1] ? decodeURIComponent(parts[1]) : null };
        if (parts[0] === 'stol' && parts[1]) return { name: 'stol', id: decodeURIComponent(parts[1]) };
        if (parts[0] === 'session' && parts[1]) return { name: 'session', id: decodeURIComponent(parts[1]) };
        if (parts[0] === 'pakety') return { name: 'pakety', id: parts[1] ? decodeURIComponent(parts[1]) : null };
        if (parts[0] === 'library' && parts.length > 1) {
            // Идентификатор документа — путь вида «standards/obw-method».
            return { name: 'library', id: parts.slice(1).map(decodeURIComponent).join('/') };
        }
        if (['board', 'cases', 'roster', 'talks', 'library', 'stats', 'me', 'users', 'potok', 'pakety', 'sessions'].indexOf(parts[0]) !== -1) {
            return { name: parts[0], id: null };
        }
        return { name: 'board', id: null };
    }

    function hasUnsaved() {
        return state.route.name === 'case' && (wb.dirty.size > 0 || wb.factsDirty);
    }

    function unsavedMessage() {
        const parts = [];
        if (wb.dirty.size) {
            parts.push('несохранённых секций: ' + wb.dirty.size);
        }
        if (wb.factsDirty) parts.push('изменён факт-пакет');
        return parts.join(', ');
    }

    async function onHashChange() {
        if (restoringHash) {
            restoringHash = false;
            return;
        }
        const next = location.hash || '#/board';
        if (hasUnsaved()) {
            const ok = await confirmDialog({
                title: 'Есть несохранённые правки',
                message: 'В письме остались несохранённые изменения (' + unsavedMessage() +
                    '). Уйти со страницы и потерять их?',
                confirmText: 'Уйти без сохранения',
                danger: true,
            });
            if (!ok) {
                restoringHash = true;
                location.hash = currentHash;
                return;
            }
            wb.dirty.clear();
            wb.factsDirty = false;
        }
        currentHash = next;
        await renderRoute(parseHash(next));
    }

    async function renderRoute(route) {
        // Уходя с экрана помощника, отпускаем узлы страницы, но генерацию
        // не трогаем: ответ дописывается в фоне и ждёт возвращения.
        detachChat();
        stopTalkPoll();
        остановитьОпросПотока();
        // Гостю открыт один помощник. Забрёл по ссылке в другой раздел —
        // возвращаем к помощнику, не показывая отказ: он ничего не сделал
        // не так.
        if (isGuest() && route.name !== 'chat') {
            location.hash = '#/chat';
            return;
        }
        state.route = route;
        setActiveNav(route.name);
        ОПИСАНИЕ.текущее = null;
        // Новый переход — новое поколение: всё, что прежний раздел ещё ждёт
        // от сервера, придёт отвергнутым и на экран не попадёт.
        поколениеВида += 1;
        document.body.style.removeProperty('--над-вводом');
        // Вторая линия защиты — своя сцена у каждого раздела. Первая линия
        // (отвергнутый ответ) не спасает там, где раздел сам ловит ошибку и
        // идёт дальше: «не пришли форматы — обойдёмся», и библиотека
        // дорисовывалась поверх «Сообщений». Таких мест десятки, и чинить
        // каждое — значит однажды пропустить. Сцена отцепляется при переходе
        // целиком, и опоздавшая отрисовка пишет в узел, которого не видно.
        const view = $('#view');
        const сцена = h('div', { class: 'scene' });
        clear(view);
        view.appendChild(сцена);
        сцена.appendChild(h('div', { class: 'page' }, skeleton(6, 'page')));
        await рисоватьРаздел(route, сцена);
    }

    async function рисоватьРаздел(route, view) {
        try {
            if (route.name === 'board') await renderBoard(view);
            else if (route.name === 'cases') await renderCases(view);
            else if (route.name === 'case') await renderCase(view, route.id);
            else if (route.name === 'library') await renderLibrary(view, route.id);
            else if (route.name === 'potok') await renderPotok(view, route.id);
            else if (route.name === 'stol') await renderStol(view, route.id);
            else if (route.name === 'sessions') await renderSessions(view);
            else if (route.name === 'session') await renderStol(view, null, route.id);
            else if (route.name === 'pakety') await renderPakety(view, route.id);
            else if (route.name === 'stats') await renderStats(view);
            else if (route.name === 'roster') await renderRoster(view);
            else if (route.name === 'chat') await renderChat(view, route.id);
            else if (route.name === 'talks') await renderTalks(view, route.id, route.to);
            else if (route.name === 'me') await renderMe(view);
            else if (route.name === 'users') await renderUsers(view);
        } catch (error) {
            if (error instanceof ApiError && error.status === 401) return;
            // Раздел сменился, пока этот ждал сервер. Молча уходим: новый
            // раздел уже рисует себя сам, и «не удалось открыть» поверх него
            // было бы неправдой.
            if (error instanceof Устарело) return;
            if (!view.isConnected) return;      // сцена уже снята — рисовать некуда
            clear(view);
            view.appendChild(h('div', { class: 'page' },
                h('div', { class: 'card card-pad' },
                    h('h3', { style: { color: 'var(--danger)', marginBottom: '6px' } }, 'Не удалось открыть раздел'),
                    h('div', { class: 'muted' }, errorText(error)),
                    h('div', { class: 'btn-row', style: { marginTop: '12px' } },
                        h('button', { class: 'btn', onclick: () => renderRoute(state.route) }, 'Повторить'),
                        h('a', { class: 'btn', href: '#/board' }, 'В сводку')))));
        }
    }

    function navigate(hash) {
        if (location.hash === hash) onHashChange();
        else location.hash = hash;
    }

    /** Сменить адрес, не перерисовывая экран: нужно, чтобы поток ответа не оборвался. */
    function replaceHash(hash) {
        if (location.hash === hash) return;
        restoringHash = true;
        currentHash = hash;
        location.hash = hash;
    }

    // =====================================================================
    // 5. Экран «Письма»
    // =====================================================================

    /* Раздел ведёт письма отдела. У письма есть входящий номер, номер
       группы (откуда пришло), срок ответа, исполнитель и один отчёт —
       подготовленный ответ. Круг замыкается исходящим номером: под ним
       ответ ушёл адресату, и только тогда письмо считается закрытым. */

    const casesState = {
        view: 'open',       // open | overdue | mine | all | архивные состояния
        query: '',
        limit: 100,
        offset: 0,
        total: 0,
        open: 0,
        overdue: 0,
        today: '',
        items: [],
        staff: [],
        //: Нажали «Новое письмо» в меню, находясь в другом разделе. Экран
        //: писем откроет окно регистрации сам, как только соберётся: иначе
        //: кнопка в меню лишь перебрасывала на список, и человек нажимал
        //: второй раз уже там.
        pendingNew: false,
    };

    /* Наборы писем на кнопках-фильтрах. */
    const CASE_VIEWS = [
        { id: 'open', title: 'В работе', params: { status: 'open' } },
        { id: 'overdue', title: 'Просроченные', params: { overdue: '1' } },
        // Начальнику это первый набор, за которым он сюда заходит.
        { id: 'review', title: 'На проверке', params: { status: 'review' } },
        // А это первый набор исполнителя: начальник проверил, ответ ещё не ушёл.
        { id: 'checked', title: 'К отправке', params: { status: 'checked' } },
        { id: 'mine', title: 'Мои', params: { status: 'open', mine: true } },
        { id: 'approved', title: 'Отправленные', params: { status: 'approved' } },
        { id: 'all', title: 'Все', params: {} },
    ];

    /** Список военнослужащих для выбора исполнителя. Читается раз на сеанс.
     *  Доступен всем: взять письмо на себя вправе любой инженер. */
    async function staffList() {
        if (casesState.staff.length) return casesState.staff;
        try {
            const data = await api.get('/api/staff');
            casesState.staff = data.items || [];
        } catch (error) {
            casesState.staff = [];
        }
        return casesState.staff;
    }

    async function renderCases(view) {
        clear(view);
        const page = h('div', { class: 'page' });
        view.appendChild(page);

        const tabs = h('div', { class: 'seg' });
        const searchInput = h('input', {
            type: 'search', class: 'field-search',
            placeholder: 'Номер, описание или слово из отчёта',
            title: 'Ищет по учётному и входящему номеру, исходящему номеру, '
                + 'описанию, номеру ТС, линии связи, номеру группы, примечанию '
                + '— и по тексту самих отчётов. Слова ищутся по основе: '
                + '«помеха» найдёт и «помехи».',
            value: casesState.query,
            oninput: debounce((event) => {
                casesState.query = event.target.value.trim();
                casesState.offset = 0;
                loadCases();
            }, 250),
        });

        const tableBox = h('div', { class: 'card' });
        const footer = h('div', { class: 'toolbar', style: { marginTop: '12px' } });

        append(page, [
            h('div', { class: 'page-head' },
                h('div', { class: 'page-head-actions' },
                    h('button', { class: 'btn', onclick: () => loadCases() }, 'Обновить'),
                    /* Указатель поиска строится сам, но перестроение может
                       оборваться, и тогда часть писем не находится. Кнопка
                       на такой случай — как и у библиотеки. */
                    isAdmin() ? h('button', {
                        class: 'btn btn--sm',
                        title: 'Перестроить указатель поиска по письмам, если что-то '
                            + 'перестало находиться',
                        onclick: () => reindexCases(),
                    }, 'Указатель поиска') : null,
                    canEdit() ? h('button', {
                        class: 'btn',
                        title: 'Загрузить свой готовый отчёт файлом на проверку начальнику',
                        onclick: () => openUploadReportDialog(loadCases),
                    }, 'Сдать готовый отчёт') : null,
                    canEdit() ? h('button', {
                        class: 'btn btn--primary', onclick: () => openNewCaseDialog(),
                    }, 'Зарегистрировать письмо') : null)),
            h('div', { class: 'toolbar' }, tabs, h('span', { class: 'grow' }), searchInput),
            tableBox,
            footer,
        ]);
        if (casesState.pendingNew) {
            casesState.pendingNew = false;
            if (canEdit()) openNewCaseDialog();
        }

        function renderTabs() {
            clear(tabs);
            CASE_VIEWS.forEach((item) => {
                let badge = null;
                if (item.id === 'open' && casesState.open) badge = String(casesState.open);
                if (item.id === 'overdue' && casesState.overdue) badge = String(casesState.overdue);
                tabs.appendChild(h('button', {
                    class: 'seg-item' + (casesState.view === item.id ? ' is-active' : '') +
                        (item.id === 'overdue' && casesState.overdue ? ' is-late' : ''),
                    onclick: () => {
                        casesState.view = item.id;
                        casesState.offset = 0;
                        loadCases();
                    },
                }, item.title, badge ? h('b', {}, badge) : null));
            });
        }

        /** Кнопка «Сдать готовый отчёт» и её диалог: реквизиты и файл. */
    /** Перестроить указатель поиска по письмам. Право администратора. */
    async function reindexCases() {
        const ok = await confirmDialog({
            title: 'Перестроить указатель поиска',
            message: 'Указатель по письмам и текстам отчётов будет собран заново.',
            note: 'Обычно он обновляется сам при каждой правке. Кнопка нужна, '
                + 'если что-то перестало находиться поиском.',
            confirmText: 'Перестроить',
        });
        if (!ok) return;
        try {
            const data = await withOverlay('Перестроение указателя',
                'Собираем реквизиты писем и тексты отчётов заново.',
                () => api.post('/api/cases/reindex', {}));
            toast('Указатель перестроен, писем: ' + (data.cases || 0), 'ok');
        } catch (error) {
            toastError(error);
        }
    }

    async function openUploadReportDialog(after) {
        const staff = await staffList();
        const me = state.user || {};
        const incoming = h('input', {
            type: 'text', placeholder: 'ВХ-2026-0423',
            maxLength: CARD_LIMIT.incoming_no });
        const group = h('input', {
            type: 'text', placeholder: '1274 или 1-я группа',
            maxLength: CARD_LIMIT.group_no });
        const title = h('input', {
            type: 'text', placeholder: 'о чём письмо', maxLength: CARD_LIMIT.title });
        const incomingDate = h('input', { type: 'date' });
        const deadline = h('input', { type: 'date' });
        const priority = h('select', {}, ...Object.keys(CASE_PRIORITY).map((id) =>
            h('option', { value: id }, CASE_PRIORITY[id])));
        const assignee = h('select', {},
            h('option', { value: String(me.id || '') },
                (me.short_name || me.full_name || me.login || 'я') + ' (я)'),
            ...staff.filter((person) => person.id !== me.id).map((person) =>
                h('option', { value: String(person.id) },
                    person.full_name || person.login)));
        /* Направление работы. Сданный файлом отчёт по шаблону не собирается,
           но письмо без направления не найти в отделе по нужной теме — а
           брать первое попавшееся значит подписать письмо чужой темой. */
        const outlines = state.config.outlines || [];
        const kind = h('select', {}, outlines.map((outline) =>
            h('option', { value: outline.report_type, title: outline.title },
                reportTypeShort(outline))));
        kind.disabled = !outlines.length;
        // Системную кнопку выбора файла прячем: она подписана по-английски
        // и в остальном интерфейсе такой нет.
        const chosen = h('span', { class: 'small muted' }, 'файл не выбран');
        const picker = h('input', {
            type: 'file',
            style: { display: 'none' },
            onchange: () => {
                const file = (picker.files || [])[0];
                chosen.textContent = file ? file.name : 'файл не выбран';
                chosen.className = file ? 'small' : 'small muted';
            },
        });
        const pickButton = h('div', { class: 'file-pick' },
            h('button', {
                class: 'btn btn--sm', type: 'button',
                onclick: () => picker.click(),
            }, iconGlyph('clip'), 'Выбрать файл'),
            chosen, picker);

        const dialog = openModal({
            title: 'Сдать готовый отчёт',
            body: h('div', { class: 'form-grid' },
                h('div', { class: 'muted', style: { gridColumn: '1 / -1' } },
                    'Отчёт уйдёт на проверку начальнику отдела. Числа в нём система '
                    + 'не сверяет: факт-пакета за таким отчётом нет, читает его человек.'),
                h('label', { class: 'field' }, 'Файл отчёта', pickButton),
                h('label', { class: 'field' }, 'Входящий номер', incoming),
                h('label', { class: 'field' }, 'Номер группы', group),
                h('label', { class: 'field' }, 'Описание', title),
                h('label', { class: 'field' }, 'Направление работы', kind),
                h('label', { class: 'field' }, 'Дата письма', incomingDate),
                h('label', { class: 'field' }, 'Срок ответа', deadline),
                h('label', { class: 'field' }, 'Важность', priority),
                h('label', { class: 'field' }, 'Исполнитель', assignee)),
            footer: [
                h('button', { class: 'btn', onclick: () => dialog.close() }, 'Отмена'),
                h('button', { class: 'btn btn--primary', onclick: () => send() }, 'Сдать на проверку'),
            ],
        });
        setTimeout(() => incoming.focus(), 30);

        async function send() {
            const file = (picker.files || [])[0];
            if (!file) { toast('Выберите файл отчёта', 'error'); return; }
            if (!incoming.value.trim()) { toast('Укажите входящий номер', 'error'); return; }
            const form = new FormData();
            form.append('file', file);
            form.append('case_id', incoming.value.trim());
            form.append('incoming_no', incoming.value.trim());
            form.append('group_no', group.value.trim());
            form.append('title', title.value.trim());
            form.append('report_type', kind.value || '');
            form.append('incoming_date', incomingDate.value || '');
            form.append('deadline', deadline.value || '');
            form.append('priority', priority.value);
            form.append('assignee_id', assignee.value || '');
            try {
                const data = await uploadFile('/api/reports/upload', form);
                dialog.close();
                toast(data.note
                    ? 'Отчёт сдан на проверку. Текст прочитать не удалось: ' + data.note
                    : 'Отчёт сдан на проверку', data.note ? 'info' : 'ok', 6000);
                if (after) after();
            } catch (error) {
                toastError(error);
            }
        }
    }

    async function loadCases() {
            renderTabs();
            clear(tableBox);
            tableBox.appendChild(skeleton(8));
            const chosen = CASE_VIEWS.filter((item) => item.id === casesState.view)[0] || CASE_VIEWS[0];
            const params = ['limit=' + casesState.limit, 'offset=' + casesState.offset];
            if (chosen.params.status) params.push('status=' + chosen.params.status);
            if (chosen.params.overdue) params.push('overdue=1');
            if (chosen.params.mine && state.user) params.push('assignee=' + state.user.id);
            if (casesState.query) params.push('q=' + encodeURIComponent(casesState.query));
            try {
                const data = await api.get('/api/cases?' + params.join('&'));
                casesState.items = data.items || [];
                casesState.total = data.total || 0;
                casesState.open = data.open || 0;
                casesState.overdue = data.overdue || 0;
                casesState.today = data.today || '';
                setNavCount('letters', casesState.open, casesState.overdue);
                renderTabs();
                renderCasesTable();
            } catch (error) {
                clear(tableBox);
                tableBox.appendChild(errorBox(error));
            }
        }

        function renderCasesTable() {
            const items = casesState.items;
            clear(tableBox);
            if (!items.length) {
                tableBox.appendChild(emptyBox(
                    casesState.query ? 'Ничего не найдено' : 'Писем нет',
                    casesState.query
                        ? 'Проверьте строку поиска или выберите другой набор.'
                        : 'Зарегистрируйте входящее письмо, чтобы начать работу.',
                    casesState.query || !canEdit() ? null : h('button', {
                        class: 'btn btn--sm btn--primary',
                        onclick: () => openNewCaseDialog(),
                    }, 'Зарегистрировать письмо')));
            } else {
                const body = h('tbody', {});
                items.forEach((item) => {
                    body.appendChild(h('tr', {
                        class: 'clickable',
                        onclick: (event) => {
                            if (event.target.closest('button')) return;
                            navigate('#/case/' + item.id);
                        },
                    },
                        h('td', { class: 'mono nowrap' }, item.incoming_no || item.case_id),
                        h('td', {}, h('div', {}, item.title || h('span', { class: 'faint' }, 'без описания')),
                            item.priority && item.priority !== 'normal'
                                ? h('span', { class: 'tag tag--' + item.priority },
                                    CASE_PRIORITY[item.priority]) : null,
                            // Искомого слова не видно ни в теме, ни в номерах —
                            // значит, письмо нашлось по тексту отчёта. Без
                            // пометки строка в выдаче выглядит случайной.
                            item.found_in_report
                                ? h('span', { class: 'tag', title: 'Искомое слово нашлось '
                                    + 'в тексте отчёта по этому письму' }, 'в тексте отчёта')
                                : null),
                        // Линия связи и номер средства — разные вещи и разные
                        // столбцы: линия говорит, чьё это хозяйство, номер ТС —
                        // по какому именно средству работают. В одной ячейке их
                        // не отсортировать и не сравнить глазами по столбцу.
                        h('td', { class: 'small nowrap' },
                            item.line_type
                                ? h('span', { class: 'tag tag--line' },
                                    LINE_TITLE[item.line_type] || item.line_type)
                                : h('span', { class: 'faint' }, '—')),
                        h('td', { class: 'mono small nowrap' },
                            item.tc_no || h('span', { class: 'faint' }, '—')),
                        h('td', { class: 'small' },
                            item.group_no || h('span', { class: 'faint' }, '—')),
                        h('td', { class: 'small nowrap' },
                            personLink(item.assignee_id, item.assignee_name)),
                        h('td', { class: 'nowrap' }, deadlineCell(item)),
                        h('td', {}, statusBadge(item.status)),
                        // Исходящий номер — вторая половина учёта: чем ответили.
                        h('td', { class: 'mono small nowrap',
                            title: item.outgoing_date
                                ? 'Ответ отправлен ' + fmtDate(item.outgoing_date)
                                    + (item.sent_by_name ? ', ' + item.sent_by_name : '')
                                : '' },
                            item.outgoing_no || h('span', { class: 'faint' }, '—')),
                        h('td', { class: 'small muted nowrap' }, fmtDate(item.incoming_date) || '—'),
                        h('td', { class: 'row-actions nowrap' },
                            canEdit() ? h('button', {
                                class: 'btn btn--icon',
                                title: 'Карточка письма: исполнитель, срок, состояние',
                                onclick: () => openCaseCard(item, loadCases),
                            }, iconGlyph('edit')) : null,
                            canDeleteCase(item) ? h('button', {
                                class: 'btn btn--icon btn--danger-hover',
                                title: isAdmin()
                                    ? 'Удалить письмо вместе с отчётами'
                                    : 'Убрать ошибочно заведённое письмо',
                                onclick: () => deleteCase(item, loadCases),
                            }, iconGlyph('trash')) : null)));
                });
                tableBox.appendChild(h('div', { class: 'table-scroll' },
                    h('table', { class: 'grid grid--letters' },
                        h('thead', {}, h('tr', {},
                            h('th', {}, 'Входящий'),
                            h('th', {}, 'Описание'),
                            h('th', {}, 'Линия'),
                            h('th', {}, 'Номер ТС'),
                            h('th', {}, 'Номер группы'),
                            h('th', {}, 'Исполнитель'),
                            h('th', {}, 'Срок ответа'),
                            h('th', {}, 'Состояние'),
                            h('th', {}, 'Исходящий'),
                            h('th', {}, 'Дата письма'),
                            h('th', {}))),
                        body)));
            }

            clear(footer);
            const from = casesState.total ? casesState.offset + 1 : 0;
            const to = casesState.offset + items.length;
            append(footer, [
                h('span', { class: 'small muted' }, 'показаны ' + from + '–' + to + ' из ' + casesState.total),
                h('span', { class: 'grow' }),
                h('button', {
                    class: 'btn btn--sm', disabled: casesState.offset <= 0,
                    onclick: () => {
                        casesState.offset = Math.max(0, casesState.offset - casesState.limit);
                        loadCases();
                    },
                }, 'Назад'),
                h('button', {
                    class: 'btn btn--sm', disabled: to >= casesState.total,
                    onclick: () => {
                        casesState.offset += casesState.limit;
                        loadCases();
                    },
                }, 'Дальше'),
            ]);
        }

        await loadCases();
    }

    /** Срок с пометкой: просрочен, сегодня-завтра или спокойно. */
    function deadlineCell(item) {
        if (!item.deadline) return h('span', { class: 'faint' }, 'не задан');
        const today = casesState.today || todayIso();
        const done = item.status === 'approved' || item.status === 'archived';
        let cls = 'due';
        let note = '';
        if (!done && item.deadline < today) {
            cls = 'due due--late';
            const late = daysBetween(item.deadline, today);
            note = 'просрочено на ' + late + ' ' + plural(late, 'день', 'дня', 'дней');
        } else if (!done && daysBetween(today, item.deadline) <= 2) {
            cls = 'due due--soon';
            const left = daysBetween(today, item.deadline);
            note = 'осталось ' + left + ' ' + plural(left, 'день', 'дня', 'дней');
        }
        return h('span', { class: cls, title: note }, fmtDate(item.deadline));
    }

    function todayIso() {
        const now = new Date();
        const month = String(now.getMonth() + 1).padStart(2, '0');
        return now.getFullYear() + '-' + month + '-' + String(now.getDate()).padStart(2, '0');
    }

    function daysBetween(from, to) {
        const a = Date.parse(from + 'T00:00:00');
        const b = Date.parse(to + 'T00:00:00');
        if (isNaN(a) || isNaN(b)) return 0;
        return Math.round((b - a) / 86400000);
    }

    function statusBadge(status) {
        const kind = { approved: 'ok', review: 'warn', archived: '', draft: 'info', new: 'accent' }[status];
        return h('span', { class: 'badge' + (kind ? ' badge--' + kind : '') }, CASE_STATUS[status] || status);
    }

    /** Карточка письма: исполнитель, срок, состояние, приоритет — без ухода со списка. */
    async function openCaseCard(item, after) {
        const staff = await staffList();
        const assignee = h('select', {},
            h('option', { value: '' }, 'не назначен'),
            staff.map((person) => h('option', {
                value: String(person.id),
                selected: person.id === item.assignee_id,
            }, (person.full_name || person.login) + ' — ' + roleShort(person.role))));
        if (!staff.length) {
            assignee.disabled = true;
            assignee.title = 'Список военнослужащих получить не удалось';
        }

        const deadline = h('input', { type: 'date', value: item.deadline || '' });
        const incomingNo = h('input', {
            type: 'text', class: 'mono', value: item.incoming_no || '',
            maxLength: CARD_LIMIT.incoming_no });
        const incomingDate = h('input', { type: 'date', value: item.incoming_date || '' });
        const priority = h('select', {}, Object.keys(CASE_PRIORITY).map((key) =>
            h('option', { value: key, selected: (item.priority || 'normal') === key },
                CASE_PRIORITY[key])));
        /* «На проверке» и «отправлено» письму даёт проверка отчёта: сдали —
           «на проверке», отметили проверенным — «отправлено». Руками их не
           выставляют, иначе письмо уходит из работы мимо начальника. Пока по
           письму нет ни одного отчёта, подменять нечего — на такое письмо
           ответили мимо системы, и отметить его можно. */
        const byFlow = Number(item.reports_count || 0) > 0;
        const status = h('select', {}, CASE_FLOW.map((key) => {
            const locked = byFlow && CASE_BY_FLOW.includes(key) && item.status !== key;
            return h('option', {
                value: key,
                selected: item.status === key,
                disabled: locked,
                title: locked ? 'Это состояние письмо получает от проверки отчёта' : '',
            }, CASE_STATUS[key] + (locked ? ' — по отчёту' : ''));
        }));
        const groupInput = h('input', {
            type: 'text', maxLength: CARD_LIMIT.group_no,
            placeholder: '1274 или 1-я группа', value: item.group_no || '',
            title: 'Откуда пришло письмо. Пишите как принято в отделе: 1274, 12/345, в/ч 74326, «2-я группа связи»',
        });
        const titleInput = h('textarea', {
            class: 'field-area', rows: 2, maxLength: CARD_LIMIT.title,
            placeholder: 'о чём письмо' }, item.title || '');
        const tcInput = h('input', {
            type: 'text', class: 'mono', maxLength: CARD_LIMIT.tc_no,
            placeholder: 'ТС-1274-03', value: item.tc_no || '' });
        const tcDate = h('input', { type: 'date', value: item.tc_date || '' });
        const orderNo = h('input', {
            type: 'text', class: 'mono', maxLength: CARD_LIMIT.order_no,
            placeholder: 'У-2026-14', value: item.order_no || '' });
        const orderDate = h('input', { type: 'date', value: item.order_date || '' });
        const regInput = h('input', {
            type: 'number', min: '0', step: '1',
            value: String(item.registrations || 0) });
        const linePick = h('select', {},
            h('option', { value: '', selected: !item.line_type }, 'не указана'),
            (state.config.line_types || []).map((line) => h('option', {
                value: line.id, title: line.full, selected: item.line_type === line.id,
            }, line.title)));
        const note = h('textarea', { rows: '3', maxLength: CARD_LIMIT.note }, item.note || '');

        const save = h('button', { class: 'btn btn--primary', onclick: submit }, 'Сохранить');
        const dialog = openModal({
            title: 'Письмо ' + (item.incoming_no || item.case_id),
            body: [
                h('div', { class: 'form-grid' },
                    h('label', { class: 'field' }, 'Входящий номер', incomingNo),
                    h('label', { class: 'field' }, 'Дата письма', incomingDate),
                    h('label', { class: 'field' }, 'Номер группы', groupInput),
                    h('label', { class: 'field' }, 'Номер указаний', orderNo),
                    h('label', { class: 'field' }, 'Дата указаний', orderDate),
                    h('label', { class: 'field' }, 'Номер ТС', tcInput),
                    h('label', { class: 'field' }, 'Дата ТС', tcDate),
                    h('label', { class: 'field' }, 'Линия связи', linePick),
                    h('label', { class: 'field' }, 'Количество регистраций', regInput),
                    h('label', { class: 'field' }, 'Срок ответа', deadline),
                    h('label', { class: 'field' }, 'Исполнитель', assignee),
                    h('label', { class: 'field' }, 'Приоритет', priority),
                    h('label', { class: 'field' }, 'Состояние', status)),
                h('label', { class: 'field' }, 'Описание', titleInput),
                h('label', { class: 'field' }, 'Примечание', note),
            ],
            footer: [
                h('span', { class: 'spacer' }),
                h('button', { class: 'btn', onclick: () => dialog.close() }, 'Отмена'),
                save,
            ],
            focus: 'input',
        });

        async function submit() {
            save.disabled = true;
            try {
                await api.patch('/api/cases/' + item.id, {
                    incoming_no: incomingNo.value.trim(),
                    incoming_date: incomingDate.value,
                    group_no: groupInput.value.trim(),
                    title: titleInput.value.trim(),
                    tc_no: tcInput.value.trim(),
                    tc_date: tcDate.value || '',
                    order_no: orderNo.value.trim(),
                    order_date: orderDate.value || '',
                    registrations: Number(regInput.value || 0),
                    line_type: linePick.value,
                    deadline: deadline.value,
                    assignee_id: assignee.value ? Number(assignee.value) : null,
                    priority: priority.value,
                    status: status.value,
                    note: note.value.trim(),
                });
                dialog.close();
                toast('Карточка письма сохранена', 'ok');
                if (after) after();
            } catch (error) {
                toastError(error);
            } finally {
                save.disabled = false;
            }
        }
    }

    /* Кому можно убрать письмо. Ошибиться при регистрации может каждый, и
       ходить за начальником из-за собственной описки человек не должен. Своё
       письмо убирает тот, кто его завёл, — но лишь пока по нему ничего не
       сделано. Как только за письмо взялись, оно перестаёт быть личной
       ошибкой и становится работой отдела. Те же правила на сервере. */
    function canDeleteCase(item) {
        if (isAdmin()) return true;
        const me = state.user || {};
        return Boolean(item.created_by && item.created_by === me.id)
            && !Number(item.reports_count || 0)
            && !item.outgoing_no;
    }

    /* Сдать по уже заведённому письму свой отчёт.

       Отдельное окно от «Сдать готовый отчёт» в списке писем: там реквизиты
       спрашивают, потому что письма может ещё не быть. Здесь письмо открыто,
       и спрашивать нечего — от повторного ввода входящего номера рождались
       письма-двойники: ошибся в знаке, и вместо новой редакции по своему
       письму заводилось второе. */
    function openUploadForCase(item, after) {
        const chosen = h('span', { class: 'small muted' }, 'файл не выбран');
        const picker = h('input', {
            type: 'file',
            style: { display: 'none' },
            onchange: () => {
                const file = (picker.files || [])[0];
                chosen.textContent = file ? file.name : 'файл не выбран';
                chosen.className = file ? 'small' : 'small muted';
            },
        });
        const send = h('button', { class: 'btn btn--primary', onclick: submit },
            'Загрузить');

        const dialog = openModal({
            title: 'Свой отчёт по письму ' + (item.incoming_no || item.case_id),
            narrow: true,
            body: [
                h('div', { class: 'muted', style: { marginBottom: '10px' } },
                    'Отчёт станет новой редакцией по этому письму. Числа в нём '
                    + 'система не сверяет: его написал человек. После загрузки '
                    + 'отчёт можно отправить начальнику на проверку.'),
                h('div', { class: 'file-pick' },
                    h('button', {
                        class: 'btn btn--sm', type: 'button',
                        onclick: () => picker.click(),
                    }, iconGlyph('clip'), 'Выбрать файл'),
                    chosen, picker),
            ],
            footer: [
                h('span', { class: 'spacer' }),
                h('button', { class: 'btn', onclick: () => dialog.close() }, 'Отмена'),
                send,
            ],
        });

        async function submit() {
            const file = (picker.files || [])[0];
            if (!file) { toast('Выберите файл отчёта', 'error'); return; }
            send.disabled = true;
            const form = new FormData();
            form.append('file', file);
            // Ключ письма — его учётный номер: сервер найдёт письмо по нему
            // и заведёт редакцию, а не второе письмо.
            form.append('case_id', item.case_id);
            // На проверку отчёт уйдёт отдельной кнопкой: сперва его смотрят.
            form.append('submit', '0');
            try {
                const data = await uploadFile('/api/reports/upload', form);
                dialog.close();
                toast(data.note
                    ? 'Отчёт загружен. Текст прочитать не удалось: ' + data.note
                    : 'Отчёт загружен — посмотрите и отправьте на проверку',
                    data.note ? 'info' : 'ok', 6000);
                if (after) after();
            } catch (error) {
                toastError(error);
            } finally {
                send.disabled = false;
            }
        }
    }

    async function deleteCase(item, after) {
        const mine = !isAdmin();
        const ok = await confirmDialog({
            title: mine ? 'Убрать письмо' : 'Удалить письмо',
            message: mine
                ? 'Письмо ' + (item.incoming_no || item.case_id) + ' будет убрано '
                    + 'вместе с приложенными к нему файлами. Действие необратимо.'
                : 'Письмо ' + (item.incoming_no || item.case_id) +
                    ' будет удалено вместе со всеми версиями отчёта. Действие необратимо.',
            note: 'Сохранённые пары «черновик → правка» в обучающем наборе остаются. '
                + 'Уже выгруженные файлы DOCX лежат в каталоге выгрузок и удаляются вручную.',
            confirmText: 'Удалить',
            danger: true,
        });
        if (!ok) return;
        try {
            await api.del('/api/cases/' + item.id);
            toast('Письмо удалено', 'ok');
            if (after) after();
        } catch (error) {
            toastError(error);
        }
    }

    // -- модальное окно «Новое письмо» ---------------------------------------

    function openNewCaseDialog() {
        const lines = state.config.line_types || [];

        const titleInput = h('textarea', {
            class: 'field-area', rows: 2, placeholder: 'о чём письмо',
            maxLength: CARD_LIMIT.title });
        const incomingNo = h('input', {
            type: 'text', class: 'mono', placeholder: 'ВХ-2026-0412',
            maxLength: CARD_LIMIT.incoming_no });
        const caseInput = h('input', {
            type: 'text', placeholder: 'заполнится по входящему номеру', class: 'mono',
            oninput: () => { caseTouched = true; },
        });
        let caseTouched = false;
        // Учётный номер по умолчанию повторяет входящий: два разных номера
        // руками никто вводить не станет, а поле обязательное.
        incomingNo.addEventListener('input', () => {
            if (caseTouched) return;
            caseInput.value = incomingNo.value.trim();
        });
        const incomingDate = h('input', { type: 'date', value: todayIso() });
        const groupNoInput = h('input', {
            type: 'text', placeholder: '1274',
            title: 'Откуда пришло письмо. Пишите как принято в отделе: 1274, 12/345, в/ч 74326, «2-я группа связи»',
        });
        const tcInput = h('input', {
            type: 'text', class: 'mono', placeholder: 'ТС-1274-03',
            maxLength: CARD_LIMIT.tc_no,
            title: 'Номер технического средства, о котором письмо. Ищется наравне с номерами письма',
        });
        const tcDate = h('input', { type: 'date' });
        const orderNo = h('input', {
            type: 'text', class: 'mono', placeholder: 'У-2026-14',
            maxLength: CARD_LIMIT.order_no,
            title: 'Номер указаний, по которым письмо отрабатывают',
        });
        const orderDate = h('input', { type: 'date' });
        const regInput = h('input', {
            type: 'number', min: '0', step: '1', placeholder: '0',
            title: 'Сколько регистраций числится по письму',
        });
        const deadlineInput = h('input', { type: 'date' });
        const priorityPick = h('select', {}, Object.keys(CASE_PRIORITY).map((key) =>
            h('option', { value: key }, CASE_PRIORITY[key])));
        const assigneePick = h('select', {}, h('option', { value: '' }, 'назначить позже'));
        // Список военнослужащих подгружаем, не задерживая открытие окна.
        staffList().then((staff) => staff.forEach((person) => assigneePick.appendChild(
            h('option', { value: String(person.id) },
                (person.full_name || person.login) + ' — ' + roleShort(person.role)))));

        // Линия связи вместо типа отчёта: отдел работает по линиям, а шаблон
        // отчёта выбирается потом, когда инженер садится за текст.
        const linePick = h('select', {},
            h('option', { value: '' }, 'не указана'),
            lines.map((item) => h('option', { value: item.id, title: item.full }, item.title)));

        // Приложенные бумаги. Файл кладётся на диск после того, как письмо
        // заведено: раньше не к чему прикладывать. Список собираем здесь и
        // отправляем по одному — так видно, какой именно файл не прошёл.
        let picked = [];
        const fileList = h('div', { class: 'file-list' });
        const fileInput = h('input', {
            type: 'file', multiple: true, style: { display: 'none' },
            onchange: (event) => {
                const chosen = Array.from(event.target.files || []);
                chosen.forEach((file) => {
                    if (!picked.some((item) => item.name === file.name && item.size === file.size)) {
                        picked.push(file);
                    }
                });
                event.target.value = '';
                drawFiles();
            },
        });

        function drawFiles() {
            clear(fileList);
            if (!picked.length) {
                fileList.appendChild(h('div', { class: 'small faint' },
                    'Скан письма, схема линии, журнал измерений — что пришло вместе с письмом'));
                return;
            }
            picked.forEach((file, index) => fileList.appendChild(
                h('div', { class: 'file-row' },
                    h('span', { class: 'file-name' }, file.name),
                    h('span', { class: 'small faint' }, fmtBytes(file.size)),
                    h('button', {
                        class: 'btn btn--sm btn--ghost',
                        title: 'Убрать из списка',
                        onclick: () => { picked.splice(index, 1); drawFiles(); },
                    }, 'Убрать'))));
        }
        drawFiles();

        const createButton = h('button', { class: 'btn btn--primary', onclick: submit },
            'Зарегистрировать');

        const dialog = openModal({
            title: 'Регистрация письма',
            body: [
                h('div', { class: 'form-grid' },
                    h('label', { class: 'field' }, 'Входящий номер', incomingNo),
                    h('label', { class: 'field' }, 'Дата письма', incomingDate),
                    h('label', { class: 'field' }, 'Номер группы', groupNoInput,
                        h('span', { class: 'small faint' }, 'номер группы или части')),
                    h('label', { class: 'field' }, 'Номер указаний', orderNo),
                    h('label', { class: 'field' }, 'Дата указаний', orderDate),
                    h('label', { class: 'field' }, 'Номер ТС', tcInput,
                        h('span', { class: 'small faint' }, 'техническое средство, о котором письмо')),
                    h('label', { class: 'field' }, 'Дата ТС', tcDate),
                    h('label', { class: 'field' }, 'Линия связи', linePick),
                    h('label', { class: 'field' }, 'Количество регистраций', regInput),
                    h('label', { class: 'field' }, 'Срок ответа', deadlineInput),
                    h('label', { class: 'field' }, 'Исполнитель', assigneePick),
                    h('label', { class: 'field' }, 'Приоритет', priorityPick)),
                h('label', { class: 'field' }, 'Описание', titleInput),
                h('label', { class: 'field' }, 'Учётный номер', caseInput,
                    h('span', { class: 'small faint' },
                        'внутренний номер дела; можно повторить входящий')),
                h('div', { class: 'field' },
                    h('div', { class: 'toolbar', style: { marginBottom: '6px' } },
                        h('span', { class: 'grow' }, 'Приложенные файлы'),
                        h('button', {
                            class: 'btn btn--sm', onclick: () => fileInput.click(),
                        }, 'Выбрать файлы'),
                        fileInput),
                    fileList),
            ],
            footer: [
                h('span', { class: 'small faint spacer' },
                    'Обязательны входящий номер и описание'),
                h('button', { class: 'btn', onclick: () => dialog.close() }, 'Отмена'),
                createButton,
            ],
            focus: 'input',
        });

        async function submit() {
            const caseId = caseInput.value.trim() || incomingNo.value.trim();
            if (!caseId) {
                toast('Укажите входящий номер письма', 'error');
                incomingNo.focus();
                return;
            }
            if (!titleInput.value.trim()) {
                toast('Опишите, о чём письмо', 'error');
                titleInput.focus();
                return;
            }

            createButton.disabled = true;
            createButton.textContent = 'Создание…';
            let created = null;
            try {
                const data = await api.post('/api/cases', {
                    case_id: caseId,
                    title: titleInput.value.trim(),
                    incoming_no: incomingNo.value.trim(),
                    incoming_date: incomingDate.value || '',
                    group_no: groupNoInput.value.trim(),
                    tc_no: tcInput.value.trim(),
                    tc_date: tcDate.value || '',
                    order_no: orderNo.value.trim(),
                    order_date: orderDate.value || '',
                    registrations: Number(regInput.value || 0),
                    line_type: linePick.value,
                    deadline: deadlineInput.value || '',
                    priority: priorityPick.value,
                    assignee_id: assigneePick.value ? Number(assigneePick.value) : null,
                });
                created = data.case;
            } catch (error) {
                toastError(error);
                createButton.disabled = false;
                createButton.textContent = 'Зарегистрировать';
                return;
            }

            // Письмо заведено. Файлы кладём следом и по одному: если один
            // не прошёл, остальные всё равно на месте, а человек видит имя
            // того, который не взяли, — а не «что-то пошло не так».
            const failed = [];
            for (const file of picked) {
                try {
                    const form = new FormData();
                    form.append('file', file);
                    await uploadFile('/api/cases/' + created.id + '/files', form);
                } catch (error) {
                    failed.push(file.name + ' — ' + errorText(error));
                }
            }

            dialog.close();
            if (failed.length) {
                toast('Письмо создано, но файлы не приложены: ' + failed.join('; '), 'error');
            } else {
                toast('Письмо ' + created.case_id + ' зарегистрировано', 'ok');
            }
            location.hash = '#/case/' + created.id;
        }
    }

    // =====================================================================
    // 5а. Экран «Расход»
    // =====================================================================

    /* Расход личного состава: кто где и чем занят по дням.

       Смысл раздела в том, что человек отмечает себя сам. Расход, собранный
       через начальника, устаревает за день, и им никто не пользуется. Поэтому
       своя строка в сетке кликабельна у каждого, чужая — только у начальства.

       Раскладку периодов по суткам делает сервер (GET /api/roster): в браузере
       это пришлось бы повторить трижды — в сетке, в сводке дня и в кабинете, —
       и рано или поздно три расхода разошлись бы. */

    const ROSTER_KIND = {
        duty:     { title: 'дежурство',    short: 'Деж',  cls: 'duty' },
        work:     { title: 'работы',       short: 'Раб',  cls: 'work' },
        trip:     { title: 'командировка', short: 'Ком',  cls: 'trip' },
        study:    { title: 'учёба',        short: 'Учёб', cls: 'study' },
        vacation: { title: 'отпуск',       short: 'Отп',  cls: 'vacation' },
        sick:     { title: 'больничный',   short: 'Бол',  cls: 'sick' },
        dayoff:   { title: 'отгул',        short: 'Отг',  cls: 'dayoff' },
    };

    const WEEKDAYS = ['вс', 'пн', 'вт', 'ср', 'чт', 'пт', 'сб'];

    //: Окно расхода: с какого дня, на сколько суток и какой день раскрыт внизу.
    //: Больше 31 суток сервер не отдаёт (MAX_ROSTER_WINDOW), и просить незачем:
    //: расход дальше месяца в отделе не планируют.
    const ROSTER_MAX_SPAN = 31;
    const rosterState = { from: '', span: 7, day: '' };

    /** Сколько суток между двумя днями включительно. */
    function daysBetween(from, to) {
        const a = new Date(from + 'T00:00:00');
        const b = new Date(to + 'T00:00:00');
        if (isNaN(a.getTime()) || isNaN(b.getTime())) return 0;
        return Math.round((b - a) / 86400000) + 1;
    }

    function shiftIso(day, delta) {
        const date = new Date(day + 'T00:00:00');
        if (isNaN(date.getTime())) return day;
        date.setDate(date.getDate() + delta);
        const month = String(date.getMonth() + 1).padStart(2, '0');
        return date.getFullYear() + '-' + month + '-' + String(date.getDate()).padStart(2, '0');
    }

    /** Понедельник недели, в которую попал день: расход в отделе ведут неделями. */
    function weekStart(day) {
        const date = new Date(day + 'T00:00:00');
        if (isNaN(date.getTime())) return day;
        const shift = (date.getDay() + 6) % 7;
        return shiftIso(day, -shift);
    }

    function isWeekend(day) {
        const date = new Date(day + 'T00:00:00');
        const weekday = date.getDay();
        return weekday === 0 || weekday === 6;
    }

    /* Свой промежуток: «с какого по какое». Выпадающий список даёт неделю,
       две и месяц, а расход просят и на конкретные числа — на время учений,
       на командировку, на отпускной период группы. */
    function pickRosterPeriod(reload) {
        const from = h('input', { type: 'date', value: rosterState.from });
        const to = h('input', {
            type: 'date',
            value: shiftIso(rosterState.from, rosterState.span - 1),
        });
        const hint = h('div', { class: 'small muted' });

        function apply() {
            const начало = from.value;
            const конец = to.value;
            if (!начало || !конец) {
                hint.textContent = 'Укажите оба числа.';
                return;
            }
            if (конец < начало) {
                hint.textContent = 'Конец промежутка раньше начала.';
                return;
            }
            const суток = daysBetween(начало, конец);
            if (суток > ROSTER_MAX_SPAN) {
                // Не молча обрезаем, а говорим: человек ждал бы свой
                // промежуток, а увидел бы месяц и решил, что кнопка не
                // работает.
                hint.textContent = 'Больше ' + ROSTER_MAX_SPAN
                    + ' суток расход не показывает: получилось ' + суток + '.';
                return;
            }
            rosterState.from = начало;
            rosterState.span = суток;
            // День сводки держим внутри нового окна.
            if (rosterState.day < начало || rosterState.day > конец) {
                rosterState.day = начало;
            }
            dialog.close();
            reload();
        }

        const dialog = openModal({
            title: 'Свой промежуток',
            narrow: true,
            body: h('div', {},
                h('label', { class: 'field' }, 'С какого числа', from),
                h('label', { class: 'field' }, 'По какое число', to),
                hint),
            footer: h('button', { class: 'btn btn--primary', onclick: apply },
                       'Показать'),
        });
        return dialog;
    }

    async function renderRoster(view) {
        clear(view);
        const page = h('div', { class: 'page' });
        view.appendChild(page);

        // Окно начинается с сегодня: расход смотрят вперёд («кто где завтра»),
        // а не назад. Кнопка «Текущая неделя» ставит начало на понедельник.
        if (!rosterState.from) rosterState.from = todayIso();
        if (!rosterState.day) rosterState.day = todayIso();

        const gridBox = h('div', { class: 'card' });
        const daysBox = h('div', {});
        const dayBox = h('div', {});
        const rangeLabel = h('span', { class: 'small muted' });

        // В списке — привычные величины. Свой промежуток в список не входит,
        // и его добавляем отдельной строкой: иначе поле показывало бы «7 сут.»
        // при четырёх показанных днях, и человек решил бы, что выбор сбросился.
        const spanChoices = [7, 14, 31];
        const spanPick = h('select', {
            title: 'Сколько суток показывать сразу',
            onchange: () => { rosterState.span = Number(spanPick.value); load(); },
        });

        // Кнопку прячем, пока не выяснили, есть ли вошедший в расходе.
        // Создатель системы в нём не значится: он не дежурит и писем не
        // ведёт. Показанная ему кнопка «Отметить себя» ставила наряд первому
        // по списку — то есть человеку, который об этом не узнает.
        const markSelf = h('button', {
            class: 'btn btn--primary',
            hidden: true,
            title: 'Отметить, чем вы заняты',
            onclick: () => openRosterDialog({ user_id: (state.user || {}).id,
                date_from: rosterState.day }, load),
        }, 'Отметить себя');

        staffList().then((staff) => {
            markSelf.hidden = !staff.some(
                (person) => person.id === (state.user || {}).id);
        });

        function syncSpanPick() {
            clear(spanPick);
            if (spanChoices.indexOf(rosterState.span) === -1) {
                spanPick.appendChild(h('option', { value: String(rosterState.span) },
                                       rosterState.span + ' сут. (свой)'));
            }
            spanChoices.forEach((value) => spanPick.appendChild(
                h('option', { value: String(value) }, value + ' сут.')));
            spanPick.value = String(rosterState.span);
        }
        syncSpanPick();

        append(page, [
            h('div', { class: 'page-head' },
                // «Расход» — слово отдела, а не общепонятное: заголовок сам за
                // себя не говорит. Пересказы заголовков убраны везде, но эти
                // два раздела названы так, что строка под ними — не пересказ,
                // а ответ на «а что здесь вообще?».
                h('div', { class: 'page-note' },
                    'Кто где и чем занят: дежурство, работы, выезды, отсутствия'),
                h('div', { class: 'page-head-actions' },
                    // Двойная стрелка — на окно целиком, одинарная — на сутки.
                    // Раньше были только двойные: чтобы посмотреть завтрашний
                    // день у края окна, приходилось прыгать через всю неделю.
                    h('button', {
                        class: 'btn btn--sm', title: 'На окно назад',
                        onclick: () => { rosterState.from = shiftIso(rosterState.from, -rosterState.span); load(); },
                    }, '«'),
                    h('button', {
                        class: 'btn btn--sm', title: 'На сутки назад',
                        onclick: () => {
                            rosterState.from = shiftIso(rosterState.from, -1);
                            rosterState.day = shiftIso(rosterState.day, -1);
                            load();
                        },
                    }, '‹'),
                    h('button', {
                        class: 'btn btn--sm',
                        onclick: () => {
                            rosterState.from = weekStart(todayIso());
                            rosterState.day = todayIso();
                            load();
                        },
                        title: 'С понедельника текущей недели',
                    }, 'Неделя'),
                    h('button', {
                        class: 'btn btn--sm',
                        title: 'Показать расход на завтра',
                        onclick: () => {
                            const tomorrow = shiftIso(todayIso(), 1);
                            rosterState.day = tomorrow;
                            // Окно оставляем как есть, если завтрашний день в
                            // него попадает. Раньше «Завтра» всегда ставило
                            // начало окна на сегодня, и от одного щелчка вся
                            // сетка перескакивала на другую неделю.
                            const after = shiftIso(rosterState.from, rosterState.span);
                            if (!(rosterState.from <= tomorrow && tomorrow < after)) {
                                rosterState.from = tomorrow;
                            }
                            load();
                        },
                    }, 'Завтра'),
                    h('button', {
                        class: 'btn btn--sm', title: 'На сутки вперёд',
                        onclick: () => {
                            rosterState.from = shiftIso(rosterState.from, 1);
                            rosterState.day = shiftIso(rosterState.day, 1);
                            load();
                        },
                    }, '›'),
                    h('button', {
                        class: 'btn btn--sm', title: 'На окно вперёд',
                        onclick: () => { rosterState.from = shiftIso(rosterState.from, rosterState.span); load(); },
                    }, '»'),
                    spanPick,
                    h('button', {
                        class: 'btn btn--sm',
                        title: 'Задать свой промежуток: с какого по какое число',
                        onclick: () => pickRosterPeriod(load),
                    }, 'Свой период'),
                    markSelf)),
            rangeLabel,
            daysBox,
            dayBox,
            gridBox,
            rosterLegend(),
        ]);

        async function load() {
            gridBox.appendChild(loadingBox());
            let data;
            try {
                data = await api.get('/api/roster?date_from=' + rosterState.from +
                    '&days=' + rosterState.span);
            } catch (error) {
                clear(gridBox);
                gridBox.appendChild(errorBox(error));
                return;
            }
            // День сводки держим внутри показанной недели: иначе человек
            // листает вперёд, а внизу висит позавчерашний расход.
            if (data.days.indexOf(rosterState.day) === -1) rosterState.day = data.days[0];
            rangeLabel.textContent = fmtDate(data.date_from) + ' — ' + fmtDate(data.date_to);
            // Поле выбора окна держим в согласии с показанным: свой промежуток
            // меняет размер окна в обход этого поля.
            syncSpanPick();
            drawGrid(data);
            drawDepartmentDays(data);
            await drawDay();
        }

        /* Дни, отмеченные на весь отдел: учения, собрание, общие работы.

           Это не расход одного человека, а то, что в этот день у отдела
           целиком. Записывать такое отсутствием пришлось бы двадцатью
           строками на один день — и счёт «сколько людей в строю» перестал бы
           сходиться. */
        function drawDepartmentDays(data) {
            clear(daysBox);
            const marked = data.department_days || {};
            const shown = [];
            const seen = {};
            data.days.forEach((day) => (marked[day] || []).forEach((item) => {
                if (seen[item.id]) return;
                seen[item.id] = true;
                shown.push(item);
            }));
            if (!shown.length && !data.can_mark_days) return;

            const row = h('div', { class: 'toolbar days-bar' });
            append(row, [
                h('span', { class: 'small muted' }, shown.length
                    ? 'Общие дни отдела:'
                    : 'Общих дней отдела на этот промежуток не отмечено'),
                shown.map((item) => h('span', {
                    class: 'chip day-chip day-' + item.kind,
                    title: [item.kind_title, item.note].filter(Boolean).join('. '),
                },
                    h('b', {}, item.title || item.kind_title),
                    h('span', { class: 'small faint' },
                        item.date_from === item.date_to
                            ? fmtDate(item.date_from)
                            : fmtDate(item.date_from) + '—' + fmtDate(item.date_to)),
                    data.can_mark_days ? h('button', {
                        class: 'chip-x', title: 'Снять отметку',
                        onclick: () => dropDepartmentDay(item),
                    }, '×') : null)),
                h('span', { class: 'grow' }),
                data.can_mark_days ? h('button', {
                    class: 'btn btn--sm',
                    title: 'Отметить день на весь отдел: общие работы, '
                        + 'занятия, собрание, нерабочий день',
                    onclick: () => markDepartmentDay(data),
                }, 'Отметить день отдела') : null,
            ]);
            daysBox.appendChild(row);
        }

        async function markDepartmentDay(data) {
            const kinds = data.day_kinds || [];
            const kind = h('select', {}, kinds.map((item) =>
                h('option', { value: item.id }, item.title)));
            const from = h('input', { type: 'date', value: rosterState.day });
            const to = h('input', { type: 'date', value: rosterState.day });
            const title = h('input', {
                type: 'text',
                placeholder: 'например, Парко-хозяйственный день',
            });
            const note = h('textarea', { rows: 2, placeholder: 'подробности (не обязательно)' });
            const submit = h('button', {
                class: 'btn btn--primary',
                onclick: async () => {
                    submit.disabled = true;
                    try {
                        await api.post('/api/roster/days', {
                            kind: kind.value,
                            date_from: from.value,
                            date_to: to.value || from.value,
                            title: title.value.trim(),
                            note: note.value.trim(),
                        });
                        dialog.close();
                        toast('День отдела отмечен', 'ok');
                        await load();
                    } catch (error) {
                        toastError(error);
                        submit.disabled = false;
                    }
                },
            }, 'Отметить');
            const dialog = openModal({
                title: 'День отдела',
                body: [
                    h('div', { class: 'small muted' },
                        'Отметка стоит на дне, а не на человеке: расход у всех '
                        + 'остаётся своим, а в сетке видно, что в этот день у '
                        + 'отдела общее дело.'),
                    h('label', { class: 'field' }, 'Что', kind),
                    h('div', { class: 'field-row' },
                        h('label', { class: 'field' }, 'С', from),
                        h('label', { class: 'field' }, 'По', to)),
                    h('label', { class: 'field' }, 'Название', title),
                    h('label', { class: 'field' }, 'Примечание', note),
                ],
                footer: [submit,
                    h('button', { class: 'btn', onclick: () => dialog.close() }, 'Отмена')],
            });
        }

        async function dropDepartmentDay(item) {
            const ok = await confirmDialog({
                title: 'Снять отметку',
                message: 'Отметка «' + (item.title || item.kind_title)
                    + '» будет снята со всего отдела.',
                confirmText: 'Снять',
                danger: true,
            });
            if (!ok) return;
            try {
                await api.del('/api/roster/days/' + item.id);
                await load();
            } catch (error) {
                toastError(error);
            }
        }

        function drawGrid(data) {
            clear(gridBox);
            const marked = data.department_days || {};
            const head = h('tr', {}, h('th', { class: 'roster-name' }, 'Военнослужащий'),
                data.days.map((day) => {
                    const dayMarks = marked[day] || [];
                    const first = dayMarks[0];
                    return h('th', {
                        class: 'roster-day' + (day === data.today ? ' is-today' : '')
                            + (isWeekend(day) ? ' is-weekend' : '')
                            + (day === rosterState.day ? ' is-picked' : '')
                            + (first ? ' is-marked day-' + first.kind : ''),
                        title: dayMarks.length
                            ? dayMarks.map((item) => item.title || item.kind_title).join('; ')
                            : 'Показать расход на этот день',
                        onclick: () => { rosterState.day = day; load(); },
                    },
                        h('b', {}, WEEKDAYS[new Date(day + 'T00:00:00').getDay()]),
                        h('span', {}, fmtDate(day).slice(0, 5)),
                        // Отметка на весь отдел стоит в шапке дня, а не в
                        // клетках: она про день, а не про человека, и
                        // повторять её двадцать раз в столбце незачем.
                        first ? h('i', { class: 'roster-day-mark' },
                            first.title || first.kind_title) : null);
                }));

            const body = h('tbody', {});
            data.staff.forEach((person) => {
                const cells = data.days.map((day) => {
                    const marks = data.cells[person.id + '|' + day] || [];
                    const mark = marks[0];
                    const classes = ['roster-cell'];
                    if (isWeekend(day)) classes.push('is-weekend');
                    if (day === data.today) classes.push('is-today');
                    if (mark) classes.push('kind-' + (ROSTER_KIND[mark.kind] || {}).cls);
                    if (person.can_edit) classes.push('is-mine');
                    return h('td', {
                        class: classes.join(' '),
                        title: mark
                            ? (mark.kind_title + (mark.place ? ' · ' + mark.place : '')
                                + (mark.note ? '\n' + mark.note : ''))
                            : (person.can_edit
                                ? 'На месте. Щёлкните, чтобы отметить другое'
                                : 'На месте'),
                        onclick: () => {
                            if (!person.can_edit) return;
                            openRosterDialog(mark || { user_id: person.id, date_from: day },
                                load);
                        },
                    }, mark
                        ? h('span', { class: 'roster-mark' },
                            h('b', {}, (ROSTER_KIND[mark.kind] || {}).short || mark.kind),
                            mark.place ? h('i', {}, mark.place) : null)
                        : (person.can_edit ? h('span', { class: 'roster-add' }, '+') : null));
                });
                // Как найти человека — подсказкой на фамилии: расход отвечает
                // «где он», и телефон тут же под рукой.
                const reach = [person.phone_open ? 'откр. ' + person.phone_open : '',
                    person.phone_secure ? 'реж. ' + person.phone_secure : '',
                    person.room ? 'каб. ' + person.room : '',
                    person.phone_mobile].filter(Boolean).join(' · ');
                // Должность и телефон — разные сведения, и одно другого не
                // отменяет. Стояло «телефон ИЛИ должность»: стоило человеку
                // вписать номер, и должность из расхода пропадала — а расход
                // читают как штатное расписание, по должностям.
                const post = roleShort(person.role);
                body.appendChild(h('tr', {},
                    h('td', {
                        class: 'roster-name' + (person.is_me ? ' is-me' : ''),
                        title: [person.role_title, reach].filter(Boolean).join(' · '),
                    },
                        personLink(person.id, person.full_name),
                        post ? h('div', { class: 'small faint' }, post) : null,
                        reach ? h('div', { class: 'small faint roster-reach' },
                            reach) : null),
                    cells));
            });

            gridBox.appendChild(h('div', { class: 'table-scroll' },
                h('table', { class: 'grid grid--roster' }, h('thead', {}, head), body)));
        }

        async function drawDay() {
            clear(dayBox);
            let day;
            try {
                day = await api.get('/api/roster/day?date=' + rosterState.day);
            } catch (error) {
                dayBox.appendChild(h('div', { class: 'small muted' }, errorText(error)));
                return;
            }
            append(dayBox, [
                h('div', { class: 'stat-cards' },
                    statCard(day.present, 'на месте ' + fmtDate(day.date),
                        day.unmarked.length
                            ? 'из них без отметки: ' + day.unmarked.length
                            : 'все отметились'),
                    statCard(day.away, 'отсутствуют',
                        'выезды, отпуска, больничные, учёба'),
                    statCard(day.marked, 'отметок в расходе',
                        'из ' + day.total + ' человек в отделе')),
                h('div', { class: 'card card-pad roster-day-card' },
                    h('div', { class: 'card-title' }, 'Расход на ' + fmtDate(day.date)),
                    rosterDayBoard(day),
                    day.marked === 0
                        ? h('div', { class: 'muted' },
                            'На этот день никто себя не отмечал — значит, весь '
                            + 'отдел на местах.')
                        : null),
            ]);
        }

        await load();
    }

    /* Кто где в этот день. Раньше это был столбик фамилий в цветной коробке:
       на десятерых читалось, на двадцати превращалось в простыню, которую
       надо прокручивать, чтобы найти одну фамилию.

       Теперь строка на состояние, а люди в ней — плашками с переносом: два
       десятка помещаются в три строки, глаз ловит нужную фамилию сразу, а
       щелчок открывает карточку военнослужащего. Отсутствующие идут первыми — их
       и ищут, присутствие в отделе подразумевается. */
    function rosterDayBoard(day) {
        const rows = [];
        day.groups.filter((group) => group.people.length).forEach((group) => rows.push({
            cls: ROSTER_KIND[group.id] ? ROSTER_KIND[group.id].cls : 'work',
            title: group.title,
            people: group.people,
            // Дежурство и работы — присутствие, остальное — отсутствие.
            away: PRESENT_ROSTER.indexOf(group.id) === -1,
        }));
        if (day.unmarked.length) {
            rows.push({
                cls: 'none', title: 'на месте, без отметки',
                people: day.unmarked, away: false,
            });
        }
        rows.sort((a, b) => (b.away ? 1 : 0) - (a.away ? 1 : 0));

        return h('div', { class: 'day-board' }, rows.map((row) =>
            h('div', { class: 'day-row' },
                h('div', { class: 'day-row-head' },
                    h('i', { class: 'kind-' + row.cls }),
                    h('b', {}, row.title),
                    h('span', { class: 'day-count' }, String(row.people.length))),
                h('div', { class: 'day-people' }, row.people.map((person) =>
                    h('button', {
                        class: 'day-chip kind-' + row.cls,
                        title: (person.place ? person.place + ' · ' : '')
                            + 'карточка военнослужащего',
                        onclick: () => openPerson(person.id),
                    },
                        h('span', { class: 'avatar avatar--xs' },
                            initials(person.full_name)),
                        person.full_name,
                        person.place
                            ? h('i', {}, person.place) : null))))));
    }

    /** Дежурство и работы — человек на месте; остальное — отсутствие. */
    const PRESENT_ROSTER = ['duty', 'work'];

    function rosterLegend() {
        return h('div', { class: 'roster-legend' },
            Object.keys(ROSTER_KIND).map((key) => h('span', { class: 'roster-legend-item' },
                h('i', { class: 'kind-' + ROSTER_KIND[key].cls }),
                ROSTER_KIND[key].title)),
            h('span', { class: 'small faint' },
                'Пустая клетка — человек на месте: отмечают отклонения, а не '
                + 'присутствие. Щёлкните по своей клетке, чтобы отметиться; '
                + 'по заголовку дня — чтобы увидеть расход на этот день.'));
    }

    /** Отметка в расходе: своя — у каждого, чужая — у начальника. */
    async function openRosterDialog(mark, after) {
        const existing = Boolean(mark && mark.id);
        const staff = await staffList();
        const me = state.user || {};
        const owner = existing ? mark.user_id : (mark.user_id || me.id);

        // Того, кого в расходе нет, подставлять нельзя. Список личного
        // состава не содержит создателя системы: он писем не ведёт и не
        // дежурит. А выпадающий список, не найдя своего человека, молча
        // встаёт на первого по алфавиту — и «Отметить себя» ставило наряд
        // Орловой. Отказ вслух лучше отметки не тому.
        if (!staff.some((person) => person.id === owner)) {
            toast(owner === me.id
                ? 'Вас нет в расходе отдела: создатель системы не дежурит и '
                  + 'писем не ведёт. Отмечать за себя нечего.'
                : 'Этого человека нет в расходе отдела — отметку поставить не за кого.',
                'error');
            return;
        }

        const whoPick = h('select', {}, staff.map((person) => h('option', {
            value: String(person.id), selected: person.id === owner,
        }, (person.full_name || person.login)
            + (person.id === (me || {}).id ? ' (я)' : ''))));
        // Чужой расход ведёт только начальство: инженеру список не нужен.
        whoPick.disabled = !isAdmin();

        const kindPick = h('select', {}, Object.keys(ROSTER_KIND).map((key) =>
            h('option', { value: key, selected: (mark.kind || 'duty') === key },
                ROSTER_KIND[key].title)));
        const fromInput = h('input', { type: 'date',
            value: mark.date_from || rosterState.day || todayIso() });
        const toInput = h('input', { type: 'date',
            value: mark.date_to || mark.date_from || rosterState.day || todayIso() });
        // Одна дата — обычный случай: отметился на завтра и забыл. Конец
        // тянется за началом, пока его не тронули руками.
        let toTouched = existing;
        fromInput.addEventListener('input', () => {
            if (toTouched || !fromInput.value) return;
            toInput.value = fromInput.value;
        });
        toInput.addEventListener('input', () => { toTouched = true; });
        const placeInput = h('input', {
            type: 'text', maxLength: 120, value: mark.place || '',
            placeholder: 'Узел 3, аппаратная 2, в/ч 74326',
            title: 'Где вы будете. Пишите как принято в отделе',
        });
        const noteInput = h('textarea', { rows: '2', maxLength: 300 }, mark.note || '');

        const save = h('button', { class: 'btn btn--primary', onclick: submit },
            existing ? 'Сохранить' : 'Отметить');

        const dialog = openModal({
            title: existing ? 'Отметка в расходе' : 'Отметить в расходе',
            body: [
                h('div', { class: 'form-grid' },
                    h('label', { class: 'field' }, 'Военнослужащий', whoPick),
                    h('label', { class: 'field' }, 'Чем занят', kindPick),
                    h('label', { class: 'field' }, 'С какого дня', fromInput),
                    h('label', { class: 'field' }, 'По какой день', toInput)),
                h('label', { class: 'field' }, 'Где', placeInput),
                h('label', { class: 'field' }, 'Примечание', noteInput),
            ],
            footer: [
                existing ? h('button', {
                    class: 'btn btn--danger-hover', onclick: remove,
                }, 'Убрать отметку') : null,
                h('span', { class: 'spacer' }),
                h('button', { class: 'btn', onclick: () => dialog.close() }, 'Отмена'),
                save,
            ],
            focus: 'select',
        });

        async function submit() {
            if (!fromInput.value) { toast('Укажите день', 'error'); return; }
            const payload = {
                kind: kindPick.value,
                date_from: fromInput.value,
                date_to: toInput.value || fromInput.value,
                place: placeInput.value.trim(),
                note: noteInput.value.trim(),
            };
            save.disabled = true;
            try {
                if (existing) {
                    await api.patch('/api/absences/' + mark.id, payload);
                } else {
                    payload.user_id = Number(whoPick.value) || me.id;
                    await api.post('/api/absences', payload);
                }
                dialog.close();
                toast('Расход обновлён', 'ok');
                if (after) after();
            } catch (error) {
                toastError(error);
            } finally {
                save.disabled = false;
            }
        }

        async function remove() {
            const ok = await confirmDialog({
                title: 'Убрать отметку',
                message: 'Отметка «' + (ROSTER_KIND[mark.kind] || {}).title + '» '
                    + 'с ' + fmtDate(mark.date_from) + ' по ' + fmtDate(mark.date_to)
                    + ' будет убрана из расхода.',
                confirmText: 'Убрать',
                danger: true,
            });
            if (!ok) return;
            try {
                await api.del('/api/absences/' + mark.id);
                dialog.close();
                toast('Отметка убрана', 'ok');
                if (after) after();
            } catch (error) {
                toastError(error);
            }
        }
    }

    // =====================================================================
    // 6. Экран письма: три панели
    // =====================================================================

    const wb = {
        case: null,
        coverage: {},
        reports: [],
        report: null,
        facts: null,
        files: [],
        filesError: '',
        rows: [],
        regs: [],
        findings: [],
        factsDirty: false,
        drafts: new Map(),
        dirty: new Set(),
        tab: 'sources',
        activeSource: null,
        focused: null,
        busy: false,
        nodes: {},
    };

    function resetWorkbench() {
        wb.case = null;
        wb.coverage = {};
        wb.reports = [];
        wb.report = null;
        wb.facts = null;
        wb.files = [];
        wb.filesError = '';
        wb.notes = [];
        wb.notesError = '';
        wb.rows = [];
        wb.findings = [];
        wb.factsDirty = false;
        wb.drafts = new Map();
        wb.dirty = new Set();
        wb.tab = 'sources';
        wb.activeSource = null;
        wb.focused = null;
        wb.busy = false;
        wb.coverageError = '';
        wb.nodes = {};
    }

    async function renderCase(view, caseRef) {
        resetWorkbench();
        const data = await api.get('/api/cases/' + encodeURIComponent(caseRef));
        wb.case = data.case;
        wb.coverage = data.coverage || {};
        wb.coverageError = data.coverage_error || '';
        wb.reports = (data.reports || []).slice().sort((a, b) => a.version - b.version);
        wb.facts = clone(wb.case.facts || {});
        rebuildFactRows();

        const latest = wb.reports.length ? wb.reports[wb.reports.length - 1] : null;
        if (latest) {
            try {
                wb.report = await loadReport(latest.id);
            } catch (error) {
                toastError(error);
            }
        }

        clear(view);
        view.appendChild(buildWorkbench());
        refreshAll();
        // Куда человек заходил — то и в «Недавнем»: письмо узнают по входящему
        // номеру, а без номера — по теме.
        rememberRecent('#/case/' + encodeURIComponent(caseRef),
            [wb.case.case_id, wb.case.title].filter(Boolean).join(' — ') || 'Письмо');
        // Список бумаг и примечания догружаем после отрисовки: письмо должно
        // открыться сразу, а не ждать ещё двух запросов.
        loadCaseFiles();
        loadCaseNotes();
    }

    /* Примечания к письму: переписка прямо на деле.

       Начальник пишет, что поправить, исполнитель отвечает — и всё остаётся
       при письме. Разговор у стола через неделю не вспомнить, а по бумаге,
       которую вернули на доработку, вопрос «что именно не так» возникает
       всегда. */
    async function loadCaseNotes() {
        try {
            const data = await api.get('/api/cases/' + wb.case.id + '/notes');
            wb.notes = data.notes || [];
            wb.notesError = '';
        } catch (error) {
            wb.notes = [];
            wb.notesError = errorText(error);
        }
        renderSidePanel();
    }

    async function addCaseNote(text, control) {
        if (!text.trim()) return false;
        if (control) control.disabled = true;
        try {
            await api.post('/api/cases/' + wb.case.id + '/notes', { text: text.trim() });
            await loadCaseNotes();
            return true;
        } catch (error) {
            toastError(error);
            return false;
        } finally {
            if (control) control.disabled = false;
        }
    }

    async function removeCaseNote(note) {
        const ok = await confirmDialog({
            title: 'Убрать примечание',
            message: 'Примечание будет удалено без следа.',
            confirmText: 'Убрать', danger: true,
        });
        if (!ok) return;
        try {
            await api.del('/api/cases/' + wb.case.id + '/notes/' + note.id);
            await loadCaseNotes();
        } catch (error) {
            toastError(error);
        }
    }

    function renderCaseNotes(body) {
        const notes = wb.notes || [];
        const field = h('textarea', {
            rows: 3, placeholder: 'Что поправить, о чём договорились, что уточнили',
        });
        const send = h('button', {
            class: 'btn btn--primary btn--sm',
            onclick: async () => {
                if (await addCaseNote(field.value, send)) field.value = '';
            },
        }, 'Добавить');

        if (canEdit()) {
            body.appendChild(h('div', { class: 'note-form' }, field,
                h('div', { class: 'toolbar' },
                    h('span', { class: 'small faint grow' },
                        'Увидит исполнитель и автор письма'),
                    send)));
        }

        if (!notes.length) {
            body.appendChild(emptyBox('Примечаний нет', wb.notesError
                || 'Здесь остаётся то, что сказали бы через стол: что '
                + 'поправить и о чём договорились.'));
            return;
        }

        const me = state.user || {};
        notes.forEach((note) => {
            body.appendChild(h('div', { class: 'note-item' },
                h('div', { class: 'note-head' },
                    h('b', {}, note.author || 'кто-то'),
                    h('span', {
                        class: 'small faint grow', title: fmtDateTime(note.created_at),
                    }, fmtWhen(note.created_at)),
                    // Своё убирает автор, чужое — начальство.
                    (note.user_id === me.id || isAdmin()) ? h('button', {
                        class: 'btn btn--icon btn--sm btn--danger-hover',
                        title: 'Убрать примечание',
                        onclick: () => removeCaseNote(note),
                    }, iconGlyph('trash')) : null),
                h('div', { class: 'note-text' }, note.text || '')));
        });
    }

    /** Загрузка редакции отчёта вместе со списком источников для правой панели. */
    async function loadReport(reportId) {
        const payload = await api.get('/api/reports/' + reportId);
        const report = normalizeReport(payload.report);
        const needsSources = report && !report.sources.length &&
            report.sections.some((section) => (section.sources || []).length);
        if (needsSources) {
            // Отдельный маршрут на случай, если отчёт отдан без вложенных цитат.
            const extra = await api.get('/api/reports/' + reportId + '/sources');
            report.sources = extra.items || [];
        }
        return report;
    }

    function normalizeReport(report) {
        if (!report) return null;
        const copy = Object.assign({}, report);
        copy.sections = (report.sections || []).slice().sort((a, b) => (a.ord || 0) - (b.ord || 0));
        copy.issues = report.issues || [];
        copy.sources = report.sources || (report.meta && report.meta.sources) || [];
        if (copy.errors === undefined) {
            copy.errors = copy.issues.filter((issue) => issue.level === 'error').length;
        }
        if (copy.warnings === undefined) {
            copy.warnings = copy.issues.filter((issue) => issue.level === 'warning').length;
        }
        return copy;
    }

    function buildWorkbench() {
        const screen = h('div', {
            style: { flex: '1', display: 'flex', flexDirection: 'column', minHeight: '0' },
        });

        const workbench = h('div', { class: 'workbench', id: 'workbench', dataset: { panel: 'report' } });
        const switcher = h('div', { class: 'panel-switch' },
            ['facts', 'report', 'side'].map((key) => h('button', {
                class: 'btn btn--sm' + (key === 'report' ? ' btn--primary' : ''),
                dataset: { panel: key },
                onclick: (event) => {
                    workbench.dataset.panel = key;
                    $$('.panel-switch button', screen).forEach((button) => {
                        button.classList.toggle('btn--primary', button === event.currentTarget);
                    });
                },
            }, { facts: 'Факты', report: 'Отчёт', side: 'Источники и замечания' }[key])));

        const layout = {
            left: parseInt(storageGet('rg-left', '400'), 10) || 400,
            right: parseInt(storageGet('rg-right', '360'), 10) || 360,
        };
        workbench.style.setProperty('--left-w', layout.left + 'px');
        workbench.style.setProperty('--right-w', layout.right + 'px');

        const leftSplitter = h('div', { class: 'splitter', title: 'Потяните, чтобы изменить ширину панели' });
        const rightSplitter = h('div', { class: 'splitter', title: 'Потяните, чтобы изменить ширину панели' });
        bindSplitter(leftSplitter, workbench, 'left', layout);
        bindSplitter(rightSplitter, workbench, 'right', layout);

        append(workbench, [
            buildFactsPanel(),
            leftSplitter,
            buildReportPanel(),
            rightSplitter,
            buildSidePanel(),
        ]);
        append(screen, [switcher, workbench]);
        return screen;
    }

    function bindSplitter(splitter, workbench, which, layout) {
        splitter.addEventListener('mousedown', (event) => {
            event.preventDefault();
            const startX = event.clientX;
            const startWidth = layout[which];
            splitter.classList.add('is-dragging');

            function onMove(moveEvent) {
                const delta = moveEvent.clientX - startX;
                const raw = which === 'left' ? startWidth + delta : startWidth - delta;
                const value = Math.min(900, Math.max(280, Math.round(raw)));
                layout[which] = value;
                workbench.style.setProperty(which === 'left' ? '--left-w' : '--right-w', value + 'px');
            }

            function onUp() {
                document.removeEventListener('mousemove', onMove);
                document.removeEventListener('mouseup', onUp);
                splitter.classList.remove('is-dragging');
                storageSet(which === 'left' ? 'rg-left' : 'rg-right', String(layout[which]));
                $$('.editor').forEach(autosize);
                $$('.section-card').forEach(syncBackdrop);
            }

            document.addEventListener('mousemove', onMove);
            document.addEventListener('mouseup', onUp);
        });
    }

    // -- панель фактов ------------------------------------------------------

    const MEASUREMENT_FIELDS = ['title', 'value', 'unit', 'method', 'uncertainty', 'source', 'note'];

    /** Раздел шаблона, который повторяется по описи (если он есть). */
    function repeatSection(outline) {
        return ((outline && outline.sections) || [])
            .find((section) => section.repeat_over) || null;
    }

    /** Имя списка описи для типа отчёта письма. Пусто — список не нужен. */
    function repeatName() {
        const section = repeatSection(outlineFor(wb.case && wb.case.report_type));
        return section ? section.repeat_over : '';
    }

    /** Поля, которые обязана иметь каждая запись описи. */
    function itemRequired() {
        const section = repeatSection(outlineFor(wb.case && wb.case.report_type));
        return section ? (section.item_required || []) : [];
    }

    /** Ключи, которые упомянуты в заголовке записи: {catalogs}, {caption}. */
    function itemTitleKeys() {
        const section = repeatSection(outlineFor(wb.case && wb.case.report_type));
        const found = [];
        String((section && section.item_title) || '')
            .replace(/\{([a-zA-Z_][a-zA-Z0-9_]*)\}/g, (whole, name) => {
                if (name !== 'n' && name !== 'caption' && found.indexOf(name) === -1) {
                    found.push(name);
                }
                return whole;
            });
        return found;
    }

    function rebuildFactRows() {
        const measurements = (wb.facts && wb.facts.measurements) || {};
        wb.rows = Object.keys(measurements).map((key) => {
            const raw = measurements[key] || {};
            const row = { key: key };
            MEASUREMENT_FIELDS.forEach((field) => {
                row[field] = raw[field] === undefined || raw[field] === null ? '' : String(raw[field]);
            });
            return row;
        });
        // Опись: список записей с произвольными полями. Держим его парами
        // «ключ — значение», а не готовым объектом: инженер правит и сами
        // имена полей, а объект порядок полей не хранит.
        const listName = repeatName();
        const list = (listName && wb.facts && Array.isArray(wb.facts[listName]))
            ? wb.facts[listName] : [];
        wb.regs = list.map((item) => ({
            fields: Object.keys(item || {}).map((key) => ({
                key: key,
                value: item[key] === undefined || item[key] === null ? '' : String(item[key]),
            })),
        }));
        wb.findings = ((wb.facts && wb.facts.findings) || []).map((finding) => ({
            id: finding.id || '',
            severity: finding.severity || 'info',
            title: finding.title || '',
            description: finding.description || '',
            evidence: (finding.evidence || []).join(', '),
            refs: (finding.refs || []).join(', '),
        }));
    }

    function parseValue(raw) {
        const text = String(raw === undefined || raw === null ? '' : raw).trim();
        if (text === '') return '';
        if (/^-?\d+(?:[.,]\d+)?(?:[eE][-+]?\d+)?$/.test(text)) {
            const number = Number(text.replace(',', '.'));
            if (isFinite(number)) return number;
        }
        return String(raw).trim();
    }

    function serializeFacts() {
        const facts = Object.assign({}, wb.facts || {});
        facts.case_id = wb.case.case_id;
        facts.report_type = wb.case.report_type;

        const measurements = {};
        wb.rows.forEach((row) => {
            const key = row.key.trim();
            if (!key) return;
            const item = { value: parseValue(row.value) };
            MEASUREMENT_FIELDS.forEach((field) => {
                if (field === 'value') return;
                const value = String(row[field] || '').trim();
                if (value) item[field] = value;
            });
            measurements[key] = item;
        });
        facts.measurements = measurements;

        const listName = repeatName();
        if (listName) {
            facts[listName] = (wb.regs || []).map((reg) => {
                const item = {};
                reg.fields.forEach((field) => {
                    const key = String(field.key || '').trim();
                    if (!key) return;
                    item[key] = parseValue(field.value);
                });
                return item;
            });
        }

        facts.findings = wb.findings.map((finding) => {
            const item = {
                id: finding.id.trim(),
                severity: finding.severity,
                title: finding.title.trim(),
            };
            if (finding.description.trim()) item.description = finding.description.trim();
            const evidence = splitList(finding.evidence);
            if (evidence.length) item.evidence = evidence;
            const refs = splitList(finding.refs);
            if (refs.length) item.refs = refs;
            return item;
        });
        return facts;
    }

    function splitList(value) {
        return String(value || '').split(',').map((item) => item.trim()).filter(Boolean);
    }

    /** Проверки, повторяющие требования схемы факт-пакета (док. 08). */
    function validateFacts() {
        const problems = [];
        const seen = new Set();
        wb.rows.forEach((row, index) => {
            const key = row.key.trim();
            if (!key) problems.push('измерение №' + (index + 1) + ': не заполнен ключ');
            else if (seen.has(key)) problems.push('ключ измерения «' + key + '» повторяется');
            else seen.add(key);
        });
        wb.findings.forEach((finding, index) => {
            const number = 'находка №' + (index + 1);
            if (!finding.id.trim()) problems.push(number + ': не заполнен идентификатор');
            if (!finding.title.trim()) problems.push(number + ': не заполнена формулировка');
            if (SEVERITIES.indexOf(finding.severity) === -1) problems.push(number + ': неизвестная критичность');
            splitList(finding.evidence).forEach((key) => {
                if (!seen.has(key)) {
                    problems.push(number + ': ссылка на несуществующее измерение «' + key + '»');
                }
            });
        });
        return problems;
    }

    function localCoverage() {
        const outline = outlineFor(wb.case.report_type);
        const have = new Set(wb.rows.map((row) => row.key.trim()).filter(Boolean));
        if (!outline) {
            // Шаблон неизвестен (его сняли или переименовали) — показываем то,
            // что посчитал сервер. Пустую опись он помечает служебным ключом
            // «__list__:имя»: показывать его человеку как есть нельзя.
            return Object.keys(wb.coverage || {}).map((sectionId) => ({
                id: sectionId,
                title: sectionId.indexOf('__list__:') === 0
                    ? 'Опись пуста' : sectionId,
                keys: wb.coverage[sectionId] || [],
            }));
        }
        const result = [];
        outline.sections.forEach((section) => {
            // Повторяющийся раздел спрашивает не общие измерения, а поля
            // каждой записи описи: их считаем отдельно, по карточкам.
            if (section.repeat_over) return;
            const missing = (section.required_facts || []).filter((key) => !have.has(key));
            if (missing.length) result.push({ id: section.id, title: section.title, keys: missing });
        });
        return result.concat(registrationGaps());
    }

    /** Чего не хватает записям описи: по строке на регистрацию. */
    function registrationGaps() {
        const required = itemRequired();
        if (!required.length) return [];
        const gaps = [];
        (wb.regs || []).forEach((reg, index) => {
            const missing = required.filter((key) => {
                const field = reg.fields.find((item) => String(item.key || '').trim() === key);
                return !field || !String(field.value || '').trim();
            });
            if (missing.length) {
                gaps.push({
                    id: 'reg-' + index, kind: 'reg', index: index,
                    title: registrationCaption(reg, index), keys: missing,
                });
            }
        });
        return gaps;
    }

    /** Подвести человека к пустому полю записи, а не просто назвать его. */
    function focusRegistrationField(index, key) {
        const cards = $$('.reg-card');
        const card = cards[index];
        if (!card) return;
        card.scrollIntoView({ block: 'nearest' });
        const input = card.querySelector('input[data-reg-field="' + key + '"]');
        if (input) input.focus();
    }

    function missingKeySet() {
        const keys = new Set();
        // Только общие измерения: поле записи описи и строка измерений могут
        // называться одинаково («modulation»), и пустая запись подсвечивала
        // бы заполненную строку в таблице.
        localCoverage()
            .filter((entry) => entry.kind !== 'reg')
            .forEach((entry) => entry.keys.forEach((key) => keys.add(key)));
        return keys;
    }

    function buildFactsPanel() {
        const saveButton = h('button', {
            class: 'btn btn--primary btn--sm', disabled: true,
            title: 'Сохранить данные (Ctrl+S)',
            onclick: () => saveFacts(),
        }, 'Сохранить');

        const body = h('div', { class: 'panel-body' });
        const digest = h('div', { class: 'small faint' });

        wb.nodes.factsBody = body;
        wb.nodes.factsSave = saveButton;
        wb.nodes.factsDigest = digest;

        // Бумаги письма стоят над фактами: с них работа и начинается —
        // сперва читают, что пришло, и только потом заносят числа.
        const filesBox = h('div', { class: 'case-files' });
        wb.nodes.caseFiles = filesBox;
        renderCaseFiles();

        return h('section', { class: 'panel panel--facts' },
            h('div', { class: 'panel-head' },
                h('div', { class: 'panel-head-row' },
                    h('span', { class: 'panel-title' }, 'Данные для отчёта'),
                    saveButton),
                h('div', { class: 'panel-head-row' }, digest)),
            filesBox,
            body);
    }

    /* Просмотр приложенного файла, не скачивая его.

       Скан письма хочется увидеть, а не положить в «Загрузки» и открывать
       сторонней программой: половина вложений в отделе — картинки, и весь
       смысл в том, чтобы взглянуть. Браузер сам рисует картинки, PDF и
       простой текст; всё прочее просмотру не поддаётся, и по нему честно
       говорится, что открыть можно только скачав. */
    const PREVIEW_IMAGE = ['png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp'];
    const PREVIEW_TEXT = ['txt', 'md', 'log', 'json', 'csv'];
    /* PDF и сканы показываем страницами, нарисованными на сервере.

       Раньше PDF стоял во встроенном окне — и не открывался вовсе. Чужой
       файл в своей странице — это чужой код в своей странице, поэтому окно
       стоит в песочнице и с запретом «default-src 'none'». Встроенный
       просмотрщик браузера — тоже код, и запрет глушил и его: человек
       нажимал на справку-объективку и получал пустой серый прямоугольник со
       словами «This page has been blocked by Chromium». Ждал, ничего не
       дождавшись, и шёл скачивать файл.

       Снимать запрет нельзя: PDF умеет исполнять свой код. Поэтому страницу
       рисует сервер и отдаёт картинкой — картинка кода не несёт ни при каком
       браузере. Заодно так показываются сканы TIFF, которые не показывает
       вообще ни один браузер. */
    const PREVIEW_PAGES = ['pdf', 'tif', 'tiff', 'xps', 'oxps', 'epub', 'cbz'];
    /* Документы Word, Excel и им подобные браузер не рисует и никогда не
       будет: это не формат для показа, а упакованный архив с разметкой.
       Но текст из них система уже вычитала при загрузке — тем же
       конвертером, что и библиотеку, — и показать его она может. Это не
       вид документа, а его содержимое, и говорится об этом прямо. */
    const PREVIEW_READ = ['docx', 'doc', 'rtf', 'odt', 'xlsx', 'xls'];
    /* Архив не показать никак: внутри может быть что угодно. */
    const PREVIEW_NONE = ['zip', '7z', 'rar'];

    function fileExt(name) {
        const dot = String(name || '').lastIndexOf('.');
        return dot === -1 ? '' : String(name).slice(dot + 1).toLowerCase();
    }

    /* Просмотрщик страниц: страница рисуется на сервере и приходит картинкой.

       Листается кнопками и стрелками на клавиатуре, соседняя страница
       подгружается заранее — на своей машине это мгновенно, а перелистывать
       книгу приятнее без ожидания. */
    function pageViewer(item, href) {
        const total = Number(item.pages || 0);
        const box = h('div', { class: 'pages-view', tabindex: '0' });
        box.addEventListener('keydown', (event) => {
            if (event.key === 'ArrowLeft') { show(current - 1); event.preventDefault(); }
            if (event.key === 'ArrowRight') { show(current + 1); event.preventDefault(); }
        });
        const canvas = h('div', { class: 'pages-sheet' }, h('div', { class: 'spinner' }));
        const label = h('span', { class: 'small muted pages-count' });
        let current = 1;
        let wide = false;

        const pageUrl = (number) =>
            href + (href.indexOf('?') === -1 ? '?' : '&') + 'page=' + number;

        const back = h('button', {
            class: 'btn btn--sm', title: 'Предыдущая страница',
            onclick: () => show(current - 1),
        }, '← назад');
        const forward = h('button', {
            class: 'btn btn--sm', title: 'Следующая страница',
            onclick: () => show(current + 1),
        }, 'вперёд →');
        // Страница целиком — чтобы увидеть вёрстку; по ширине — чтобы
        // прочитать. Нужно и то и другое: справку читают, схему разглядывают.
        const zoom = h('button', {
            class: 'btn btn--sm',
            title: 'Показать страницу целиком или растянуть по ширине окна',
            onclick: () => { wide = !wide; show(current); },
        }, 'по ширине');

        function show(number) {
            if (!total || number < 1 || number > total) return;
            current = number;
            back.disabled = current <= 1;
            forward.disabled = current >= total;
            zoom.textContent = wide ? 'страница целиком' : 'по ширине';
            label.textContent = 'страница ' + current + ' из ' + total;
            const image = h('img', {
                class: 'pages-image' + (wide ? ' is-wide' : ''),
                src: pageUrl(current),
                alt: 'Страница ' + current + ' — ' + item.name,
                onerror: () => {
                    clear(canvas);
                    canvas.appendChild(h('div', { class: 'muted' },
                        'Эту страницу показать не удалось — скачайте файл '
                        + 'и откройте своей программой.'));
                },
                onload: () => {
                    clear(canvas);
                    canvas.appendChild(image);
                    // Новую страницу показываем с её начала: без этого после
                    // перелистывания человек оказывался посреди чужого листа.
                    box.scrollTop = 0;
                    // Следующую готовим заранее, пока человек читает эту.
                    if (current < total) new Image().src = pageUrl(current + 1);
                },
            });
        }

        if (!total) {
            clear(canvas);
            canvas.appendChild(h('div', { class: 'muted' },
                'Страницы этого файла показать не получилось — скачайте его '
                + 'и откройте своей программой.'));
        } else {
            show(1);
        }

        box.appendChild(canvas);
        // Листалка живёт ВНЕ прокручиваемого листа. Растянутая по ширине
        // страница выше окна, и внутри она уезжала из виду вместе с текстом:
        // человек прокручивал страницу до конца и не находил, чем листать.
        const bar = h('div', { class: 'toolbar pages-bar' },
            total > 1 ? [back, label, forward] : label,
            total ? zoom : null);
        return { view: box, bar: bar, focus: () => box.focus() };
    }

    function openFilePreview(item, href, textHref) {
        const ext = fileExt(item.name);
        const inline = href + (href.indexOf('?') === -1 ? '?' : '&') + 'inline=1';
        // Документ Word показываем его текстом, и он занимает главное место
        // в окне, а не прячется в свёрнутой строке внизу: до сих пор по
        // .docx окно говорило «скачайте и откройте своей программой» — то
        // есть отказывалось показывать документ, который система уже
        // прочитала.
        const asText = PREVIEW_READ.indexOf(ext) !== -1;
        let view;
        let pager = null;
        if (PREVIEW_IMAGE.indexOf(ext) !== -1) {
            view = h('img', { class: 'preview-image', src: inline, alt: item.name });
        } else if (PREVIEW_PAGES.indexOf(ext) !== -1) {
            pager = pageViewer(item, href);
            view = pager.view;
        } else if (PREVIEW_TEXT.indexOf(ext) !== -1) {
            // Встроенное окно, а не вставка текста в разметку: чужой файл в
            // своей странице — это чужой код в своей странице. Сервер отдаёт
            // его в песочнице и с запретом переугадывать тип.
            view = h('iframe', {
                class: 'preview-frame', src: inline, title: item.name,
                sandbox: '', referrerpolicy: 'no-referrer',
            });
        } else if (asText) {
            view = h('div', { class: 'preview-doc' },
                h('div', { class: 'spinner' }));
        } else {
            view = h('div', { class: 'muted' },
                PREVIEW_NONE.indexOf(ext) !== -1
                    ? 'Архив на экране не раскрыть — скачайте и распакуйте.'
                    : 'Такой файл на экране не показать — скачайте и откройте '
                        + 'своей программой.');
        }

        // Что система вычитала из файла. Для Word это и есть показ, для
        // остальных — справка рядом: человек должен видеть, что попало в
        // поиск, и не рассчитывать на распознанное там, где его нет.
        const readBox = h('div', {});
        if (textHref && (asText || item.has_text)) {
            api.get(textHref).then((data) => {
                const text = (data.text || '').trim();
                if (asText) {
                    clear(view);
                    append(view, [text
                        ? [
                            h('div', { class: 'small muted preview-doc-note' },
                                'Так система прочитала документ: только текст, '
                                + 'без разметки, колонок и таблиц. Подлинник — '
                                + 'сам файл, его и скачивайте для правки и печати.'),
                            h('pre', {}, text + (data.truncated ? '\n…' : '')),
                        ]
                        : h('div', { class: 'muted' },
                            'Текст из документа прочитать не удалось — '
                            + 'скачайте и откройте своей программой.')]);
                    return;
                }
                if (!text) return;
                append(readBox, [h('details', { class: 'preview-text' },
                    h('summary', {}, data.recognised
                        ? 'Что распознала система'
                        : 'Что система вычитала из файла'),
                    data.recognised ? h('div', { class: 'small muted' },
                        'Текст получен машинным распознаванием. По нему ищется '
                        + 'письмо, но числа и обозначения сверяйте с оригиналом: '
                        + 'на снимке «3,5» и «8,5» различаются одним штрихом.') : null,
                    h('pre', {}, text + (data.truncated ? '\n…' : '')))]);
            }).catch(() => {
                if (!asText) return;
                clear(view);
                view.appendChild(h('div', { class: 'muted' },
                    'Текст из документа прочитать не удалось — скачайте и '
                    + 'откройте своей программой.'));
            });
        } else if (asText) {
            clear(view);
            view.appendChild(h('div', { class: 'muted' },
                'Текст этого документа система не сохранила — скачайте файл.'));
        }

        const dialog = openModal({
            title: item.name,
            wide: true,
            body: [
                h('div', { class: 'preview-box' }, view),
                pager ? pager.bar : null,
                item.note ? h('div', { class: 'small muted' }, item.note) : null,
                !asText && item.has_text === false ? h('div', { class: 'small muted' },
                    'Текст из файла прочитать не удалось: по словам из него '
                    + 'письмо не найдётся. Сам файл на месте.') : null,
                readBox,
            ],
            footer: [
                h('span', { class: 'small faint spacer' }, fmtBytes(item.size)),
                h('a', { class: 'btn', href: href }, 'Скачать'),
                h('button', { class: 'btn', onclick: () => dialog.close() }, 'Закрыть'),
            ],
        });
        // Стрелки листают сразу, без щелчка по листу.
        if (pager) setTimeout(() => pager.focus(), 0);
    }

    /* Приложенные к письму бумаги: скан письма, схема линии, журнал.
       Список отдельным запросом — он нужен и после того, как файл добавили
       или убрали, а перезагружать ради этого всё письмо расточительно. */
    async function loadCaseFiles() {
        try {
            const data = await api.get('/api/cases/' + wb.case.id + '/files');
            wb.files = data.files || [];
        } catch (error) {
            wb.files = [];
            wb.filesError = errorText(error);
        }
        renderCaseFiles();
    }

    function renderCaseFiles() {
        const box = wb.nodes.caseFiles;
        if (!box) return;
        clear(box);

        const picker = h('input', {
            type: 'file', multiple: true, style: { display: 'none' },
            onchange: async (event) => {
                const chosen = Array.from(event.target.files || []);
                event.target.value = '';
                for (const file of chosen) {
                    const form = new FormData();
                    form.append('file', file);
                    try {
                        await uploadFile('/api/cases/' + wb.case.id + '/files', form);
                    } catch (error) {
                        toast(file.name + ' — ' + errorText(error), 'error', 6000);
                    }
                }
                await loadCaseFiles();
            },
        });

        const items = wb.files || [];
        // Бумаги делим по тому, к чему они относятся: пришедшие с письмом и
        // ушедшие с ответом. В одной куче исполнитель через полгода уже не
        // отличит скан входящего от приложения к своему ответу.
        const incoming = items.filter((file) => file.stage !== 'outgoing');
        const outgoing = items.filter((file) => file.stage === 'outgoing');

        function fileRow(file) {
            return h('div', { class: 'file-row' },
                h('button', {
                    class: 'file-name file-name--link',
                    title: 'Посмотреть ' + file.name + (file.uploaded_by_name
                        ? ' · приложил ' + file.uploaded_by_name : ''),
                    onclick: () => openFilePreview(file,
                        '/api/cases/' + wb.case.id + '/files/' + file.id,
                        '/api/cases/' + wb.case.id + '/files/' + file.id + '/text'),
                }, file.name),
                h('span', { class: 'small faint nowrap' }, fmtBytes(file.size)),
                // Не прочиталось — значит, по словам из этой бумаги
                // письмо не найдётся. Человек должен это знать заранее.
                file.has_text ? null : h('span', {
                    class: 'small faint', title: 'Текст из файла прочитать не удалось: '
                        + 'по словам из него письмо не найдётся',
                }, 'без текста'),
                canEdit() && !isSent(wb.case) ? h('button', {
                    class: 'btn btn--icon btn--danger-hover',
                    title: 'Убрать файл из письма',
                    onclick: () => removeCaseFile(file),
                }, iconGlyph('trash')) : null);
        }

        append(box, [
            h('div', { class: 'toolbar' },
                h('span', { class: 'panel-title grow' }, 'Приложено к письму'),
                h('span', { class: 'small faint' }, incoming.length ? String(incoming.length) : ''),
                canEdit() && !isSent(wb.case) ? h('button', {
                    class: 'btn btn--sm', onclick: () => picker.click(),
                }, iconGlyph('clip'), 'Приложить') : null,
                picker),
            incoming.length ? h('div', { class: 'file-list' }, incoming.map(fileRow))
                : h('div', { class: 'small faint' },
                    wb.filesError || 'Ничего не приложено'),
            // Приложения к ответу показываем только когда они есть: у письма,
            // по которому ещё работают, этой стопки просто нет.
            outgoing.length ? h('div', { class: 'toolbar' },
                h('span', { class: 'panel-title grow' }, 'Ушло с ответом'),
                h('span', { class: 'small faint' }, String(outgoing.length))) : null,
            outgoing.length ? h('div', { class: 'file-list' }, outgoing.map(fileRow)) : null,
        ]);
    }

    async function removeCaseFile(file) {
        const ok = await confirmDialog({
            title: 'Убрать файл',
            message: 'Файл «' + file.name + '» будет убран из письма и удалён с диска.',
            confirmText: 'Убрать',
            danger: true,
        });
        if (!ok) return;
        try {
            await api.del('/api/cases/' + wb.case.id + '/files/' + file.id);
            toast('Файл убран', 'ok');
        } catch (error) {
            toastError(error);
        }
        await loadCaseFiles();
    }

    /** Ответ по письму уже отправлен: исходные бумаги задним числом не правят. */
    function isSent(item) {
        return Boolean(item && item.outgoing_no);
    }

    function markFactsDirty() {
        wb.factsDirty = true;
        if (wb.nodes.factsSave) wb.nodes.factsSave.disabled = !canEdit();
        updateFactsDigest();
    }

    function updateFactsDigest() {
        if (!wb.nodes.factsDigest) return;
        const parts = ['хеш: ' + (wb.case.facts_digest || '—').slice(0, 12)];
        parts.push('измерений: ' + wb.rows.length);
        parts.push('находок: ' + wb.findings.length);
        clear(wb.nodes.factsDigest);
        append(wb.nodes.factsDigest, [
            parts.join(' · '),
            wb.factsDirty ? h('span', { class: 'badge badge--warn', style: { marginLeft: '6px' } }, 'не сохранено') : null,
        ]);
    }

    function renderFactsBody() {
        const body = wb.nodes.factsBody;
        if (!body) return;
        const scroll = body.scrollTop;
        clear(body);
        renderFactsTable(body);
        body.scrollTop = scroll;
        updateFactsDigest();
    }

    /** Блок «каких обязательных измерений не хватает» — красные ключи из coverage. */
    function buildCoverageBox() {
        // Письмо заведено под сданный файлом отчёт: факт-пакета за ним нет и
        // не нужно. Требовать измерения не за чем — по этому письму никто не
        // собирается собирать отчёт системой.
        if (wb.report && wb.report.uploaded) {
            return h('div', { class: 'coverage-box coverage-box--calm' },
                h('b', {}, 'Отчёт написан человеком'),
                h('div', { class: 'small muted' },
                    'Измерения нужны, только когда отчёт собирает система. '
                    + 'Заполните их, если решите собрать свой вариант.'));
        }
        // Факт-пакет правили руками и сломали: расчёт покрытия не прошёл.
        // Письмо при этом открывается — иначе чинить пакет было бы негде.
        if (wb.coverageError) {
            return h('div', { class: 'coverage-box coverage-box--bad' },
                h('b', {}, 'Данные не разбираются'),
                h('div', { class: 'small' }, wb.coverageError),
                h('div', { class: 'small muted' },
                    'Поправьте значения в этой панели — до этого проверка '
                    + 'обязательных не работает.'));
        }
        const coverage = localCoverage();
        if (!coverage.length) {
            return h('div', { class: 'badge badge--ok', style: { marginBottom: '12px' } },
                'Всё, что нужно отчёту, занесено');
        }
        const box = h('div', { class: 'coverage-box' },
            h('b', {}, 'Не хватает данных'),
            h('div', { class: 'small muted' },
                'Щёлкните — строка добавится в таблицу.'));
        coverage.forEach((entry) => {
            box.appendChild(h('div', { class: 'coverage-line' },
                h('span', { class: 'small' }, entry.title + ': '),
                entry.keys.map((key) => entry.kind === 'reg'
                    ? h('button', {
                        class: 'chip',
                        title: 'Показать поле «' + factTitle(key) + '» этой регистрации',
                        onclick: () => focusRegistrationField(entry.index, key),
                    }, factTitle(key))
                    : h('button', {
                        class: 'chip',
                        title: 'Добавить строку «' + factTitle(key) + '» в таблицу',
                        onclick: () => addMeasurement(key),
                    }, factTitle(key), ' +'))));
        });
        return box;
    }

    function renderFactsTable(body) {
        const missing = missingKeySet();

        wb.nodes.coverageBox = buildCoverageBox();
        body.appendChild(wb.nodes.coverageBox);

        // -- общие сведения
        const general = h('div', { class: 'facts-section' },
            h('h4', {}, 'Общие сведения'),
            h('div', { class: 'kv' },
                h('dt', {}, 'учётный номер'), h('dd', { class: 'mono' }, wb.case.case_id),
                wb.case.incoming_no ? h('dt', {}, 'входящий') : null,
                wb.case.incoming_no
                    ? h('dd', { class: 'mono' }, wb.case.incoming_no) : null,
                wb.case.line_type ? h('dt', {}, 'линия связи') : null,
                wb.case.line_type
                    ? h('dd', {}, wb.case.line_title || LINE_TITLE[wb.case.line_type]) : null,
                wb.case.tc_no ? h('dt', {}, 'номер ТС') : null,
                wb.case.tc_no ? h('dd', { class: 'mono' }, wb.case.tc_no) : null,
                h('dt', {}, 'тип отчёта'), h('dd', {}, reportTypeTitle(wb.case.report_type)),
                h('dt', {}, 'состояние'), h('dd', {}, CASE_STATUS[wb.case.status] || wb.case.status)),
            h('label', { class: 'field', style: { marginTop: '8px' } }, 'Номер группы',
                h('input', {
                    type: 'text', placeholder: '1274',
                    value: wb.facts.group_no || wb.facts.customer || '', disabled: !canEdit(),
                    title: 'Откуда пришло письмо. Пишите как принято в отделе: 1274, 12/345, в/ч 74326, «2-я группа связи»',
                    oninput: (event) => {
                        // Прежний ключ убираем, иначе в пакете останутся два
                        // номера и прочитается не тот, который вписали.
                        wb.facts.group_no = event.target.value;
                        delete wb.facts.customer;
                        markFactsDirty();
                    },
                })),
            h('label', { class: 'field', style: { marginTop: '8px' } }, 'Суть обращения',
                h('textarea', {
                    rows: '3', disabled: !canEdit(),
                    oninput: (event) => { wb.facts.request = event.target.value; markFactsDirty(); },
                }, wb.facts.request || '')),
            h('label', { class: 'field', style: { marginTop: '8px' } }, 'Ключевые слова (через запятую)',
                h('input', {
                    type: 'text', value: (wb.facts.keywords || []).join(', '), disabled: !canEdit(),
                    oninput: (event) => {
                        wb.facts.keywords = splitList(event.target.value);
                        markFactsDirty();
                    },
                })));
        body.appendChild(general);

        // -- опись регистраций
        if (repeatName()) body.appendChild(registrationsSection());

        // -- измерения
        const tbody = h('tbody', {});
        const detailed = storageGet('facts-detailed', '0') === '1';
        const headCells = detailed
            ? [h('th', { class: 'col-key' }, 'Ключ'), h('th', {}, 'Название'),
               h('th', {}, 'Значение'), h('th', { class: 'col-unit' }, 'Ед.'),
               h('th', {}, 'Метод'), h('th', {}, 'Погрешность'),
               h('th', { class: 'col-act' })]
            : [h('th', {}, 'Что измерено'), h('th', { class: 'col-value' }, 'Значение'),
               h('th', { class: 'col-unit' }, 'Ед.'), h('th', { class: 'col-act' })];
        const table = h('table', { class: 'facts-table' + (detailed ? '' : ' is-compact') },
            h('thead', {}, h('tr', {}, ...headCells)),
            tbody);

        wb.rows.forEach((row) => tbody.appendChild(measurementRow(row, missing, detailed)));

        body.appendChild(h('div', { class: 'facts-section' },
            h('h4', {},
                'Что измерено ', h('span', { class: 'faint' }, '(' + wb.rows.length + ')'),
                h('label', { class: 'facts-toggle',
                    title: 'Показать технический ключ, способ измерения и погрешность' },
                    h('input', {
                        type: 'checkbox', checked: detailed,
                        onchange: (event) => {
                            storageSet('facts-detailed', event.target.checked ? '1' : '0');
                            renderFactsBody();
                        },
                    }), ' подробно')),
            h('div', { class: 'small faint', style: { marginBottom: '6px' } },
                'Других чисел в отчёте не будет.'),
            h('div', { class: 'table-scroll' }, table),
            canEdit() ? h('button', {
                class: 'btn btn--sm', style: { marginTop: '8px' },
                onclick: () => addMeasurement(''),
            }, '+ значение') : null));

        // -- находки
        const findingsBox = h('div', {});
        wb.findings.forEach((finding, index) => findingsBox.appendChild(findingCard(finding, index)));
        body.appendChild(h('div', { class: 'facts-section' },
            h('h4', {}, 'Что обнаружено ',
                h('span', { class: 'faint' }, '(' + wb.findings.length + ')')),
            findingsBox,
            canEdit() ? h('button', {
                class: 'btn btn--sm',
                onclick: () => {
                    wb.findings.push({
                        id: 'F' + (wb.findings.length + 1), severity: 'medium',
                        title: '', description: '', evidence: '', refs: '',
                    });
                    markFactsDirty();
                    renderFactsBody();
                },
            }, '+ отклонение') : null));


    }

    /** Опись регистраций: по разделу отчёта на каждую запись. */
    function registrationsSection() {
        const box = h('div', {});
        wb.regs.forEach((reg, index) => box.appendChild(registrationCard(reg, index)));
        if (!wb.regs.length) {
            box.appendChild(h('div', { class: 'small faint' },
                'Опись пуста: разделов по регистрациям в отчёте не будет.'));
        }
        // Ключ поля показываем в том же режиме «подробно», что и у измерений:
        // переключателей на одной панели должно быть не два, а один.
        const detailed = storageGet('facts-detailed', '0') === '1';
        return h('div', { class: 'facts-section reg-list' + (detailed ? ' is-detailed' : '') },
            h('h4', {}, 'Регистрации ',
                h('span', { class: 'faint' }, '(' + wb.regs.length + ')')),
            h('div', { class: 'small faint', style: { marginBottom: '6px' } },
                'Опись, по которой пришли сигналы. На каждую запись отчёт '
                + 'соберёт свой раздел — в этом же порядке.'),
            box,
            canEdit() ? h('button', {
                class: 'btn btn--sm', style: { marginTop: '8px' },
                onclick: () => addRegistration(),
            }, '+ регистрация') : null);
    }

    /** Как назвать запись в заголовке карточки. */
    function registrationCaption(reg, index) {
        const values = {};
        reg.fields.forEach((field) => {
            const key = String(field.key || '').trim();
            if (key) values[key] = String(field.value || '').trim();
        });
        if (values.caption) return values.caption;
        const named = itemTitleKeys().map((key) => values[key]).filter(Boolean);
        if (named.length) return named.join(', ');
        return 'Регистрация ' + (index + 1);
    }

    function registrationCard(reg, index) {
        const editable = canEdit();
        const required = itemRequired();
        const have = new Set(reg.fields.map((field) => String(field.key || '').trim()));
        const lacking = required.filter((key) => {
            const field = reg.fields.find((item) => String(item.key || '').trim() === key);
            return !field || !String(field.value || '').trim();
        });

        const rows = h('div', { class: 'reg-fields' });
        reg.fields.forEach((field) => rows.appendChild(registrationField(reg, field, required)));

        const missingChips = lacking
            .filter((key) => !have.has(key))
            .map((key) => h('button', {
                class: 'chip', title: 'Добавить поле «' + factTitle(key) + '»',
                onclick: () => {
                    reg.fields.push({ key: key, value: '' });
                    markFactsDirty();
                    renderFactsBody();
                },
            }, factTitle(key), ' +'));

        return h('div', { class: 'reg-card' + (lacking.length ? ' is-missing' : '') },
            h('div', { class: 'reg-head' },
                h('span', { class: 'reg-no' }, String(index + 1)),
                h('span', { class: 'reg-caption', title: registrationCaption(reg, index) },
                    registrationCaption(reg, index)),
                editable ? h('button', {
                    class: 'btn btn--icon btn--ghost', title: 'Поднять выше',
                    disabled: index === 0,
                    onclick: () => moveRegistration(index, -1),
                }, '↑') : null,
                editable ? h('button', {
                    class: 'btn btn--icon btn--ghost', title: 'Опустить ниже',
                    disabled: index === wb.regs.length - 1,
                    onclick: () => moveRegistration(index, 1),
                }, '↓') : null,
                editable ? h('button', {
                    class: 'btn btn--icon btn--ghost', title: 'Убрать регистрацию',
                    onclick: () => {
                        wb.regs.splice(index, 1);
                        markFactsDirty();
                        renderFactsBody();
                    },
                }, '×') : null),
            rows,
            missingChips.length
                ? h('div', { class: 'reg-missing' },
                    h('span', { class: 'small' }, 'не хватает: '), missingChips)
                : null,
            editable ? h('button', {
                class: 'btn btn--sm btn--ghost',
                onclick: () => {
                    reg.fields.push({ key: '', value: '' });
                    markFactsDirty();
                    renderFactsBody();
                },
            }, '+ поле') : null);
    }

    function registrationField(reg, field, required) {
        const editable = canEdit();
        const key = String(field.key || '').trim();
        const isRequired = required.indexOf(key) !== -1;
        const unit = factUnit(key);

        const keyInput = h('input', {
            type: 'text', class: 'key', value: field.key || '', placeholder: 'ключ',
            disabled: !editable || isRequired,
            title: isRequired
                ? 'Поле требуется шаблоном отчёта — имя менять нельзя'
                : 'Имя поля записи',
            oninput: (event) => {
                field.key = event.target.value;
                markFactsDirty();
            },
        });
        const valueInput = h('input', {
            type: 'text', value: field.value || '', disabled: !editable,
            placeholder: unit ? unit : 'значение',
            title: field.value || '',
            oninput: (event) => {
                field.value = event.target.value;
                event.target.title = event.target.value;
                // Перерисовать всю панель нельзя — потеряется фокус, поэтому
                // метку «пусто» снимаем с самого поля и с его карточки.
                if (isRequired) {
                    event.target.classList.toggle('is-bad', !event.target.value.trim());
                    const card = event.target.closest('.reg-card');
                    if (card) {
                        card.classList.toggle('is-missing',
                            !!card.querySelector('input.is-bad'));
                    }
                }
                // Заголовок карточки складывается из каталогов: не обновить
                // его сразу — и человек, заполнив опись, видит над каждой
                // записью безличное «Регистрация 3».
                if (key === 'caption' || itemTitleKeys().indexOf(key) !== -1) {
                    const card = event.target.closest('.reg-card');
                    const caption = card && card.querySelector('.reg-caption');
                    if (caption) {
                        const index = wb.regs.indexOf(reg);
                        const text = registrationCaption(reg, index);
                        caption.textContent = text;
                        caption.title = text;
                    }
                }
                markFactsDirty();
                refreshCoverageMarks();
            },
        });
        valueInput.dataset.regField = key;
        if (isRequired && !String(field.value || '').trim()) valueInput.classList.add('is-bad');

        return h('div', { class: 'reg-field' },
            h('span', { class: 'reg-label', title: key }, factTitle(key) || 'поле'),
            keyInput,
            valueInput,
            editable && !isRequired ? h('button', {
                class: 'btn btn--icon btn--ghost', title: 'Убрать поле',
                onclick: () => {
                    const index = reg.fields.indexOf(field);
                    if (index !== -1) reg.fields.splice(index, 1);
                    markFactsDirty();
                    renderFactsBody();
                },
            }, '×') : null);
    }

    function addRegistration() {
        // Новая запись сразу с полями, которых ждёт шаблон, и с теми, из
        // которых складывается её заголовок: пустую карточку человеку
        // пришлось бы заполнять ключами наугад.
        const keys = [];
        itemTitleKeys().concat(itemRequired()).forEach((key) => {
            if (keys.indexOf(key) === -1) keys.push(key);
        });
        wb.regs.push({ fields: keys.map((key) => ({ key: key, value: '' })) });
        markFactsDirty();
        renderFactsBody();
    }

    function moveRegistration(index, step) {
        const next = index + step;
        if (next < 0 || next >= wb.regs.length) return;
        const moved = wb.regs.splice(index, 1)[0];
        wb.regs.splice(next, 0, moved);
        markFactsDirty();
        renderFactsBody();
    }

    function measurementRow(row, missing, detailed) {
        const tr = h('tr', {});
        const editable = canEdit();

        function field(name, className, placeholder) {
            const input = h('input', {
                type: 'text', class: className || '', value: row[name] || '',
                placeholder: placeholder || '', disabled: !editable,
                title: row[name] || '',
                oninput: (event) => {
                    row[name] = event.target.value;
                    // В узкой панели текст не помещается целиком — показываем его по наведению.
                    event.target.title = event.target.value;
                    if (name === 'key' || name === 'value') refreshCoverageMarks();
                    markFactsDirty();
                },
            });
            input.dataset.field = name;
            if (name === 'value' && !String(row.value || '').trim()) input.classList.add('is-bad');
            return input;
        }

        const remove = h('td', {}, editable ? h('button', {
            class: 'btn btn--icon btn--ghost', title: 'Убрать строку',
            onclick: () => {
                const index = wb.rows.indexOf(row);
                if (index !== -1) wb.rows.splice(index, 1);
                markFactsDirty();
                renderFactsBody();
            },
        }, '×') : null);

        tr.dataset.key = row.key;
        if (missing.has(row.key)) tr.classList.add('is-missing');

        if (detailed) {
            append(tr, [
                h('td', {}, field('key', 'key', 'ключ')),
                h('td', {}, field('title', '', 'что измерено')),
                h('td', {}, field('value', '', 'значение')),
                h('td', {}, field('unit', '', 'ед.')),
                h('td', {}, field('method', '', 'как получено')),
                h('td', {}, field('uncertainty', '', '±')),
                remove,
            ]);
        } else {
            // Компактный режим: только название. Ключ вроде packet_count —
            // имя для кода, человеку он не говорит ничего, а места в панели
            // шириной 400 px занимает столько же, сколько название. Кому он
            // нужен — включает «подробно».
            append(tr, [
                h('td', {}, field('title', '', 'что измерено')),
                h('td', {}, field('value', '', 'значение')),
                h('td', {}, field('unit', '', 'ед.')),
                remove,
            ]);
        }
        return tr;
    }

    function refreshCoverageMarks() {
        // Обновляем только подсветку и блок покрытия: перерисовка таблицы
        // потеряла бы фокус в поле, которое сейчас правит инженер.
        const missing = missingKeySet();
        if (wb.nodes.coverageBox && wb.nodes.coverageBox.parentNode) {
            const fresh = buildCoverageBox();
            wb.nodes.coverageBox.replaceWith(fresh);
            wb.nodes.coverageBox = fresh;
        }
        $$('.facts-table tbody tr').forEach((tr, index) => {
            const row = wb.rows[index];
            if (!row) return;
            tr.classList.toggle('is-missing', missing.has(row.key.trim()));
            const valueInput = tr.querySelector('input[data-field="value"]');
            if (valueInput) valueInput.classList.toggle('is-bad', !String(row.value || '').trim());
        });
    }

    /* Как значение называется по-русски. Названия лежат в шаблоне рядом с
       ключами: заводят новый ключ — тут же и подписывают. Нет подписи —
       показываем сам ключ: это хуже, но честно, и видно, что подписать. */
    function factTitle(key) {
        const outline = outlineFor(wb.case && wb.case.report_type);
        const titles = (outline && outline.fact_titles) || {};
        return titles[key] || key;
    }

    function factUnit(key) {
        const outline = outlineFor(wb.case && wb.case.report_type);
        return ((outline && outline.fact_units) || {})[key] || '';
    }

    function addMeasurement(key) {
        wb.rows.push({
            key: key || '', title: key ? factTitle(key) : '', value: '',
            unit: key ? factUnit(key) : '', method: '', uncertainty: '',
            source: '', note: '',
        });
        markFactsDirty();
        renderFactsBody();
        const rows = $$('.facts-table tbody tr');
        const lastRow = rows[rows.length - 1];
        if (!lastRow) return;
        if (!key) {
            // Строку добавили вручную — начинают с названия: ключ человек
            // придумывать не должен, его подставит шаблон или он останется
            // пустым, и это законно.
            const titleInput = lastRow.querySelector('input[data-field="title"]');
            if (titleInput) titleInput.focus();
            return;
        }
        // Ключ уже известен (строку добавили из списка недостающих) — название
        // и единица подставлены шаблоном, курсор ставим сразу в «Значение».
        const value = lastRow.querySelector('input[data-field="value"]');
        if (value) value.focus();
    }

    function findingCard(finding, index) {
        const editable = canEdit();
        return h('div', { class: 'finding' },
            h('div', { class: 'finding-head' },
                h('input', {
                    type: 'text', class: 'fid', value: finding.id, placeholder: 'F1', disabled: !editable,
                    oninput: (event) => { finding.id = event.target.value; markFactsDirty(); },
                }),
                h('select', {
                    disabled: !editable,
                    onchange: (event) => { finding.severity = event.target.value; markFactsDirty(); },
                }, SEVERITIES.map((level) => h('option', {
                    value: level, selected: finding.severity === level,
                }, SEVERITY_LABEL[level]))),
                h('span', { style: { flex: '1' } }),
                editable ? h('button', {
                    class: 'btn btn--icon btn--ghost', title: 'Удалить находку',
                    onclick: () => {
                        wb.findings.splice(index, 1);
                        markFactsDirty();
                        renderFactsBody();
                    },
                }, '×') : null),
            h('input', {
                type: 'text', value: finding.title, placeholder: 'формулировка одной строкой',
                disabled: !editable,
                oninput: (event) => { finding.title = event.target.value; markFactsDirty(); },
            }),
            h('textarea', {
                placeholder: 'что именно наблюдается', disabled: !editable,
                oninput: (event) => { finding.description = event.target.value; markFactsDirty(); },
            }, finding.description),
            h('input', {
                type: 'text', class: 'mono', value: finding.evidence, disabled: !editable,
                placeholder: 'подтверждающие измерения: snr, evm',
                oninput: (event) => { finding.evidence = event.target.value; markFactsDirty(); },
            }),
            h('input', {
                type: 'text', value: finding.refs, disabled: !editable,
                placeholder: 'нормативные ссылки через запятую',
                oninput: (event) => { finding.refs = event.target.value; markFactsDirty(); },
            }));
    }

    async function saveFacts() {
        if (!canEdit()) {
            toast('Недостаточно прав: правка фактов доступна инженеру', 'error');
            return;
        }
        const problems = validateFacts();
        if (problems.length) {
            toast('Факт-пакет не сохранён: ' + problems.slice(0, 3).join('; ') +
                (problems.length > 3 ? ' и ещё ' + (problems.length - 3) : ''), 'error');
            return;
        }
        const facts = serializeFacts();

        const button = wb.nodes.factsSave;
        button.disabled = true;
        const label = button.textContent;
        button.textContent = 'Сохранение…';
        try {
            const data = await api.put('/api/cases/' + wb.case.id + '/facts', { facts: facts });
            wb.case = data.case;
            wb.coverage = data.coverage || {};
            wb.facts = clone(wb.case.facts || {});
            rebuildFactRows();
            wb.factsDirty = false;
            renderFactsBody();
            toast('Факт-пакет сохранён', 'ok');
            if (wb.report) {
                toast('Числа изменились — перепроверьте отчёт кнопкой «Проверить»', 'info');
            }
        } catch (error) {
            toastError(error);
        } finally {
            button.textContent = label;
            button.disabled = !wb.factsDirty;
        }
    }

    // -- центральная панель: отчёт -----------------------------------------

    function buildReportPanel() {
        const head = h('div', { class: 'report-head' });
        const body = h('div', { class: 'panel-body' });
        wb.nodes.reportHead = head;
        wb.nodes.reportBody = body;
        return h('section', { class: 'panel panel--report' }, head, body);
    }

    function renderReportHead() {
        const head = wb.nodes.reportHead;
        clear(head);
        const report = wb.report;
        const editable = canEdit();

        /* У письма один отчёт. То, что раньше звалось версиями, — это его
           редакции: собрал заново или сдал файлом ещё раз. Нынешняя —
           последняя, прежние остаются на чтение как история правок:
           по ним видно, что начальник вернул и что исполнитель поправил. */
        const currentReport = wb.reports.length
            ? wb.reports[wb.reports.length - 1] : null;
        const isCurrent = !report || !currentReport || report.id === currentReport.id;
        const versionSelect = h('select', {
            title: wb.reports.length < 2
                ? 'Отчёт по письму один'
                : 'Редакции отчёта: нынешняя и прежние, на чтение',
            disabled: wb.reports.length < 2,
            onchange: (event) => switchVersion(Number(event.target.value)),
        }, wb.reports.map((item) => h('option', {
            value: item.id, selected: report && item.id === report.id,
        }, (currentReport && item.id === currentReport.id
            ? 'отчёт (редакция ' + item.version + ')'
            : 'прежняя редакция ' + item.version)
            + ' · ' + (REPORT_STATUS[item.status] || item.status))));

        /* Ответ ушёл под исходящим номером — письмо закрыто. Работать
           можно только с нынешней редакцией и только до отправки: после
           неё отчёт обязан совпадать с тем, что ушло адресату. Сервер это
           и так не даст, но человек должен видеть погашенную кнопку, а не
           ловить отказ после нажатия. */
        const sent = !!(wb.case && wb.case.outgoing_no);
        const frozen = sent || !isCurrent;

        // Со сломанным факт-пакетом генерация всё равно откажет: кнопку
        // гасим и говорим почему, а не отправляем инженера за ошибкой.
        const broken = !!wb.coverageError;
        const generateButton = h('button', {
            class: 'btn' + (report ? '' : ' btn--primary'),
            disabled: !editable || wb.busy || broken || frozen,
            title: broken
                ? 'Сначала исправьте факт-пакет: ' + wb.coverageError
                : (report
                    ? 'Написать все разделы заново новой версией (прежние сохранятся)'
                    : 'Пройти по разделам шаблона и написать черновик ответа'),
            onclick: () => generateReport(),
        }, report ? 'Переписать заново' : 'Подготовить черновик');

        const verifyButton = h('button', {
            class: 'btn', disabled: !report || wb.busy,
            title: 'Пересчитать замечания верификатора',
            onclick: () => verifyReport(),
        }, 'Проверить');

        const exportButton = h('button', {
            class: 'btn', disabled: !report || wb.busy,
            onclick: () => exportDocx(),
        }, 'Экспорт в DOCX');

        /* Отчёт, написанный руками, кладётся прямо на письмо. Раньше для
           этого приходилось возвращаться в список и заново вводить входящий
           номер: ошибся в знаке — и вместо редакции по своему письму
           заводилось второе письмо-двойник. */
        const uploadOwnButton = h('button', {
            class: 'btn' + (report ? '' : ' btn--primary'),
            disabled: !editable || wb.busy || frozen,
            title: 'Приложить к этому письму отчёт, который вы написали сами',
            onclick: () => openUploadForCase(wb.case, () => renderRoute(state.route)),
        }, 'Загрузить свой отчёт');

        const errors = report ? report.errors || 0 : 0;
        const uploaded = !!(report && report.uploaded);
        const status = report ? report.status : '';

        /* Сдать отчёт начальнику может любой военнослужащий — свои отчёты в отдел
           сдают все. У сданного файлом отчёта чисел не сверяют: факт-пакета
           за ним нет, читает его человек. */
        const submitButton = h('button', {
            class: 'btn' + (status === 'draft' || status === 'rework' ? ' btn--primary' : ''),
            disabled: !report || !editable || wb.busy || frozen
                || status === 'review' || status === 'approved'
                || (!uploaded && errors > 0),
            title: (!uploaded && errors > 0)
                ? 'Сначала снимите ошибки верификатора: ' + errors
                : 'Отправить отчёт начальнику отдела на проверку',
            onclick: () => submitReport(),
        }, status === 'review' ? 'На проверке у начальника' : 'Отправить на проверку');

        /* Проверяет начальник отдела или заместитель. Остальным кнопки не
           показываем вовсе: несуществующее право не должно дразнить. */
        const approveButton = canReview() ? h('button', {
            class: 'btn btn--primary',
            disabled: !report || (!uploaded && errors > 0) || status === 'approved'
                || wb.busy || frozen,
            title: (!uploaded && errors > 0)
                ? 'Проверка заблокирована: верификатор нашёл ошибок — ' + errors
                : 'Отметить отчёт проверенным',
            onclick: () => approveReport(),
        }, status === 'approved' ? 'Проверен' : 'Отметить проверенным') : null;

        const reworkButton = canReview() ? h('button', {
            class: 'btn btn--danger-hover',
            disabled: !report || wb.busy || frozen
                || (status !== 'review' && status !== 'approved'),
            title: 'Вернуть исполнителю с замечанием',
            onclick: () => reworkReport(),
        }, 'Вернуть на исправление') : null;

        /* Последний шаг порядка отдела: ответ ушёл адресату, записываем
           исходящий номер. Отправляет исполнитель — тот же, кто готовил и
           сдавал отчёт; проверяет начальник, а отправляют все. */
        const sendButton = sent ? null : h('button', {
            class: 'btn' + (status === 'approved' ? ' btn--primary' : ''),
            disabled: !report || status !== 'approved' || wb.busy || !canEdit(),
            title: status === 'approved'
                ? 'Записать исходящий номер, под которым ушёл ответ'
                : 'Сначала начальник отдела должен отметить отчёт проверенным',
            onclick: () => sendCase(),
        }, 'Ответ отправлен');

        /* Отозвать отправку может проверяющий: запись учётная. */
        const unsendButton = (sent && canReview()) ? h('button', {
            class: 'btn btn--danger-hover', disabled: wb.busy,
            title: 'Снять запись об отправке и вернуть письмо к работе',
            onclick: () => unsendCase(),
        }, 'Отозвать отправку') : null;

        append(head, [
            h('div', { class: 'line' },
                h('div', { class: 'case-title' },
                    wb.case.title || reportTypeTitle(wb.case.report_type),
                    h('span', { class: 'case-id' },
                        wb.case.incoming_no || wb.case.case_id)),
                statusBadge(wb.case.status),
                // Срок и исполнитель — то, что спрашивают о письме первым.
                // Без них приходилось возвращаться в список.
                wb.case.deadline ? deadlineCell(wb.case) : null,
                h('span', { class: 'small muted nowrap' },
                    wb.case.assignee_name || 'исполнитель не назначен'),
                wb.case.group_no
                    ? h('span', { class: 'small muted' },
                        'группа ' + wb.case.group_no) : null,
                h('span', { class: 'spacer' }),
                canEdit() ? h('button', {
                    class: 'btn btn--sm',
                    title: 'Исполнитель, срок ответа, входящий номер, состояние',
                    onclick: () => openCaseCard(wb.case, () => renderRoute(state.route)),
                }, 'Карточка письма') : null,
                h('button', {
                    class: 'btn btn--sm',
                    title: 'Открыть разговор с помощником по этому письму',
                    onclick: (event) => askAssistantAboutCase(event.currentTarget),
                }, 'Спросить помощника'),
                canDeleteCase(wb.case) ? h('button', {
                    class: 'btn btn--sm btn--danger',
                    onclick: () => deleteCase(wb.case, () => navigate('#/cases')),
                }, isAdmin() ? 'Удалить письмо' : 'Убрать письмо') : null),
            h('div', { class: 'line' },
                wb.reports.length ? versionSelect : h('span', { class: 'small muted' }, 'отчёта ещё нет'),
                report ? reportStatusBadge(report) : null,
                // Открыта прежняя редакция: править и проверять её нельзя,
                // и человек должен видеть это, а не гадать, почему кнопки
                // не нажимаются.
                !isCurrent ? h('span', {
                    class: 'badge badge--warn',
                    title: 'Это прежняя редакция отчёта, открытая на чтение. '
                        + 'Работают с нынешней — последней в списке слева.',
                }, 'прежняя редакция') : null,
                // У сданного файлом отчёта факт-пакета нет: числа в нём не
                // сверялись ни с чем, и молчать об этом нельзя.
                uploaded ? h('span', {
                    class: 'badge badge--warn',
                    title: 'Отчёт написан вручную и загружен файлом. Числа в нём '
                        + 'система не сверяла — проверяет человек.',
                }, 'загружен файлом') : null,
                // Шапку документа при правке фактов никто не переписывает —
                // и правильно: пересборка сменила бы текст под подписью.
                // Значит, расхождение надо показать, а не прятать.
                report && report.facts_stale ? h('span', {
                    class: 'badge badge--warn',
                    title: 'Исходные данные письма правили после сборки этого '
                        + 'отчёта. В шапке документа стоят прежние сведения. '
                        + 'Чтобы обновить их — «Переписать заново».',
                }, 'собран по прежним данным') : null,
                report && !uploaded ? h('button', {
                    class: 'counter' + (errors ? ' has-errors' : ''),
                    title: 'Показать замечания',
                    onclick: () => { setTab('issues'); focusSidePanel(); },
                }, '● ошибок: ' + errors) : null,
                report && !uploaded ? h('button', {
                    class: 'counter' + (report.warnings ? ' has-warnings' : ''),
                    title: 'Показать предупреждения',
                    onclick: () => { setTab('issues'); focusSidePanel(); },
                }, '▲ предупреждений: ' + (report.warnings || 0)) : null,
                h('span', { style: { flex: '1' } }),
                uploadOwnButton,
                uploaded ? null : generateButton,
                uploaded ? null : verifyButton,
                uploaded ? h('button', {
                    class: 'btn', disabled: wb.busy,
                    title: 'Скачать файл, каким его сдали',
                    onclick: () => downloadReportFile(report),
                }, 'Скачать файл') : exportButton,
                submitButton, reworkButton, approveButton, sendButton, unsendButton),
            // Замечание проверяющего видит весь отдел, и в первую очередь
            // исполнитель: без него «требует исправления» ничего не значит.
            report && report.review_note
                ? h('div', { class: 'review-note' },
                    h('b', {}, 'Возвращено на исправление'),
                    h('div', {}, report.review_note))
                : null,
            /* Ответ ушёл, а верификатор нашёл в отчёте числа мимо
               факт-пакета. Отметку не снимаем — отзыв подписи не отзывает
               бумагу у адресата, — но молчать об этом нельзя: отдел должен
               решить, отзывать ли отправку и исправлять. */
            sent && !uploaded && errors > 0
                ? h('div', { class: 'review-note' },
                    h('b', {}, 'Ошибки в уже отправленном отчёте: ' + errors),
                    h('div', {}, 'Ответ ушёл под номером ' + wb.case.outgoing_no
                        + ', а проверка нашла в тексте числа мимо исходных данных. '
                        + 'Чтобы исправить, начальник отдела отзывает отправку. '
                        + 'Замечания — справа.'))
                : null,
            // Исходящий номер — вторая половина учёта: по нему в отделе
            // находят, чем ответили на письмо.
            sent
                ? h('div', { class: 'line small muted' },
                    h('span', {}, 'Ответ отправлен: '),
                    h('b', { class: 'mono' }, wb.case.outgoing_no),
                    wb.case.outgoing_date
                        ? h('span', {}, ' от ' + fmtDate(wb.case.outgoing_date)) : null,
                    wb.case.sent_by_name
                        ? h('span', {}, ' · ' + wb.case.sent_by_name) : null)
                : null,
        ]);
    }

    /** Значок состояния отчёта: в работе, на проверке, требует исправления. */
    function reportStatusBadge(report) {
        const tone = REPORT_STATUS_TONE[report.status] || '';
        return h('span', { class: 'badge' + (tone ? ' ' + tone : '') },
            REPORT_STATUS[report.status] || report.status);
    }

    /** Новый разговор с помощником, привязанный к текущему обращению. */
    async function askAssistantAboutCase(button) {
        if (button) button.disabled = true;
        try {
            const data = await api.post('/api/chats', {
                title: 'Обращение ' + wb.case.case_id,
                case_ref: wb.case.id,
            });
            navigate('#/chat/' + data.chat.id);
        } catch (error) {
            toastError(error);
            if (button) button.disabled = false;
        }
    }

    /* Порядок работы над письмом. Четыре шага, всегда одни и те же:
       без такой полосы инженер, открывший письмо впервые, не понимал, что
       делать раньше — заполнять измерения или жать «Сгенерировать». */
    /* Путь отчёта, который система собирает сама. */
    const CASE_STEPS = [
        { id: 'facts', title: 'Внести измерения' },
        { id: 'draft', title: 'Получить черновик' },
        { id: 'check', title: 'Проверить и поправить' },
        { id: 'review', title: 'Сдать начальнику' },
        { id: 'done', title: 'Проверено' },
        { id: 'sent', title: 'Ответ отправлен' },
    ];

    /* Путь отчёта, который написали руками и сдали файлом: шаблона и
       факт-пакета за ним нет, значит и шагов меньше. */
    const UPLOAD_STEPS = [
        { id: 'loaded', title: 'Отчёт загружен' },
        { id: 'review', title: 'Сдан на проверку' },
        { id: 'done', title: 'Проверено' },
        { id: 'sent', title: 'Ответ отправлен' },
    ];

    /** Какой шаг сейчас и что на нём делать. */
    function caseStep() {
        const report = wb.report;
        const uploaded = !!(report && report.uploaded);

        // Ответ ушёл под исходящим номером — работа по письму закончена.
        // Это последний шаг, и он важнее всех прочих признаков.
        if (wb.case && wb.case.outgoing_no) {
            return {
                id: 'sent', done: true, uploaded: uploaded,
                hint: 'Ответ отправлен под исходящим номером '
                    + wb.case.outgoing_no + '. Письмо закрыто, отчёт правке '
                    + 'не подлежит: он должен совпадать с тем, что ушло. '
                    + 'Понадобилось исправить — начальник отзывает отправку.',
            };
        }

        // Сданный файлом отчёт по шаблону не собирается: у него свой,
        // короткий путь — сдан и проверен.
        if (report && report.uploaded) {
            if (report.status === 'approved') {
                return {
                    id: 'done', uploaded: true,
                    hint: 'Отчёт проверен начальником отдела. Отправьте ответ '
                        + 'и нажмите «Ответ отправлен», чтобы записать '
                        + 'исходящий номер — иначе письмо остаётся незакрытым.',
                };
            }
            if (report.status === 'rework') {
                return {
                    id: 'review', errors: 1, uploaded: true,
                    hint: 'Начальник вернул отчёт: ' + (report.review_note || 'см. замечание')
                        + ' Исправьте документ и сдайте его заново — новой версией.',
                };
            }
            if (report.status === 'draft') {
                return {
                    id: 'loaded', uploaded: true,
                    hint: 'Отчёт загружен файлом. Посмотрите его и нажмите '
                        + '«Отправить на проверку» — до этого начальник его не '
                        + 'видит. Числа в таком отчёте система не сверяет: его '
                        + 'написал человек.',
                };
            }
            return {
                id: 'review', uploaded: true,
                hint: 'Отчёт сдан файлом и ждёт начальника отдела. Числа в нём '
                    + 'система не сверяла: факт-пакета за таким отчётом нет.',
            };
        }

        // Факт-пакет не разбирается — говорить «измерения на месте, сейчас
        // напишем черновик» нельзя: генерация всё равно откажет, а инженер
        // будет искать причину в другом месте.
        if (wb.coverageError) {
            return {
                id: 'facts', broken: true,
                hint: 'Факт-пакет не разбирается: ' + wb.coverageError
                    + ' Пока это не исправлено, черновик не построить — '
                    + 'поправьте пакет слева или в режиме JSON.',
            };
        }
        const missing = localCoverage().reduce((sum, item) => sum + item.keys.length, 0);
        if (!report) {
            return missing
                ? {
                    id: 'facts', missing: missing,
                    hint: 'Не хватает значений: ' + missing + '. Без них '
                        + 'разделы выйдут с пометкой «не хватает данных».',
                }
                : {
                    id: 'draft',
                    hint: 'Данные на месте. Система пройдёт по разделам шаблона '
                        + '«' + reportTypeTitle(wb.case.report_type) + '», подберёт '
                        + 'фрагменты библиотеки и напишет черновик.',
                };
        }
        if (report.status === 'approved') {
            return {
                id: 'done',
                hint: 'Отчёт проверен начальником отдела. Выгрузите его в DOCX, '
                    + 'отправьте ответ и нажмите «Ответ отправлен», чтобы '
                    + 'записать исходящий номер — иначе письмо остаётся '
                    + 'незакрытым и висит в работе.',
            };
        }
        if (report.status === 'review') {
            return {
                id: 'review',
                hint: 'Отчёт у начальника отдела на проверке. Правка вернёт его вам: '
                    + 'начальник должен читать то, что сдали.',
            };
        }
        if (report.status === 'rework') {
            return {
                id: 'check', errors: 1,
                hint: 'Начальник вернул отчёт: ' + (report.review_note || 'см. замечание')
                    + ' Поправьте разделы и отправьте на проверку заново.',
            };
        }
        const errors = report.errors || 0;
        if (errors) {
            return {
                id: 'check', errors: errors,
                hint: 'Проверка нашла ошибок: ' + errors + '. Пока они не сняты, '
                    + 'отчёт не отправить начальнику — числа в тексте должны '
                    + 'совпадать с измерениями. Замечания справа.',
            };
        }
        return {
            id: 'review',
            hint: 'Черновик готов, ошибок нет. Прочитайте разделы, поправьте '
                + 'формулировки — и отправляйте начальнику на проверку.',
        };
    }

    function stepStrip() {
        const step = caseStep();
        const steps = step.uploaded ? UPLOAD_STEPS : CASE_STEPS;
        const index = steps.map((item) => item.id).indexOf(step.id);
        const strip = h('div', { class: 'steps' });
        steps.forEach((item, position) => {
            const state = step.done || position < index ? ' is-past'
                : position === index ? ' is-now' : '';
            strip.appendChild(h('div', { class: 'step' + state },
                h('b', {}, String(position + 1)),
                h('span', {}, item.title)));
        });
        return h('div', { class: 'step-box' + (step.errors ? ' step-box--bad' : '') },
            strip,
            h('div', { class: 'step-hint' }, step.hint));
    }

    /** Сданный файлом отчёт: показываем прочитанный текст, а не одну кнопку.

        Начальник открывает отчёт, чтобы его прочитать. Заставлять его для
        этого скачивать файл и искать, чем открыть .docx, — лишний шаг на
        каждом отчёте отдела. Текст мы извлекаем при сдаче; показываем его
        здесь и честно говорим, что это чтение файла, а подлинник — файл. */
    function uploadedReportView(report) {
        const box = h('div', { class: 'section-card' });
        box.appendChild(h('header', {},
            h('h3', {}, report.file_name || 'файл'),
            h('button', {
                class: 'btn btn--sm',
                title: 'Открыть подлинник, как его сдали',
                onclick: () => downloadReportFile(report),
            }, 'Скачать файл')));
        const text = String(report.markdown || '').trim();
        const read = h('div', { class: 'section-read' });
        if (text) {
            read.appendChild(h('div', { class: 'small muted', style: { marginBottom: '10px' } },
                'Так система прочитала сданный файл. Оформление подлинника '
                + 'здесь не передаётся — за ним «Скачать файл».'));
            read.appendChild(renderMarkdown(text));
        } else {
            read.appendChild(h('div', { class: 'faint' },
                'Прочитать текст файла не удалось — откройте подлинник кнопкой '
                + '«Скачать файл».'));
        }
        box.appendChild(read);
        return box;
    }

    function renderSections() {
        const body = wb.nodes.reportBody;
        clear(body);
        const report = wb.report;

        if (!report) {
            body.appendChild(h('div', { class: 'sections' },
                stepStrip(),
                emptyBox('Ответ ещё не готовили',
                    'Модель соберёт черновик по фактам письма и фрагментам библиотеки. '
                    + 'Править его потом можно как угодно.',
                    h('button', {
                        class: 'btn btn--primary',
                        disabled: !canEdit() || !!wb.coverageError,
                        title: wb.coverageError
                            ? 'Сначала исправьте факт-пакет: ' + wb.coverageError : '',
                        onclick: () => generateReport(),
                    }, 'Подготовить черновик'))));
            return;
        }

        const container = h('div', { class: 'sections' });
        container.appendChild(stepStrip());
        report.sections.forEach((section) => container.appendChild(sectionCard(section)));
        if (!report.sections.length) {
            // У сданного файлом отчёта секций и не бывает: это не сборка по
            // шаблону, а документ, который инженер написал сам.
            container.appendChild(report.uploaded
                ? uploadedReportView(report)
                : emptyBox('Разделов в отчёте нет',
                    'Отчёт заведён, но шаблон к нему не применён. Выберите шаблон в карточке письма — разделы появятся с заготовками.'));
        }
        body.appendChild(container);
        $$('.editor', container).forEach(autosize);
        $$('.section-card', container).forEach(syncBackdrop);
    }

    function sectionCard(section) {
        const editable = canEdit();
        const draft = wb.drafts.has(section.section_id)
            ? wb.drafts.get(section.section_id)
            : section.text;

        const badges = h('div', { class: 'btn-row' });
        const backdrop = h('div', { class: 'editor-backdrop', 'aria-hidden': 'true' });
        const textarea = h('textarea', {
            class: 'editor', spellcheck: 'true', disabled: !editable,
            'aria-label': 'Текст раздела «' + section.title + '»',
        });
        textarea.value = draft;

        const hintInput = h('input', {
            type: 'text', class: 'hint',
            placeholder: 'пожелание к перегенерации: «подробнее про полосу»',
            disabled: !editable,
        });

        const saveButton = h('button', {
            class: 'btn btn--sm btn--primary', disabled: !editable || !wb.dirty.has(section.section_id),
            title: 'Сохранить раздел (Ctrl+S)',
            onclick: () => saveSection(section.section_id),
        }, 'Сохранить');

        const regenButton = h('button', {
            class: 'btn btn--sm', disabled: !editable,
            title: 'Перегенерировать раздел (Ctrl+Enter)',
            onclick: () => regenerateSection(section.section_id),
        }, 'Перегенерировать');

        const restoreButton = h('button', {
            class: 'btn btn--sm', disabled: !editable,
            title: 'Заменить текст раздела черновиком, который написала модель',
            hidden: !section.edited,
            onclick: () => restoreSection(section.section_id),
        }, 'Вернуть черновик модели');

        // Раздел читается заметно чаще, чем правится, а в тексте отчёта есть
        // таблицы и списки. В поле ввода они выглядят как «| Параметр | … |»,
        // поэтому по умолчанию показываем разметку, а правка — по щелчку.
        const readView = h('div', { class: 'section-read' });

        function paintRead() {
            clear(readView);
            const text = wb.drafts.has(section.section_id)
                ? wb.drafts.get(section.section_id)
                : section.text;
            if (String(text || '').trim()) {
                readView.appendChild(renderMarkdown(text));
            } else {
                readView.appendChild(h('div', { class: 'faint' }, 'раздел пуст'));
            }
            highlightCites(readView);
        }

        function setMode(editing) {
            card.classList.toggle('is-editing', editing);
            modeButton.textContent = editing ? 'Просмотр' : 'Править';
            modeButton.title = editing
                ? 'Вернуться к чтению с разметкой'
                : 'Править текст раздела';
            if (editing) {
                autosize(textarea);
                textarea.focus();
            } else {
                paintRead();
            }
        }

        const modeButton = h('button', {
            class: 'btn btn--sm btn--ghost',
            hidden: !editable,
            onclick: () => setMode(!card.classList.contains('is-editing')),
        }, 'Править');

        readView.addEventListener('click', (event) => {
            // Щелчок по ссылке на источник — это не «хочу править», а
            // «покажи фрагмент». Кнопки в отчёте рисовались с курсором-
            // пальцем и подсветкой, а обработчика у них не было вовсе:
            // инженер жал на метку и не получал ничего.
            const cite = event.target.closest('.cite');
            if (cite) {
                setActiveSource(cite.dataset.label);
                setTab('sources');
                return;
            }
            if (!editable) return;
            setMode(true);
        });

        const card = h('article', {
            class: 'section-card', id: domId('sec-', section.section_id),
            dataset: { section: section.section_id },
        },
            h('header', {},
                h('h3', {}, h('span', { class: 'ord' }, (section.ord + 1) + '.'), ' ', section.title),
                badges,
                modeButton,
                h('button', {
                    class: 'btn btn--icon btn--ghost', title: 'Свернуть или развернуть раздел',
                    onclick: (event) => {
                        const collapsed = card.classList.toggle('is-collapsed');
                        $$('.editor-wrap, .section-read, .section-actions, .section-sources', card)
                            .forEach((node) => { node.hidden = collapsed; });
                        event.currentTarget.textContent = collapsed ? '▸' : '▾';
                    },
                }, '▾')),
            readView,
            h('div', { class: 'editor-wrap' }, backdrop, textarea),
            h('div', { class: 'section-actions' }, hintInput, regenButton, saveButton, restoreButton),
            sourceChips(section));

        paintRead();

        textarea.addEventListener('input', () => {
            wb.drafts.set(section.section_id, textarea.value);
            if (textarea.value !== section.text) wb.dirty.add(section.section_id);
            else wb.dirty.delete(section.section_id);
            saveButton.disabled = !wb.dirty.has(section.section_id);
            autosize(textarea);
            syncBackdrop(card);
            renderBadges(badges, section);
        });
        textarea.addEventListener('focus', () => { wb.focused = section.section_id; });
        textarea.addEventListener('blur', () => { paintRead(); });

        renderBadges(badges, section);
        return card;
    }

    function renderBadges(container, section) {
        clear(container);
        const items = [];
        if (wb.dirty.has(section.section_id)) items.push(h('span', { class: 'badge badge--accent' }, 'не сохранено'));
        if (section.edited) items.push(h('span', { class: 'badge badge--warn' }, 'правлено'));
        if (section.regenerated > 0) {
            items.push(h('span', { class: 'badge badge--info' },
                'перегенерировано ' + section.regenerated + ' ' +
                plural(section.regenerated, 'раз', 'раза', 'раз')));
        }
        if (section.missing_facts && section.missing_facts.length) {
            items.push(h('span', {
                class: 'badge badge--danger',
                title: 'Отсутствующие ключи: ' + section.missing_facts.join(', '),
            }, 'не хватает данных: ' + section.missing_facts.join(', ')));
        }
        append(container, items);
    }

    function sourceChips(section) {
        const labels = section.sources || [];
        if (!labels.length) {
            return h('div', { class: 'section-sources' }, 'источники не привлекались');
        }
        return h('div', { class: 'section-sources' }, 'источники раздела:',
            labels.map((label) => h('button', {
                class: 'chip chip--src' + (wb.activeSource === label ? ' is-active' : ''),
                dataset: { label: label },
                title: 'Подсветить ссылки [' + label + '] в тексте',
                onclick: () => setActiveSource(label),
            }, label)));
    }

    function autosize(textarea) {
        textarea.style.height = 'auto';
        textarea.style.height = (textarea.scrollHeight + 2) + 'px';
    }

    function syncBackdrop(card) {
        const textarea = $('.editor', card);
        const backdrop = $('.editor-backdrop', card);
        if (!textarea || !backdrop) return;
        const text = textarea.value + '\n';
        // Разбор ссылок тот же, что везде: «[S1, S2]» — тоже ссылка, и
        // подсвечиваться она обязана так же, как одиночная.
        backdrop.innerHTML = escapeHtml(text).replace(CITATION_BOX, (match) => {
            const labels = citeLabels(match);
            const active = wb.activeSource && labels.indexOf(wb.activeSource) !== -1;
            return '<mark class="src-mark' + (active ? ' is-active' : '') + '">'
                + match + '</mark>';
        });
    }

    /** Отметить в разметке ссылки на выбранный источник. */
    function highlightCites(root) {
        $$('.cite', root).forEach((node) => {
            node.classList.toggle('is-active', wb.activeSource === node.dataset.label);
        });
    }

    function setActiveSource(label) {
        wb.activeSource = wb.activeSource === label ? null : label;
        $$('.section-card').forEach(syncBackdrop);
        $$('.chip--src').forEach((chip) => {
            chip.classList.toggle('is-active', chip.dataset.label === wb.activeSource);
        });
        renderSidePanel();
        if (!wb.activeSource) return;
        const section = (wb.report ? wb.report.sections : []).find((item) => {
            const text = wb.drafts.has(item.section_id)
                ? wb.drafts.get(item.section_id) : item.text;
            // Ищем по разобранным меткам, а не по подстроке «[S1]»: раздел,
            // сославшийся группой «[S1, S2]», подстрокой не находился.
            return (String(text).match(CITATION_BOX) || []).some(
                (box) => citeLabels(box).indexOf(wb.activeSource) !== -1);
        });
        if (section) flashSection(section.section_id);
    }

    function flashSection(sectionId) {
        const card = document.getElementById(domId('sec-', sectionId));
        if (!card) return;
        const workbench = document.getElementById('workbench');
        if (workbench && window.innerWidth < 1280) workbench.dataset.panel = 'report';
        card.scrollIntoView({ behavior: 'smooth', block: 'start' });
        card.classList.remove('is-flash');
        void card.offsetWidth;
        card.classList.add('is-flash');
        setTimeout(() => card.classList.remove('is-flash'), 1600);
    }

    function focusSidePanel() {
        const workbench = document.getElementById('workbench');
        if (workbench && window.innerWidth < 1280) workbench.dataset.panel = 'side';
    }

    function setSectionBusy(sectionId, busy, note) {
        const card = document.getElementById(domId('sec-', sectionId));
        if (!card) return;
        card.classList.toggle('is-busy', busy);
        const existing = $('.progress', card);
        if (busy && !existing) {
            const bar = h('div', { class: 'progress', title: note || '' }, h('i', {}));
            card.insertBefore(bar, card.firstChild.nextSibling);
        } else if (!busy && existing) {
            existing.remove();
        }
    }

    function lockLongOperation() {
        if (wb.busy) {
            toast('Дождитесь окончания текущей операции', 'error', 4000);
            return false;
        }
        wb.busy = true;
        renderReportHead();
        return true;
    }

    function unlockLongOperation() {
        wb.busy = false;
        renderReportHead();
    }

    async function generateReport() {
        if (!canEdit()) {
            toast('Недостаточно прав: генерация доступна инженеру', 'error');
            return;
        }
        if (wb.dirty.size) {
            const ok = await confirmDialog({
                title: 'Есть несохранённые правки',
                message: 'Отчёт будет написан заново новой редакцией. Несохранённые правки в нынешней пропадут; прежняя редакция останется в истории.',
                confirmText: 'Всё равно сгенерировать',
                danger: true,
            });
            if (!ok) return;
        }
        if (wb.factsDirty) {
            const ok = await confirmDialog({
                title: 'Факт-пакет не сохранён',
                message: 'Модель получит последний сохранённый факт-пакет, а не текущие правки. Продолжить?',
                confirmText: 'Генерировать',
            });
            if (!ok) return;
        }
        if (!lockLongOperation()) return;
        try {
            const data = await withOverlay(
                'Идёт генерация отчёта',
                'Секции пишутся последовательно, каждая со своими фактами и источниками. ' +
                'На отчёт в десятки страниц уходят минуты — не закрывайте вкладку.',
                () => api.post('/api/cases/' + wb.case.id + '/generate', {}));
            wb.drafts.clear();
            wb.dirty.clear();
            await reloadCase(data.report ? data.report.id : null);
            toast('Отчёт сгенерирован: версия ' + (wb.report ? wb.report.version : '?'), 'ok');
        } catch (error) {
            toastError(error);
        } finally {
            unlockLongOperation();
        }
    }

    async function reloadCase(preferReportId) {
        const data = await api.get('/api/cases/' + wb.case.id);
        wb.case = data.case;
        wb.coverage = data.coverage || {};
        wb.coverageError = data.coverage_error || '';
        wb.reports = (data.reports || []).slice().sort((a, b) => a.version - b.version);
        if (!wb.factsDirty) {
            wb.facts = clone(wb.case.facts || {});
            rebuildFactRows();
        }
        const target = preferReportId ||
            (wb.reports.length ? wb.reports[wb.reports.length - 1].id : null);
        if (target) {
            wb.report = await loadReport(target);
        } else {
            wb.report = null;
        }
        refreshAll();
    }

    async function switchVersion(reportId) {
        if (!reportId || (wb.report && wb.report.id === reportId)) return;
        if (wb.dirty.size) {
            const ok = await confirmDialog({
                title: 'Есть несохранённые правки',
                message: 'Переход к другой редакции отчёта потеряет несохранённые правки (' +
                    wb.dirty.size + ' ' + plural(wb.dirty.size, 'раздел', 'раздела', 'разделов') + ').',
                confirmText: 'Переключить',
                danger: true,
            });
            if (!ok) {
                renderReportHead();
                return;
            }
        }
        wb.drafts.clear();
        wb.dirty.clear();
        try {
            wb.report = await loadReport(reportId);
            refreshAll();
        } catch (error) {
            toastError(error);
        }
    }

    function mergeReportPatch(patch) {
        if (!patch || !wb.report) return;
        ['status', 'errors', 'warnings', 'issues', 'markdown', 'version', 'meta', 'approved_at']
            .forEach((key) => {
                if (patch[key] !== undefined) wb.report[key] = patch[key];
            });
        if (Array.isArray(patch.sources)) wb.report.sources = patch.sources;
        if (Array.isArray(patch.sections) && patch.sections.length) {
            wb.report.sections = patch.sections.slice().sort((a, b) => (a.ord || 0) - (b.ord || 0));
        }
        if (patch.issues !== undefined) {
            if (patch.errors === undefined) {
                wb.report.errors = wb.report.issues.filter((issue) => issue.level === 'error').length;
            }
            if (patch.warnings === undefined) {
                wb.report.warnings = wb.report.issues.filter((issue) => issue.level === 'warning').length;
            }
        }
    }

    function replaceSectionCard(sectionId) {
        const section = (wb.report.sections || []).find((item) => item.section_id === sectionId);
        const old = document.getElementById(domId('sec-', sectionId));
        if (!section || !old) {
            renderSections();
            return;
        }
        const card = sectionCard(section);
        old.replaceWith(card);
        autosize($('.editor', card));
        syncBackdrop(card);
    }

    async function saveSection(sectionId) {
        if (!wb.report || !canEdit()) return;
        if (!wb.dirty.has(sectionId)) {
            toast('В разделе нет несохранённых правок', 'info', 3000);
            return;
        }
        // Правка подписанного отчёта снимает подпись — молча этого делать
        // нельзя: инженер мог открыть раздел, чтобы просто перечитать.
        if (!(await confirmUnsign())) return;
        const text = wb.drafts.get(sectionId);
        setSectionBusy(sectionId, true, 'Сохранение и пересборка отчёта');
        try {
            const data = await api.put(
                '/api/reports/' + wb.report.id + '/sections/' + encodeURIComponent(sectionId),
                { text: text });
            applySectionResult(sectionId, data);
            toast('Раздел сохранён, отчёт пересобран и перепроверен', 'ok', 4000);
        } catch (error) {
            toastError(error);
        } finally {
            setSectionBusy(sectionId, false);
        }
    }

    /** Согласие снять подпись, если отчёт уже утверждён. */
    async function confirmUnsign() {
        if (!wb.report || wb.report.status !== 'approved') return true;
        return confirmDialog({
            title: 'Отчёт подписан',
            message: 'Отчёт (редакция ' + wb.report.version + ') проверен. '
                + 'Правка снимет подпись: подпись стоит под тем текстом, '
                + 'который прочитал утвердивший.',
            note: 'После правки отчёт нужно будет утвердить заново.',
            confirmText: 'Править и снять подпись',
        });
    }

    async function regenerateSection(sectionId) {
        if (!wb.report || !canEdit()) return;
        if (wb.dirty.has(sectionId)) {
            const ok = await confirmDialog({
                title: 'Перегенерировать раздел',
                message: 'Несохранённые правки этого раздела будут заменены новым текстом модели.',
                confirmText: 'Перегенерировать',
                danger: true,
            });
            if (!ok) return;
        }
        if (!lockLongOperation()) return;
        const card = document.getElementById(domId('sec-', sectionId));
        const hintInput = card ? $('.hint', card) : null;
        const hint = hintInput ? hintInput.value.trim() : '';
        setSectionBusy(sectionId, true, 'Модель пишет раздел заново');
        try {
            const data = await api.post(
                '/api/reports/' + wb.report.id + '/sections/' + encodeURIComponent(sectionId) + '/regenerate',
                hint ? { hint: hint } : {});
            applySectionResult(sectionId, data);
            toast('Раздел перегенерирован', 'ok', 4000);
        } catch (error) {
            toastError(error);
        } finally {
            setSectionBusy(sectionId, false);
            unlockLongOperation();
        }
    }

    async function restoreSection(sectionId) {
        if (!wb.report || !canEdit()) return;
        const section = wb.report.sections.find((item) => item.section_id === sectionId);
        if (!section) return;
        const ok = await confirmDialog({
            title: 'Вернуть черновик модели',
            message: 'Текущий текст раздела «' + section.title +
                '» будет заменён исходным черновиком модели.',
            note: wb.report.status === 'approved'
                ? 'Отчёт утверждён — правка снимет подпись, утвердить придётся заново.' : '',
            confirmText: 'Вернуть черновик',
            danger: true,
        });
        if (!ok) return;

        setSectionBusy(sectionId, true, 'Возврат черновика');
        const base = '/api/reports/' + wb.report.id + '/sections/' + encodeURIComponent(sectionId);
        try {
            let data;
            try {
                data = await api.post(base + '/restore', {});
            } catch (error) {
                // Если отдельного маршрута возврата нет, пишем черновик как обычную правку.
                if (error instanceof ApiError && (error.status === 404 || error.status === 405)) {
                    data = await api.put(base, { text: section.draft_text || '' });
                } else {
                    throw error;
                }
            }
            applySectionResult(sectionId, data);
            toast('Черновик модели возвращён', 'ok', 4000);
        } catch (error) {
            toastError(error);
        } finally {
            setSectionBusy(sectionId, false);
        }
    }

    function applySectionResult(sectionId, data) {
        wb.drafts.delete(sectionId);
        wb.dirty.delete(sectionId);
        mergeReportPatch(data.report);
        if (data.section) {
            const index = wb.report.sections.findIndex((item) => item.section_id === sectionId);
            if (index === -1) wb.report.sections.push(data.section);
            else wb.report.sections[index] = data.section;
            wb.report.sections.sort((a, b) => (a.ord || 0) - (b.ord || 0));
        }
        replaceSectionCard(sectionId);
        renderReportHead();
        renderSidePanel();
    }

    async function verifyReport() {
        if (!wb.report) return;
        try {
            const data = await withOverlay('Проверка отчёта', 'Верификатор сверяет числа, ссылки и структуру.',
                () => api.post('/api/reports/' + wb.report.id + '/verify', {}));
            wb.report.issues = data.issues || [];
            wb.report.errors = data.errors !== undefined
                ? data.errors
                : wb.report.issues.filter((issue) => issue.level === 'error').length;
            wb.report.warnings = data.warnings !== undefined
                ? data.warnings
                : wb.report.issues.filter((issue) => issue.level === 'warning').length;
            renderReportHead();
            setTab('issues');
            const errors = wb.report.errors;
            toast(errors
                ? 'Проверка завершена: ошибок — ' + errors + ', предупреждений — ' + wb.report.warnings
                : 'Ошибок нет, предупреждений — ' + wb.report.warnings,
                errors ? 'error' : 'ok');
        } catch (error) {
            toastError(error);
        }
    }

    /** Сдать отчёт начальнику отдела на проверку. Может любой военнослужащий. */
    async function submitReport() {
        if (!wb.report) return;
        if (wb.dirty.size) {
            toast('Сначала сохраните правки разделов: ' + wb.dirty.size, 'error');
            return;
        }
        if (!wb.report.uploaded && (wb.report.errors || 0) > 0) {
            toast('Сначала снимите ошибки верификатора: ' + wb.report.errors, 'error');
            return;
        }
        const ok = await confirmDialog({
            title: 'Отправить на проверку',
            message: 'Отчёт (редакция ' + wb.report.version + ') по письму ' + wb.case.case_id
                + ' уйдёт на проверку начальнику отдела. Письмо перейдёт '
                + 'в состояние «на проверке».',
            note: 'Правка отчёта после отправки вернёт его вам: начальник должен '
                + 'читать то, что сдали.',
            confirmText: 'Отправить',
        });
        if (!ok) return;
        try {
            const data = await api.post('/api/reports/' + wb.report.id + '/submit', {});
            wb.report = normalizeReport(data.report) || wb.report;
            await reloadCase(wb.report.id);
            toast('Отчёт отправлен на проверку', 'ok');
        } catch (error) {
            toastError(error);
        }
    }

    /** Вернуть отчёт исполнителю с замечанием. Только начальник или зам. */
    async function reworkReport() {
        if (!wb.report) return;
        const note = await promptDialog({
            multiline: true,
            title: 'Вернуть на исправление',
            message: 'Что исправить в отчёте (редакция ' + wb.report.version + ')'
                + ' по письму ' + wb.case.case_id + '?',
            note: 'Замечание увидит исполнитель и весь отдел — пишите так, '
                + 'чтобы по нему можно было работать.',
            placeholder: 'например: в выводах нет ссылки на методику измерений',
            confirmText: 'Вернуть исполнителю',
        });
        if (!note) return;
        try {
            const data = await api.post('/api/reports/' + wb.report.id + '/rework',
                { note: note });
            wb.report = normalizeReport(data.report) || wb.report;
            await reloadCase(wb.report.id);
            toast('Отчёт возвращён исполнителю', 'ok');
        } catch (error) {
            toastError(error);
        }
    }

    /** Скачать сданный файлом отчёт таким, каким его сдали. */
    function downloadReportFile(report) {
        window.open('/api/reports/' + report.id + '/file', '_blank');
    }

    /** Отметить отчёт проверенным. Только начальник отдела или заместитель. */
    async function approveReport() {
        if (!wb.report) return;
        if (!wb.report.uploaded && (wb.report.errors || 0) > 0) {
            toast('Проверка заблокирована: сначала снимите ошибки верификатора', 'error');
            return;
        }
        const ok = await confirmDialog({
            title: 'Отметить проверенным',
            message: 'Отчёт (редакция ' + wb.report.version + ') по письму ' + wb.case.case_id +
                ' будет отмечен проверенным. Письмо перейдёт в состояние '
                + '«проверен, к отправке»: дальше исполнитель отправляет ответ '
                + 'и записывает исходящий номер.',
            note: wb.report.uploaded
                ? 'Отчёт сдан файлом: числа в нём система не сверяла, вы проверяете сами.'
                : 'Разделы, которые переписал исполнитель, сохранятся парами '
                  + '«черновик модели → текст инженера»: по ним потом дообучают модель.',
            confirmText: 'Проверен',
        });
        if (!ok) return;
        try {
            const data = await withOverlay('Проверка отчёта', 'Сохраняются правки для обучающего набора.',
                () => api.post('/api/reports/' + wb.report.id + '/approve', {}));
            wb.report = normalizeReport(data.report) || wb.report;
            await reloadCase(wb.report.id);
            toast('Отчёт отмечен проверенным. Отправьте ответ и запишите '
                + 'исходящий номер', 'ok', 6000);
        } catch (error) {
            toastError(error);
        }
    }

    /** Ответ по письму ушёл адресату: записываем исходящий номер. */
    async function sendCase() {
        if (!wb.case) return;
        const number = h('input', {
            type: 'text', class: 'mono', placeholder: 'ИСХ-2026-0915',
            maxLength: CARD_LIMIT.outgoing_no,
        });
        const when = h('input', { type: 'date', value: casesState.today || todayIso() });
        const outNote = h('textarea', {
            rows: '3', maxLength: CARD_LIMIT.outgoing_note,
            placeholder: 'чем ответили, куда ушло, особые обстоятельства',
        });
        // Приложения к ответу собираем здесь же и кладём после записи номера:
        // до неё письмо ещё не отправлено, и приложениям к ответу неоткуда
        // взяться.
        let picked = [];
        const fileList = h('div', { class: 'file-list' });
        const picker = h('input', {
            type: 'file', multiple: true, style: { display: 'none' },
            onchange: (event) => {
                Array.from(event.target.files || []).forEach((file) => {
                    if (!picked.some((item) => item.name === file.name
                            && item.size === file.size)) picked.push(file);
                });
                event.target.value = '';
                drawFiles();
            },
        });

        function drawFiles() {
            clear(fileList);
            if (!picked.length) {
                fileList.appendChild(h('div', { class: 'small faint' },
                    'Что ушло вместе с ответом: сам ответ, приложения к нему'));
                return;
            }
            picked.forEach((file, index) => fileList.appendChild(
                h('div', { class: 'file-row' },
                    h('span', { class: 'file-name' }, file.name),
                    h('span', { class: 'small faint' }, fmtBytes(file.size)),
                    h('button', {
                        class: 'btn btn--sm btn--ghost',
                        onclick: () => { picked.splice(index, 1); drawFiles(); },
                    }, 'Убрать'))));
        }
        drawFiles();

        const dialog = openModal({
            title: 'Ответ отправлен',
            body: [
                h('div', { class: 'muted' },
                    'Отчёт проверен начальником отдела. Запишите, под каким '
                    + 'исходящим номером и когда ушёл ответ по письму '
                    + (wb.case.incoming_no || wb.case.case_id) + '. После этого '
                    + 'письмо считается закрытым, а отчёт — правке не подлежит.'),
                h('div', { class: 'form-grid' },
                    h('label', { class: 'field' }, 'Исходящий номер', number),
                    h('label', { class: 'field' }, 'Дата отправки', when)),
                h('label', { class: 'field' }, 'Примечание к ответу', outNote),
                h('div', { class: 'field' },
                    h('div', { class: 'toolbar', style: { marginBottom: '6px' } },
                        h('span', { class: 'grow' }, 'Приложения к ответу'),
                        h('button', {
                            class: 'btn btn--sm', onclick: () => picker.click(),
                        }, 'Выбрать файлы'),
                        picker),
                    fileList),
            ],
            footer: [
                h('button', { class: 'btn', onclick: () => dialog.close() }, 'Отмена'),
                h('button', { class: 'btn btn--primary', onclick: () => save() },
                    'Записать'),
            ],
            focus: 'input',
        });

        async function save() {
            const value = number.value.trim();
            if (!value) { toast('Укажите исходящий номер', 'error'); return; }
            let data;
            try {
                data = await api.post('/api/cases/' + wb.case.id + '/send', {
                    outgoing_no: value, outgoing_date: when.value || '',
                    outgoing_note: outNote.value.trim(),
                });
            } catch (error) {
                toastError(error);
                return;
            }
            // Приложения кладём по одному: не прошёл один — остальные на
            // месте, а человек видит имя того, который не взяли.
            const failed = [];
            for (const file of picked) {
                const form = new FormData();
                form.append('file', file);
                form.append('stage', 'outgoing');
                try {
                    await uploadFile('/api/cases/' + wb.case.id + '/files', form);
                } catch (error) {
                    failed.push(file.name + ' — ' + errorText(error));
                }
            }
            dialog.close();
            wb.case = data.case;
            refreshAll();
            loadCaseFiles();
            toast(failed.length
                ? 'Ответ записан, но приложения не легли: ' + failed.join('; ')
                : 'Ответ отправлен под номером ' + value,
                failed.length ? 'error' : 'ok', failed.length ? 8000 : 4000);
        }
    }

    /** Отозвать отправку: номер вписали не тот. Право проверяющего. */
    async function unsendCase() {
        if (!wb.case || !wb.case.outgoing_no) return;
        const ok = await confirmDialog({
            title: 'Отозвать отправку',
            message: 'Запись об отправке ответа под номером «'
                + wb.case.outgoing_no + '» будет снята, письмо вернётся '
                + 'в состояние «проверен, к отправке».',
            note: 'Отзыв виден в журнале действий. Отчёт остаётся проверенным.',
            confirmText: 'Отозвать',
            danger: true,
        });
        if (!ok) return;
        try {
            const data = await api.post('/api/cases/' + wb.case.id + '/unsend', {});
            wb.case = data.case;
            refreshAll();
            toast('Отправка отозвана', 'ok');
        } catch (error) {
            toastError(error);
        }
    }

    async function exportDocx() {
        if (!wb.report) return;
        try {
            const result = await withOverlay('Сборка DOCX', 'Отчёт собирается по фирменному шаблону.',
                () => api.download('/api/reports/' + wb.report.id + '/export.docx'));
            const url = URL.createObjectURL(result.blob);
            const link = h('a', { href: url, download: result.filename });
            document.body.appendChild(link);
            link.click();
            link.remove();
            setTimeout(() => URL.revokeObjectURL(url), 30000);
            toast('Файл ' + result.filename + ' выгружен', 'ok');
        } catch (error) {
            toastError(error);
        }
    }

    // -- правая панель ------------------------------------------------------

    function buildSidePanel() {
        const tabs = h('div', { class: 'tabs' });
        const body = h('div', { class: 'panel-body' });
        wb.nodes.sideTabs = tabs;
        wb.nodes.sideBody = body;
        return h('section', { class: 'panel panel--side' }, tabs, body);
    }

    function setTab(tab) {
        wb.tab = tab;
        renderSidePanel();
    }

    function renderSidePanel() {
        const tabs = wb.nodes.sideTabs;
        const body = wb.nodes.sideBody;
        if (!tabs || !body) return;
        const report = wb.report;
        const sources = report ? report.sources || [] : [];
        const issues = report ? report.issues || [] : [];

        clear(tabs);
        append(tabs, [
            h('button', {
                class: wb.tab === 'sources' ? 'is-active' : '',
                onclick: () => setTab('sources'),
            }, 'Источники (' + sources.length + ')'),
            h('button', {
                class: wb.tab === 'issues' ? 'is-active' : '',
                onclick: () => setTab('issues'),
            }, 'Замечания (' + issues.length + ')'),
            h('button', {
                class: wb.tab === 'notes' ? 'is-active' : '',
                title: 'Переписка по письму: что поправить и о чём договорились',
                onclick: () => setTab('notes'),
            }, 'Примечания (' + (wb.notes || []).length + ')'),
        ]);

        clear(body);
        if (wb.tab === 'sources') renderSources(body, sources);
        else if (wb.tab === 'notes') renderCaseNotes(body);
        else renderIssues(body, issues);
    }

    function renderSources(body, sources) {
        if (!sources.length) {
            body.appendChild(emptyBox('Источников нет', wb.report
                ? 'Модель не привлекала фрагменты библиотеки: индекс пуст или разделы их не требуют.'
                : 'Появятся после генерации отчёта.'));
            return;
        }

        sources.forEach((source) => {
            const active = wb.activeSource === source.label;
            body.appendChild(h('div', {
                class: 'source-item' + (active ? ' is-active is-open' : ''),
                onclick: () => setActiveSource(source.label),
            },
                h('div', {},
                    h('span', { class: 'label' }, '[' + source.label + ']'),
                    h('span', { class: 'citation' }, source.citation || source.chunk_uid || '')),
                h('div', { class: 'quote' }, source.text || '')));
        });
    }

    function renderIssues(body, issues) {
        if (!issues.length) {
            body.appendChild(emptyBox('Замечаний нет', wb.report
                ? 'Верификатор не нашёл ни чисел мимо факт-пакета, ни ссылок в никуда.'
                : 'Появятся после генерации и проверки.'));
            return;
        }
        ['error', 'warning', 'info'].forEach((level) => {
            const group = issues.filter((issue) => issue.level === level);
            if (!group.length) return;
            body.appendChild(h('div', { class: 'group-title' }, LEVEL_LABEL[level] + ' (' + group.length + ')'));
            group.forEach((issue) => {
                body.appendChild(h('div', {
                    class: 'issue-item level-' + level,
                    title: 'Перейти к разделу',
                    onclick: () => jumpToIssue(issue),
                },
                    h('span', { class: 'dot' }),
                    h('div', { class: 'body' },
                        h('div', { class: 'code' }, issue.code || ''),
                        h('div', { class: 'message' }, issue.message || ''),
                        issue.section
                            ? h('div', { class: 'where' }, 'раздел: ' + issue.section)
                            : h('div', { class: 'where' }, 'относится к отчёту целиком'))));
            });
        });
    }

    function jumpToIssue(issue) {
        if (!issue.section || !wb.report) {
            toast('Замечание относится к отчёту целиком', 'info', 3500);
            return;
        }
        const wanted = normalizeTitle(issue.section);
        const section = wb.report.sections.find((item) => normalizeTitle(item.title) === wanted) ||
            wb.report.sections.find((item) => normalizeTitle(item.title).indexOf(wanted) !== -1) ||
            wb.report.sections.find((item) => item.section_id === issue.section);
        if (!section) {
            toast('Раздел «' + issue.section + '» не найден среди секций текущей версии', 'info');
            return;
        }
        flashSection(section.section_id);
    }

    function refreshAll() {
        renderFactsBody();
        renderReportHead();
        renderSections();
        renderSidePanel();
    }

    // -- горячие клавиши ----------------------------------------------------

    function onKeyDown(event) {
        if (!(event.ctrlKey || event.metaKey) || event.altKey) return;
        if (state.route.name !== 'case') return;
        const target = event.target;
        const card = target && target.closest ? target.closest('.section-card') : null;

        if (event.code === 'KeyS') {
            event.preventDefault();
            if (card) saveSection(card.dataset.section);
            else if (target && target.closest && target.closest('.panel--facts')) saveFacts();
            else if (wb.focused && wb.dirty.has(wb.focused)) saveSection(wb.focused);
            else if (wb.factsDirty) saveFacts();
            else toast('Нечего сохранять', 'info', 2500);
            return;
        }
        if (event.code === 'Enter' || event.code === 'NumpadEnter') {
            if (!card) return;
            event.preventDefault();
            regenerateSection(card.dataset.section);
        }
    }

    // =====================================================================
    // 7. Экран «Библиотека»
    // =====================================================================

    const libState = { docType: '', domain: '', items: [], stats: {}, chunks: 0,
                      embeddings: 0, vectorsTimer: 0,
                      // Библиотека отдела — тринадцать с половиной тысяч
                      // документов. Одной таблицей это не рисуется: браузер
                      // подвисает на минуту, а человеку нужны три документа,
                      // которые он ищет по названию.
                      query: '', page: 1, pages: 1, total: 0, perPage: 50,
                      quality: '', qualityState: null, summary: null };

    /** Подсказка о поддерживаемых форматах и о том, чего не хватает. */
    function formatsHint() {
        const formats = state.formats;
        if (!formats) return '';
        const shown = (formats.available || []).map((item) => item.replace('.', '').toUpperCase());
        // Перечислять шесть десятков расширений бессмысленно: называем те, что
        // встречаются в библиотеке чаще всего, остальное — числом.
        const head = ['PDF', 'DOCX', 'DOC', 'XLSX', 'PPTX', 'DJVU', 'TXT'].filter(
            (item) => shown.indexOf(item) >= 0);
        const rest = shown.length - head.length;
        let text = 'Текст читается из ' + head.join(', ');
        if (rest > 0) text += ' и ещё ' + rest + ' форматов';
        // Ограничения на расширение нет: класть можно что угодно. Но
        // нечитаемый файл в библиотеке — это папка с названием и без
        // содержимого: он не найдётся ни поиском, ни помощником, и сказать
        // об этом надо до загрузки, а не после.
        text += '. Любой другой файл тоже примем — но текст из него не '
            + 'вычитается, и в поиске он не найдётся';
        // Один формат объявляют несколько конвертеров (7z через 7z, 7za, 7zz),
        // поэтому без свёртки список повторялся: «.7z, .rar, .7z, .rar, .7z».
        const blocked = formats.blocked || [];
        const missing = [];
        blocked.forEach((spec) => (spec.suffixes || []).forEach((suffix) => {
            if (missing.indexOf(suffix) < 0) missing.push(suffix);
        }));
        if (missing.length) {
            text += '. Не читаются: ' + missing.join(', ');
        }
        text += '.';
        return text;
    }

    async function loadFormats() {
        if (state.formats) return state.formats;
        try {
            state.formats = await api.get('/api/formats');
        } catch (error) {
            state.formats = null;
        }
        return state.formats;
    }

    /** Что система вычитала из файла — главный способ проверить качество разбора. */
    async function showDocument(item) {
        const bodyBox = h('div', {}, loadingBox('Читаем файл…'));
        const fileUrl = '/api/library/' + encodeURIComponent(item.doc_id) + '/file';
        const openSource = h('button', {
            class: 'btn', hidden: true,
            title: 'Посмотреть страницы подлинника, не скачивая его',
            onclick: () => showSourcePages(),
        }, 'Показать подлинник');
        let sourcePages = 0;

        function showSourcePages() {
            if (!sourcePages) return;
            const pager = pageViewer(
                { name: item.doc_id, pages: sourcePages }, fileUrl);
            const window_ = openModal({
                title: h('div', { class: 'modal-head' },
                    h('b', {}, item.title || item.doc_id),
                    h('span', { class: 'mono small faint' }, 'подлинник')),
                wide: true,
                body: [h('div', { class: 'preview-box' }, pager.view), pager.bar],
                footer: [
                    h('a', { class: 'btn', href: fileUrl, download: '' }, 'Скачать'),
                    h('button', { class: 'btn btn--primary',
                                  onclick: () => window_.close() }, 'Закрыть'),
                ],
            });
            setTimeout(() => pager.focus(), 0);
        }

        const dialog = openModal({
            title: h('div', { class: 'modal-head' },
                h('b', {}, item.title || item.doc_id),
                h('span', { class: 'mono small faint' }, item.doc_id)),
            body: bodyBox,
            footer: [
                // Кнопка «Открыть исходный файл» на деле скачивала: сервер
                // отдаёт файл вложением. Смотреть подлинник теперь можно
                // прямо здесь — страницами, как справку в личном кабинете.
                openSource,
                h('a', { class: 'btn', href: fileUrl, download: '' }, 'Скачать'),
                h('button', { class: 'btn btn--primary', onclick: () => dialog.close() }, 'Закрыть'),
            ],
        });

        let data;
        let shown = 0;
        try {
            data = await api.get('/api/library/' + encodeURIComponent(item.doc_id) + '/text');
        } catch (error) {
            clear(bodyBox);
            bodyBox.appendChild(h('div', { class: 'card card-pad' }, errorText(error)));
            return;
        }

        const chunks = data.chunks || [];
        const chars = (data.text || '').length;
        sourcePages = Number(data.source_pages || 0);
        openSource.hidden = !sourcePages;
        const warnings = (item.warnings || data.document && data.document.warnings || []);

        // Доля букв и цифр: у скана без распознавания и у PDF без карты
        // символов она проваливается, и это видно сразу.
        const meaningful = (data.text || '').replace(/\s/g, '');
        const letters = (meaningful.match(/[\p{L}\p{N}]/gu) || []).length;
        const share = meaningful.length ? letters / meaningful.length : 0;

        // Плашка показывается ТОЛЬКО когда с разбором что-то не так. Когда всё
        // в порядке, сообщать об этом нечего: число фрагментов стоит на
        // соседней вкладке, а рапорт об успехе инженер читает впустую каждый
        // раз, когда открывает документ.
        const verdict = !chars
            ? { text: 'Текст не извлёкся: скан без распознавания.', tone: 'danger' }
            : share < 0.35
                ? { text: 'Текст неразборчив: осмысленных знаков ' +
                        Math.round(share * 100) + ' %. Пересохраните или распознайте файл.',
                    tone: 'danger' }
                : chars < 400
                    ? { text: 'Текста мало: ' + chars + ' знаков. Проверьте, весь ли документ разобран.',
                        tone: 'warn' }
                    : null;

        clear(bodyBox);
        append(bodyBox, [
            verdict ? h('div', { class: 'doc-verdict doc-verdict--' + verdict.tone }, verdict.text) : null,
            !data.source_exists ? h('div', { class: 'doc-verdict doc-verdict--warn' },
                'Исходного файла нет на диске — открыть не получится.') : null,
            warnings.length ? h('div', { class: 'card card-pad' },
                h('div', { class: 'card-title' }, 'При разборе'),
                h('ul', {}, warnings.map((text) => h('li', {}, text)))) : null,
            h('div', { class: 'doc-tabs' },
                h('button', { class: 'chip is-active', onclick: (e) => switchTab(e, 'text') }, 'Текст целиком'),
                h('button', { class: 'chip', onclick: (e) => switchTab(e, 'chunks') },
                    'Фрагменты (' + (data.chunks_total || chunks.length) + ')')),
            // Книга бывает и в полторы тысячи фрагментов: показываем
            // страницами и говорим, сколько всего. Молча обрезанный список
            // читается как весь документ — а это разные вещи.
            (data.chunks_total || 0) > chunks.length ? h('div', { class: 'small muted' },
                'Показаны фрагменты 1–' + chunks.length + ' из ' + data.chunks_total
                + '. Дочитать: кнопка внизу.') : null,
            h('div', { class: 'doc-pane', id: 'doc-pane-text' },
                h('pre', { class: 'doc-text' }, data.text || '')),
            h('div', { class: 'doc-pane', id: 'doc-pane-chunks', hidden: true },
                chunks.length ? chunkNodes(chunks, 0)
                    : emptyBox('Документ не нарезан',
                        'Текст из файла вычитан, но на фрагменты не разбит, и в поиске документ не найдётся. Перечитайте каталог библиотеки.')),
        ]);

        shown = chunks.length;
        appendMoreButton();

        function chunkNodes(list, from) {
            return list.map((chunk, index) => h('div', { class: 'doc-chunk' },
                h('div', { class: 'doc-chunk-head' },
                    h('b', {}, 'Фрагмент ' + (from + index + 1)),
                    h('span', { class: 'faint small' },
                        (chunk.title_path || []).join(' → ') || 'без заголовка'),
                    h('span', { class: 'faint small' }, chunk.chars + ' знаков')),
                h('div', { class: 'doc-chunk-text' }, chunk.text)));
        }

        function appendMoreButton() {
            const pane = $('#doc-pane-chunks', bodyBox);
            if (!pane || shown >= (data.chunks_total || 0)) return;
            const more = h('button', {
                class: 'btn', style: { marginTop: '10px' },
                onclick: async () => {
                    more.disabled = true;
                    more.textContent = 'читаю…';
                    try {
                        const next = await api.get('/api/library/'
                            + encodeURIComponent(item.doc_id) + '/text?offset=' + shown);
                        const list = next.chunks || [];
                        more.remove();
                        chunkNodes(list, shown).forEach((node) => pane.appendChild(node));
                        shown += list.length;
                        appendMoreButton();
                    } catch (error) {
                        more.disabled = false;
                        more.textContent = errorText(error);
                    }
                },
            }, 'Показать ещё ' + Math.min(400, (data.chunks_total || 0) - shown));
            pane.appendChild(more);
        }

        function switchTab(event, which) {
            $$('.doc-tabs .chip', bodyBox).forEach((chip) => chip.classList.remove('is-active'));
            event.currentTarget.classList.add('is-active');
            $('#doc-pane-text', bodyBox).hidden = which !== 'text';
            $('#doc-pane-chunks', bodyBox).hidden = which !== 'chunks';
        }
    }

    async function renderLibrary(view, focusDocId) {
        await loadFormats();
        clear(view);
        const page = h('div', { class: 'page' });
        view.appendChild(page);

        // Переход по адресу «#/library/<doc_id>»: показываем нужный документ.
        // Раньше здесь только снимались фильтры, а строку искали на текущей
        // странице списка — при тринадцати тысячах документов и пятидесяти
        // строках на странице её там не было почти никогда. Теперь документ
        // ставится в поиск: строка гарантированно на виду.
        if (focusDocId) {
            libState.docType = '';
            libState.domain = '';
            libState.quality = '';
            libState.query = focusDocId;
            libState.page = 1;
        }

        const tableBox = h('div', { class: 'card' });
        const vectorsBox = h('div', {});
        const statsLine = h('div', { class: 'page-note' });
        const uploadList = h('div', {});
        const searchResults = h('div', {});

        const typeFilter = h('select', {
            onchange: (event) => {
                libState.docType = event.target.value;
                loadLibrary();
            },
        }, h('option', { value: '' }, 'Все типы'),
            (state.config.doc_types || []).map((type) =>
                h('option', { value: type, selected: libState.docType === type }, docTypeLabel(type))));

        const domainFilter = domainSelect({
            value: libState.domain,
            title: 'Фильтр по направлению техники',
            onchange: (value) => {
                libState.domain = value;
                loadLibrary();
            },
        });

        // Поиск по названию — главный способ добраться до документа, когда
        // их тринадцать тысяч: листать пятьюдесятью страницами никто не станет.
        const nameSearch = h('input', {
            type: 'search', class: 'input--wide',
            placeholder: 'Поиск по названию документа',
            value: libState.query,
            oninput: () => {
                clearTimeout(libState.searchTimer);
                libState.searchTimer = setTimeout(() => {
                    libState.query = nameSearch.value.trim();
                    libState.page = 1;
                    loadLibrary();
                }, 350);
            },
        });

        const pager = h('div', { class: 'pager' });
        const qualityBox = h('div', {});
        const summaryBox = h('div', {});

        /* Собралась ли библиотека — одним взглядом, после пересборки.

           Итог приёма виден только в консоли PowerShell, а на тринадцати
           тысячах документов её содержимое уезжает вверх задолго до конца.
           Человек, ради которого пересборка и затевалась, узнать «сколько
           принято и что не принято» уже не может. */
        async function loadSummary() {
            try {
                libState.summary = await api.get('/api/library/summary');
            } catch (error) {
                libState.summary = null;
            }
            renderSummary();
        }

        function summaryTile(value, label, filter) {
            const number = filter
                ? h('button', {
                    class: 'linklike stat-link',
                    onclick: () => {
                        libState.quality = libState.quality === filter ? '' : filter;
                        libState.page = 1;
                        loadLibrary();
                        renderSummary();
                    },
                  }, String(value))
                : h('div', { class: 'value' }, String(value));
            return h('div', { class: 'stat' }, number, h('div', { class: 'label' }, label));
        }

        function renderSummary() {
            const data = libState.summary;
            clear(summaryBox);
            if (!data) return;
            const counts = data.counts || {};
            const report = data.report || {};
            const tiles = [
                summaryTile(counts.documents || 0, 'документов', ''),
                summaryTile(counts.chunks || 0, 'фрагментов', ''),
            ];
            // Плитку показываем, только когда есть о чём говорить: ноль
            // непринятых — это хорошая новость, а не строка в отчёте.
            if (report.failures_total) {
                tiles.push(h('div', { class: 'stat' },
                    h('button', {
                        class: 'linklike stat-link',
                        onclick: () => showFailures(report),
                    }, String(report.failures_total)),
                    h('div', { class: 'label' }, 'не принято')));
            }
            if (counts.empty) tiles.push(summaryTile(counts.empty, 'без фрагментов', 'empty'));
            if (counts.glued) tiles.push(summaryTile(counts.glued, 'склеенный текст', 'glued'));

            const строки = [h('div', { class: 'stat-cards' }, tiles)];
            if (report.finished_at) {
                строки.push(h('div', { class: 'small muted' },
                    'Приём закончился ' + fmtDateTime(report.finished_at * 1000)
                    + ': просмотрено файлов ' + (report.files_seen || 0)
                    + ', принято ' + (report.added || 0)
                    + ', обновлено ' + (report.updated || 0)
                    + ', пропущено ' + (report.skipped || 0)
                    + ' (не менялись или тот же файл под другим именем)'
                    + ', не принято ' + (report.failed || 0) + '.'));
            } else {
                строки.push(h('div', { class: 'small muted' },
                    'Итога приёма нет: библиотека собрана прежним выпуском системы. '
                    + 'Он появится после ближайшей загрузки.'));
            }
            // Своя кнопка выхода из отбора: соседняя карточка рисует свою,
            // только когда нашлись склеенные, и по отбору «без фрагментов»
            // человек остался бы в отфильтрованном списке без выхода.
            if (libState.quality) {
                строки.push(h('button', {
                    class: 'btn btn--sm',
                    onclick: () => {
                        libState.quality = '';
                        libState.page = 1;
                        loadLibrary();
                        renderSummary();
                    },
                }, 'Показать все документы'));
            }
            summaryBox.appendChild(h('div', { class: 'card card-pad' },
                h('h3', {}, 'Библиотека собралась'), ...строки));
        }

        function showFailures(report) {
            const список = report.failures || [];
            const хвост = (report.failures_total || 0) - список.length;
            openModal({
                title: 'Файлы, которые не приняты',
                body: h('div', {},
                    h('p', { class: 'small muted' },
                        'Эти файлы в библиотеку не попали. Причина написана рядом '
                        + 'с именем: разберитесь с ними и запустите загрузку ещё раз — '
                        + 'уже принятое заново не перечитывается.'),
                    h('ul', { class: 'plain-list' },
                        список.map((строка) => h('li', { class: 'small' }, строка))),
                    хвост > 0
                        ? h('p', { class: 'small muted' },
                            'И ещё ' + хвост + ': полный список печатает приём в консоли.')
                        : null),
            });
        }

        /* Плохо разобранные документы в уже готовой библиотеке.

           Склейку текста система замечает при приёме, но библиотека отдела
           собрана раньше: тринадцать тысяч документов лежат без пометок, и
           найти среди них плохие можно было только глазами. Проверка идёт
           по тому, что уже в базе, — перезагружать библиотеку не нужно. */
        async function loadQuality() {
            try {
                const data = await api.get('/api/library/quality');
                libState.qualityState = data.quality || {};
                renderQuality();
            } catch (error) {
                clear(qualityBox);
            }
        }

        function renderQuality() {
            const state = libState.qualityState || {};
            clear(qualityBox);
            if (!state.hint && !isAdmin()) return;
            const card = h('div', {
                class: 'card card-pad quality-card'
                    + (state.glued ? ' is-bad' : ''),
                style: { marginTop: '14px' },
            });
            append(card, [
                h('div', { class: 'vectors-line' },
                    h('b', {}, 'Качество разбора'),
                    h('span', { class: 'small' }, state.hint
                        || 'библиотека на склейку текста не проверялась')),
                h('div', { class: 'toolbar', style: { marginTop: '8px' } },
                    isAdmin() && !state.running ? h('button', {
                        class: 'btn btn--sm',
                        title: 'Пройти по уже загруженным документам и пометить те, '
                            + 'у которых текст склеен без пробелов. Файлы заново не '
                            + 'разбираются — читается то, что уже в базе.',
                        onclick: () => runQuality(),
                    }, 'Проверить разбор') : null,
                    state.glued ? h('button', {
                        class: 'btn btn--sm' + (libState.quality ? ' btn--primary' : ''),
                        onclick: () => {
                            libState.quality = libState.quality ? '' : 'glued';
                            libState.page = 1;
                            loadLibrary();
                            renderQuality();
                        },
                    }, libState.quality ? 'Показать все' : 'Показать плохо разобранные') : null),
            ]);
            qualityBox.appendChild(card);
            clearTimeout(libState.qualityTimer);
            if (state.running) {
                libState.qualityTimer = setTimeout(() => {
                    if (!document.body.contains(qualityBox)) return;
                    if (document.hidden) { renderQuality(); return; }
                    loadQuality();
                }, 1500);
            }
        }

        async function runQuality() {
            try {
                const data = await api.post('/api/library/quality', {});
                libState.qualityState = data.quality || {};
                renderQuality();
            } catch (error) {
                toastError(error);
            }
        }

        function renderPager() {
            clear(pager);
            if (libState.total <= libState.perPage) return;
            const first = (libState.page - 1) * libState.perPage + 1;
            const last = Math.min(libState.total, first + libState.items.length - 1);
            const go = (page) => {
                libState.page = page;
                loadLibrary();
                tableBox.scrollIntoView({ block: 'start' });
            };
            append(pager, [
                h('button', {
                    class: 'btn btn--sm', disabled: libState.page <= 1,
                    onclick: () => go(libState.page - 1),
                }, '← назад'),
                h('span', { class: 'small muted' },
                    first + '–' + last + ' из ' + libState.total),
                h('button', {
                    class: 'btn btn--sm', disabled: libState.page >= libState.pages,
                    onclick: () => go(libState.page + 1),
                }, 'вперёд →'),
                h('span', { class: 'small faint' },
                    'страница ' + libState.page + ' из ' + libState.pages),
            ]);
        }

        const forceCheckbox = h('input', { type: 'checkbox' });
        const uploadType = h('select', {}, (state.config.doc_types || []).map((type) =>
            h('option', { value: type }, docTypeLabel(type))));
        const uploadDomain = domainSelect({
            anyLabel: 'определить автоматически',
            title: 'Направление загружаемых документов',
        });

        const fileInput = h('input', {
            type: 'file', multiple: true, style: { display: 'none' },
            onchange: (event) => {
                handleFiles(Array.prototype.slice.call(event.target.files || []));
                event.target.value = '';
            },
        });

        const dropzone = h('div', {
            class: 'dropzone',
            onclick: () => fileInput.click(),
            ondragover: (event) => {
                event.preventDefault();
                dropzone.classList.add('is-over');
            },
            ondragleave: () => dropzone.classList.remove('is-over'),
            ondrop: (event) => {
                event.preventDefault();
                dropzone.classList.remove('is-over');
                handleFiles(Array.prototype.slice.call(event.dataTransfer.files || []));
            },
        },
            h('div', {}, h('b', {}, 'Перетащите файлы'), ' или нажмите для выбора'),
            h('div', { class: 'small' }, formatsHint()));

        const searchInput = h('input', {
            type: 'search', class: 'grow',
            placeholder: 'Что найти в документах — например, «занимаемая полоса частот»',
            onkeydown: (event) => {
                if (event.key === 'Enter') runSearch();
            },
        });
        const topKInput = h('input', {
            type: 'number', value: '10', min: '1', max: '50',
            title: 'Сколько фрагментов показать', style: { width: '64px' },
        });
        const searchDomain = domainSelect({ title: 'Ограничить поиск направлением' });
        const searchTypes = (state.config.doc_types || []).map((type) => {
            const checkbox = h('input', { type: 'checkbox', value: type });
            return { type: type, checkbox: checkbox, node: h('label', { class: 'inline' }, checkbox, docTypeLabel(type)) };
        });

        const focusChip = !focusDocId ? null : h('span', { class: 'badge badge--accent' },
            'показан документ ' + focusDocId,
            h('button', {
                class: 'btn btn--ghost btn--icon', title: 'Показать всю библиотеку',
                onclick: () => navigate('#/library'),
            }, '×'));

        append(page, [
            h('div', { class: 'page-head' },
                statsLine,
                // Кнопки держатся вместе: при переносе на узком экране они
                // должны уезжать на новую строку группой, а не поодиночке.
                h('div', { class: 'page-head-actions' },
                    h('button', { class: 'btn', onclick: () => loadLibrary() }, 'Обновить'),
                    isAdmin() ? h('label', {
                        class: 'inline',
                        title: 'Обычно перечитываются только новые и изменившиеся файлы. ' +
                            'С этой отметкой перечитываются все — нужно после смены модели ' +
                            'встраивания или правил разбора.',
                    }, forceCheckbox, 'перечитать все файлы') : null,
                    isAdmin() ? h('button', {
                        class: 'btn',
                        title: 'Прочитать каталог библиотеки и обновить поисковый индекс',
                        onclick: () => reindex(),
                    }, 'Прочитать каталог') : null)),

            // Состояние смыслового поиска стоит выше всего остального: пока
            // он слеп, и поиск по содержимому, и ответы помощника находят
            // не то, а понять это по самой выдаче нельзя.
            vectorsBox,

            // Поиск по содержимому — то, ради чего библиотеку и собирали:
            // тридцать тысяч файлов листать никто не станет. Он стоял в
            // самом низу страницы, под четырьмя карточками обслуживания, и
            // до него доходили, только зная, что он там есть.
            h('div', { class: 'card card-pad', style: { marginTop: '14px' } },
                h('div', { class: 'card-title' }, 'Поиск по библиотеке'),
                h('div', { class: 'toolbar' },
                    searchInput,
                    h('label', { class: 'inline' }, 'показать', topKInput, 'шт.'),
                    searchDomain,
                    h('button', { class: 'btn btn--primary', onclick: () => runSearch() }, 'Найти')),
                h('div', { class: 'toolbar small muted' }, 'типы:', searchTypes.map((item) => item.node)),
                searchResults),

            // Сама опись: что в библиотеке есть, какого типа и направления.
            h('div', { class: 'toolbar', style: { marginTop: '14px' } },
                typeFilter, domainFilter, nameSearch, focusChip),
            tableBox,
            pager,

            // Обслуживание — загрузка, итог приёма, качество разбора.
            // Занимается им начальство и раз в месяц, а смотрят экран
            // каждый день: четыре карточки наверху отодвигали и опись, и
            // поиск ниже сгиба у всех остальных.
            foldCard('library-maint', 'Обслуживание библиотеки',
                isAdmin()
                    ? 'загрузка документов, итог приёма, качество разбора'
                    : 'итог приёма и качество разбора',
                // Пополняет библиотеку начальство: документ ложится в общий
                // поиск всего отдела, и неверно указанный тип или направление
                // портят выдачу всем.
                isAdmin() ? h('div', { class: 'fold-part' },
                    h('div', { class: 'card-title' }, 'Загрузка документов'),
                    h('div', { class: 'toolbar' },
                        h('label', { class: 'inline' }, 'Тип:', uploadType),
                        h('label', { class: 'inline' }, 'Направление:', uploadDomain)),
                    dropzone, fileInput, uploadList) : null,
                summaryBox,
                qualityBox),
        ]);

        /* Состояние смыслового поиска. Библиотека может быть полна, а поиск
           по смыслу — слеп: не построены векторы, упала служба, векторы
           построены другой моделью. Раньше об этом говорила серая строчка
           под ответом помощника, и месяцами никто не замечал. */
        async function loadVectors() {
            try {
                const data = await api.get('/api/library/vectors');
                renderVectors(data.vectors || {});
            } catch (error) {
                clear(vectorsBox);
                vectorsBox.appendChild(h('div', { class: 'small muted' }, errorText(error)));
            }
        }

        function renderVectors(векторы) {
            clear(vectorsBox);
            if (!векторы.enabled && !векторы.chunks) return;

            // Идущая работа важнее итога: при перестройке заново векторы
            // на месте, состояние «готово», а поиск в эту минуту опирается
            // на наполовину переписанный указатель.
            const busy = векторы.running;
            const card = h('div', {
                class: 'card card-pad vectors-card'
                    + (busy ? ' is-busy' : (векторы.ready ? ' is-ok' : ' is-bad')),
                style: { marginTop: '14px' },
            });

            const line = h('div', { class: 'vectors-line' },
                h('b', {}, 'Смысловой поиск'),
                h('span', { class: 'small' }, векторы.hint || ''));
            card.appendChild(line);

            // Что делать. Диагноз «сервер эмбеддингов недоступен» человеку в
            // отделе не говорит ничего: он сидит за той же машиной, и ему
            // нужна команда, а не название беды.
            if (векторы.advice) {
                card.appendChild(h('div', { class: 'vectors-advice small' }, векторы.advice));
            }

            if (busy && векторы.total) {
                const share = Math.min(100, Math.round(100 * (векторы.done || 0) / векторы.total));
                card.appendChild(h('div', { class: 'vectors-bar' },
                    h('div', { class: 'vectors-bar-fill', style: { width: share + '%' } })));
            }

            const actions = h('div', { class: 'toolbar', style: { marginTop: '8px' } });
            if (isAdmin() && векторы.enabled && !busy && векторы.missing) {
                actions.appendChild(h('button', {
                    class: 'btn btn--primary btn--sm',
                    title: 'Построить векторы фрагментам, у которых их нет',
                    onclick: () => buildVectors(false),
                }, 'Построить векторы'));
            }
            if (isAdmin() && векторы.enabled && !busy && векторы.chunks) {
                actions.appendChild(h('button', {
                    class: 'btn btn--sm',
                    title: 'Заново по всей библиотеке — нужно после смены модели встраивания. '
                        + 'На большой библиотеке это часы работы видеокарты.',
                    onclick: () => buildVectors(true),
                }, 'Построить заново'));
            }
            // Проверка связи — отдельно от построения: узнать, поднялась ли
            // служба, нужно сразу, а не через полчаса работы видеокарты.
            if (isAdmin() && векторы.enabled && !busy) {
                actions.appendChild(h('button', {
                    class: 'btn btn--sm',
                    title: 'Один короткий запрос к службе эмбеддингов',
                    onclick: (event) => checkVectors(event.target),
                }, 'Проверить связь'));
            }
            // Реранк — вторая служба и вторая точка отказа. Отваливается он
            // молча: ответы делаются общими и не по делу, а причина видна
            // только строчкой в блоке источников под ответом помощника.
            // Признак берём из настроек отдела, а не из состояния векторов:
            // здесь «векторы» — это состояние службы эмбеддингов, реранк живёт
            // отдельно и о нём знает только конфигурация.
            if (isAdmin() && (state.config.search || {}).rerank) {
                actions.appendChild(h('button', {
                    class: 'btn btn--sm',
                    title: 'Один короткий запрос к службе реранка — второму '
                        + 'проходу поиска, который и отличает «обратный канал» '
                        + 'от «прямого»',
                    onclick: (event) => checkRerank(event.target),
                }, 'Проверить реранк'));
            }
            if (actions.childNodes.length) card.appendChild(actions);
            vectorsBox.appendChild(card);

            // Пока идёт работа — переспрашиваем. Закончилась: обновляем ещё
            // раз, чтобы полоса сменилась итогом, и на этом успокаиваемся.
            clearTimeout(libState.vectorsTimer);
            if (busy) {
                libState.vectorsTimer = setTimeout(() => {
                    if (!document.body.contains(vectorsBox)) return;
                    // Свёрнутое окно спрашивать незачем: человек на него не
                    // смотрит, а каждый вопрос — это счёт по всей библиотеке
                    // на той же базе, в которую построение сейчас пишет.
                    // Ждём, пока вкладку откроют снова.
                    if (document.hidden) { renderVectors(векторы); return; }
                    loadVectors();
                }, 2000);
            }
        }

        async function checkVectors(button) {
            const was = button.textContent;
            button.disabled = true;
            button.textContent = 'проверяю…';
            try {
                const answer = (await api.post('/api/library/vectors/check', {})).check || {};
                if (answer.ok) {
                    toast('Служба отвечает: ' + (answer.model || 'модель')
                        + ', вектор из ' + (answer.dim || '?') + ' чисел, '
                        + (answer.ms || 0) + ' мс');
                } else {
                    // Показываем не только беду, но и что с ней делать — в
                    // окне, которое не закроется само: всплывающая подсказка
                    // уходит раньше, чем человек дочитает команду.
                    const dialog = openModal({
                        narrow: true,
                        title: 'Смысловой поиск не работает',
                        body: h('div', {},
                            h('div', {}, answer.error || 'служба не отвечает'),
                            answer.advice
                                ? h('div', { class: 'small muted', style: { marginTop: '8px' } },
                                    answer.advice)
                                : null),
                        footer: [h('button', {
                            class: 'btn btn--primary', onclick: () => dialog.close(),
                        }, 'Понятно')],
                    });
                }
                loadVectors();
            } catch (error) {
                toastError(error);
            } finally {
                button.disabled = false;
                button.textContent = was;
            }
        }

        async function checkRerank(button) {
            const was = button.textContent;
            button.disabled = true;
            button.textContent = 'проверяю…';
            try {
                const answer = (await api.post('/api/library/rerank/check', {})).check || {};
                if (answer.ok && answer.advice) {
                    // Работает, но с оговоркой: сервер заставил резать
                    // фрагменты. Это не ошибка, но и не «всё хорошо».
                    const dialog = openModal({
                        narrow: true,
                        title: 'Реранк работает, но вполсилы',
                        body: h('div', {},
                            h('div', {}, 'Служба отвечает: ' + (answer.model || 'модель') + '.'),
                            h('div', { class: 'small', style: { marginTop: '8px' } },
                                answer.advice)),
                        footer: [h('button', {
                            class: 'btn btn--primary', onclick: () => dialog.close(),
                        }, 'Понятно')],
                    });
                } else if (answer.ok) {
                    toast('Реранк отвечает: ' + (answer.model || 'модель')
                        + (answer.batch ? ', по ' + answer.batch + ' фрагм. за раз' : ''));
                } else {
                    const dialog = openModal({
                        narrow: true,
                        title: 'Реранк не работает',
                        body: h('div', {},
                            h('div', {}, answer.error || 'служба не отвечает'),
                            h('div', { class: 'small muted', style: { marginTop: '8px' } },
                                'Пока реранк молчит, поиск отдаёт помощнику то, '
                                + 'что совпало словами. Вопрос про обратный канал '
                                + 'приносит фрагменты про прямой: слово «канал» '
                                + 'в них одно и то же.'),
                            answer.advice
                                ? h('div', { class: 'small', style: { marginTop: '8px' } },
                                    answer.advice)
                                : null),
                        footer: [h('button', {
                            class: 'btn btn--primary', onclick: () => dialog.close(),
                        }, 'Понятно')],
                    });
                }
            } catch (error) {
                toastError(error);
            } finally {
                button.disabled = false;
                button.textContent = was;
            }
        }

        async function buildVectors(force) {
            if (force) {
                const ok = await confirmDialog({
                    title: 'Построить векторы заново',
                    message: 'Векторы будут пересчитаны по всей библиотеке, '
                        + 'даже те, что уже есть. На большой библиотеке это '
                        + 'часы работы видеокарты. Нужно после смены модели '
                        + 'встраивания.',
                    confirmText: 'Построить заново',
                });
                if (!ok) return;
            }
            try {
                const data = await api.post('/api/library/vectors', { force: !!force });
                renderVectors(data.vectors || {});
                toast(force ? 'Строим векторы заново' : 'Строим недостающие векторы');
            } catch (error) {
                toast(errorText(error), 'bad');
            }
        }

        async function loadLibrary() {
            clear(tableBox);
            tableBox.appendChild(skeleton(7));
            try {
                const query = ['page=' + libState.page, 'per_page=' + libState.perPage];
                if (libState.docType) query.push('doc_type=' + encodeURIComponent(libState.docType));
                if (libState.domain) query.push('domain=' + encodeURIComponent(libState.domain));
                if (libState.query) query.push('q=' + encodeURIComponent(libState.query));
                if (libState.quality) query.push('quality=' + encodeURIComponent(libState.quality));
                const data = await api.get('/api/library?' + query.join('&'));
                libState.items = data.items || [];
                libState.stats = data.stats || {};
                libState.chunks = data.chunks || 0;
                libState.embeddings = data.embeddings || 0;
                libState.total = data.total || 0;
                libState.page = data.page || 1;
                libState.pages = data.pages || 1;
                renderTable();
            } catch (error) {
                clear(tableBox);
                tableBox.appendChild(errorBox(error));
            }
        }

        function renderTable() {
            const totals = Object.keys(libState.stats).reduce((acc, type) => {
                acc.documents += libState.stats[type].documents || 0;
                acc.chunks += libState.stats[type].chunks || 0;
                return acc;
            }, { documents: 0, chunks: 0 });
            // О векторах говорит отдельная карточка ниже: там же и кнопка,
            // и ход построения. В строке итогов им места нет — «векторов
            // 2000» при 5000 фрагментов выглядит благополучно, хотя три
            // пятых библиотеки в смысловом поиске не участвуют.
            const chunkCount = libState.chunks || totals.chunks;
            statsLine.textContent = 'документов: ' + totals.documents +
                ' · фрагментов: ' + chunkCount +
                (libState.query ? ' · найдено: ' + libState.total : '');

            clear(tableBox);
            if (!libState.items.length) {
                clear(pager);
                tableBox.appendChild(libState.query || libState.docType || libState.domain
                    ? emptyBox('Ничего не нашлось',
                        'По этим условиям в библиотеке документов нет. '
                        + 'Снимите отбор по типу или направлению.')
                    : emptyBox('Документов нет',
                        'Загрузите литературу, стандарты и прошлые отчёты — '
                        + 'они станут источниками для ссылок.'));
                return;
            }
            const body = h('tbody', {});
            libState.items.forEach((item) => {
                body.appendChild(h('tr', {
                    id: domId('doc-', item.doc_id),
                    class: focusDocId === item.doc_id ? 'is-focus' : '',
                },
                    h('td', { class: 'primary' }, h('button', {
                        class: 'linklike', title: 'Посмотреть, что система вычитала из файла',
                        onclick: () => showDocument(item),
                    }, item.title || item.doc_id),
                        // Документ есть, фрагментов много, а найти в нём
                        // нельзя ничего: файл разобрался в сплошную строку
                        // без пробелов. Без метки это не отличить от целого.
                        item.text_quality === 'glued' ? h('span', {
                            class: 'badge badge--warn',
                            title: 'Текст склеен без пробелов — файл разобран '
                                + 'плохо. Поиск по нему почти ничего не найдёт: '
                                + 'переложите документ через OCR или сохраните '
                                + 'в другом формате и загрузите заново.',
                        }, 'текст склеен') : null),
                    h('td', { class: 'mono small muted' }, item.doc_id),
                    h('td', { class: 'small' }, docTypeLabel(item.doc_type)),
                    h('td', {}, documentDomainCell(item)),
                    h('td', {}, documentStatusCell(item)),
                    h('td', { class: 'num' }, item.chunk_count || 0),
                    h('td', { class: 'small muted nowrap' }, fmtDateTime(item.indexed_at)),
                    h('td', { class: 'row-actions' }, isAdmin() ? h('button', {
                        class: 'btn btn--icon btn--danger-hover',
                        title: 'Убрать документ из библиотеки и из поиска',
                        onclick: () => removeDocument(item),
                    }, iconGlyph('trash')) : null)));
            });
            const libraryTable = h('table', { class: 'grid grid--library' },
                    h('thead', {}, h('tr', {},
                        h('th', {}, 'Название'), h('th', {}, 'Идентификатор'), h('th', {}, 'Тип'),
                        h('th', {}, 'Направление'),
                        h('th', {}, 'Актуальность'),
                        h('th', { class: 'num' }, 'Фрагментов'), h('th', {}, 'Прочитан'),
                        h('th', {}))),
                    body);
            tableBox.appendChild(h('div', { class: 'table-scroll' },
                makeResizable(libraryTable, 'library')));
            renderPager();

            if (focusDocId) {
                const row = document.getElementById(domId('doc-', focusDocId));
                if (row) row.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }

        /** Ячейка направления: инженеру — выпадающий список с сохранением, остальным — текст. */
        function documentDomainCell(item) {
            if (!isAdmin()) {
                return h('span', { class: 'small' + (item.domain ? '' : ' faint') }, domainTitle(item.domain));
            }
            // Название целиком — во всплывающей подсказке: у самых длинных
            // направлений оно шире столбца, и без подсказки выбранное
            // пришлось бы узнавать, открывая список.
            const select = domainSelect({
                value: item.domain,
                anyLabel: 'не указано',
                title: 'Направление документа: ' + domainTitle(item.domain),
                onchange: (value) => saveDomain(item, value, select),
            });
            select.classList.add('domain-select');
            select.classList.add('select--quiet');
            return select;
        }

        /** Актуальность документа: заменённый стандарт исчезает из поиска. */
        function documentStatusCell(item) {
            const title = item.status_title || item.status || 'действующий';
            if (!isAdmin()) {
                return h('span', {
                    class: 'small' + (item.searchable === false ? ' status-off' : ''),
                }, title);
            }
            const select = h('select', {
                class: 'domain-select select--quiet' +
                    (item.searchable === false ? ' status-off' : ''),
                title: 'Актуальность документа. Заменённый и архивный не участвуют в поиске.',
                onchange: (event) => saveStatus(item, event.target.value, event.target),
            }, (state.config.statuses || DEFAULT_STATUSES).map((entry) => h('option', {
                value: entry.id, selected: (item.status || 'current') === entry.id,
            }, entry.title)));
            return select;
        }

        async function saveStatus(item, value, select) {
            const previous = item.status || 'current';
            let supersededBy = '';
            if (value === 'superseded') {
                // Своё окно, а не системное window.prompt: то выглядит как
                // сообщение браузера посреди программы и пугает.
                const answer = await promptDialog({
                    title: 'Чем заменён документ',
                    message: 'Укажите идентификатор новой редакции — он есть в столбце '
                        + '«Идентификатор». Можно оставить пустым: документ всё равно '
                        + 'будет исключён из поиска.',
                    placeholder: 'standards/obw-method-2024',
                    confirmText: 'Отметить заменённым',
                });
                if (answer === null) {           // отменили — состояние не меняем
                    select.value = previous;
                    return;
                }
                supersededBy = String(answer).trim();
            }
            select.disabled = true;
            try {
                const data = await api.put('/api/library/' + encodePath(item.doc_id) + '/status',
                    { status: value, superseded_by: supersededBy });
                Object.assign(item, data.document || {});
                select.classList.toggle('status-off', item.searchable === false);
                toast('Документ «' + (item.title || item.doc_id) + '» — ' +
                    (item.status_title || value) +
                    (item.searchable === false ? ' (исключён из поиска)' : ''), 'ok');
                // Фильтр по актуальности включён, а документ из него вышел —
                // строку надо убрать со страницы, иначе она врёт.
                if (libState.status && libState.status !== item.status) await loadLibrary();
            } catch (error) {
                select.value = previous;
                toastError(error);
            } finally {
                select.disabled = false;
            }
        }

        async function saveDomain(item, value, select) {
            const previous = item.domain || '';
            select.disabled = true;
            try {
                const data = await api.put('/api/library/' + encodePath(item.doc_id) + '/domain',
                    { domain: value });
                item.domain = (data.document && data.document.domain) || value;
                toast('Направление документа «' + (item.title || item.doc_id) + '» — ' +
                    domainTitle(item.domain), 'ok');
                if (libState.domain && libState.domain !== item.domain) await loadLibrary();
            } catch (error) {
                select.value = previous;
                toastError(error);
            } finally {
                select.disabled = false;
            }
        }

        async function handleFiles(files) {
            if (!files.length) return;
            for (const file of files) {
                const bar = h('i', {});
                const status = h('span', { class: 'small muted' }, 'загрузка…');
                const row = h('div', { class: 'upload-row' },
                    h('span', { class: 'small' }, file.name),
                    h('span', { class: 'small faint' }, fmtBytes(file.size)),
                    h('span', { class: 'bar' }, bar), status);
                uploadList.appendChild(row);
                const form = new FormData();
                form.append('file', file);
                form.append('doc_type', uploadType.value);
                form.append('domain', uploadDomain.value);
                try {
                    const data = await uploadFile('/api/library/upload', form, (fraction) => {
                        bar.style.width = Math.round(fraction * 100) + '%';
                    });
                    bar.style.width = '100%';
                    showUploadResult(row, status, file, data);
                } catch (error) {
                    status.textContent = errorText(error);
                    status.className = 'small is-bad';
                }
            }
            await loadLibrary();
            // Векторы новых фрагментов уже строятся фоном: показываем ход.
            await loadVectors();
        }

        /* Что на самом деле стало с файлом.

           Раньше строка говорила «готово, фрагментов: 231» — и на этом всё.
           Заменил ли он прежний документ, прочитался ли текст целиком, не
           склеился ли он в сплошную строку — было неизвестно, а на глаз
           отличить принятый документ от испорченного нельзя. Инженер клал
           файл и уходил, считая, что тот работает. */
        function showUploadResult(row, status, file, data) {
            const result = data.result || {};
            const document_ = data.document || null;
            const failed = result.failed || 0;
            const chunks = document_ ? (document_.chunk_count || 0)
                : (result.chunks || 0);

            if (failed || (!document_ && !chunks)) {
                status.textContent = 'не прочитан';
                status.className = 'small is-bad';
            } else if (result.updated) {
                // Файл с таким же именем уже лежал: молча заменять и молчать
                // об этом нельзя — человек думает, что добавил второй.
                status.textContent = 'заменил прежний · фрагментов: ' + chunks;
                status.className = 'small is-ok';
            } else {
                status.textContent = 'добавлен · фрагментов: ' + chunks;
                status.className = 'small is-ok';
            }

            // Замечания приёма — под строкой, целиком: там написано, почему
            // документ прочитан не так, как ожидалось.
            const remarks = (result.failures || []).concat(result.notes || []);
            if (remarks.length) {
                row.appendChild(h('div', { class: 'upload-remarks small muted' },
                    remarks.map((text) => h('div', {}, text))));
            }
            if (document_) {
                row.appendChild(h('div', { class: 'upload-remarks' },
                    h('button', {
                        class: 'linklike small',
                        title: 'Показать, что система вычитала из файла',
                        onclick: () => showDocument(document_),
                    }, 'посмотреть, что прочитано')));
            }
        }

        async function reindex() {
            const force = forceCheckbox.checked;
            if (force) {
                const ok = await confirmDialog({
                    title: 'Принудительная переиндексация',
                    message: 'Все документы библиотеки будут разобраны и нарезаны заново, даже если файл не менялся.',
                    confirmText: 'Переиндексировать',
                });
                if (!ok) return;
            }
            try {
                const data = await withOverlay('Переиндексация библиотеки',
                    'Файлы с неизменившимся SHA-256 пропускаются.',
                    () => api.post('/api/library/reindex', { force: force }));
                const result = data.result || {};
                toast('Переиндексация завершена: добавлено ' + (result.added || 0) +
                    ', обновлено ' + (result.updated || 0) +
                    ', пропущено ' + (result.skipped || 0) +
                    ', ошибок ' + (result.failed || 0) +
                    ', фрагментов ' + (result.chunks || 0), (result.failed ? 'error' : 'ok'), 9000);
                await loadLibrary();
                await loadVectors();
                // Счётчик «ошибок 3» не говорит, КАКИЕ файлы не попали в
                // библиотеку и что с ними не так. Список показываем отдельно:
                // всплывающее сообщение для него слишком коротко живёт.
                showIngestReport(result);
            } catch (error) {
                toastError(error);
            }
        }

        function showIngestReport(result) {
            const failures = result.failures || [];
            const notes = result.notes || [];
            if (!failures.length && !notes.length) return;
            const block = (title, lines, level) => lines.length ? h('div', {
                style: { marginBottom: '14px' },
            },
                h('div', {},
                    h('span', { class: 'badge badge--' + level }, title),
                    h('span', { class: 'small muted', style: { marginLeft: '8px' } },
                        lines.length)),
                ...lines.map((line) => h('div', {
                    class: 'small',
                    style: { marginTop: '6px', whiteSpace: 'pre-wrap' },
                }, line))) : null;
            const dialog = openModal({
                title: 'Итог загрузки библиотеки',
                body: h('div', {},
                    block('Не принято — требует действий', failures, 'danger'),
                    block('Замечания — к сведению', notes, 'warn')),
                footer: [h('button', {
                    class: 'btn btn--primary',
                    onclick: () => dialog.close(),
                }, 'Понятно')],
            });
        }

        async function removeDocument(item) {
            const ok = await confirmDialog({
                title: 'Удалить документ',
                message: 'Документ «' + (item.title || item.doc_id) +
                    '» и все его фрагменты будут удалены из индекса.',
                note: 'Уже сгенерированные отчёты сохраняют цитаты в своём приложении и не пострадают.',
                confirmText: 'Удалить',
                danger: true,
            });
            if (!ok) return;
            try {
                await api.del('/api/library/' + encodePath(item.doc_id));
                toast('Документ удалён', 'ok');
                await loadLibrary();
            } catch (error) {
                toastError(error);
            }
        }

        async function runSearch() {
            const query = searchInput.value.trim();
            if (!query) {
                toast('Введите поисковый запрос', 'error', 3000);
                return;
            }
            const types = searchTypes.filter((item) => item.checkbox.checked).map((item) => item.type);
            clear(searchResults);
            searchResults.appendChild(loadingBox('Ищем по библиотеке…'));
            try {
                const url = '/api/search?q=' + encodeURIComponent(query) +
                    '&top_k=' + encodeURIComponent(topKInput.value || '10') +
                    (types.length ? '&doc_types=' + encodeURIComponent(types.join(',')) : '') +
                    (searchDomain.value ? '&domains=' + encodeURIComponent(searchDomain.value) : '');
                const data = await api.get(url);
                clear(searchResults);
                if (data.note) searchResults.appendChild(h('div', { class: 'small muted' }, data.note));
                if (data.warning) searchResults.appendChild(h('div', { class: 'small muted' }, data.warning));
                // Половина библиотеки английская, спрашивают по-русски, да и
                // один термин отдел пишет по-разному: КСВ и КСВН, ОСШ и
                // «отношение сигнал/шум». Если запрос дополнен по словарю —
                // сказать об этом: иначе и английский текст в выдаче, и
                // страница, где нужного слова будто нет, выглядят взявшимися
                // ниоткуда.
                if (data.expansion && data.expansion.length) {
                    searchResults.appendChild(h('div', { class: 'small muted' },
                        'Искали также по равнозначным написаниям: ' + data.expansion.join(', ')));
                }
                const items = data.items || [];
                if (!items.length) {
                    searchResults.appendChild(emptyBox('Ничего не нашлось',
                        'Ни один фрагмент не совпал. Попробуйте другое написание обозначения, слово из самого текста стандарта или снимите отбор по направлению.'));
                    return;
                }
                items.forEach((hit) => {
                    searchResults.appendChild(h('div', { class: 'search-hit' },
                        h('div', { class: 'head' },
                            h('b', {}, hit.citation || hit.chunk_uid),
                            h('span', { class: 'badge' }, docTypeLabel(hit.doc_type)),
                            hit.domain ? h('span', { class: 'badge badge--info' }, domainTitle(hit.domain)) : null,
                            h('span', { class: 'faint small' }, 'вес ' + fmtNumber(hit.score, 3))),
                        h('div', { class: 'text' }, hit.text || '')));
                });
            } catch (error) {
                clear(searchResults);
                searchResults.appendChild(errorBox(error));
            }
        }

        await loadLibrary();
        await loadVectors();
        await loadQuality();
        await loadSummary();
    }

    // =====================================================================
    // 8. Экран «Метрики» и журнал действий
    // =====================================================================

    // =====================================================================
    // 8а. Экран «Сводка» — состояние отдела на сегодня
    // =====================================================================

    const boardState = { days: 30, data: null };

    /** Обрезать текст по слову, с многоточием. */
    function обрезать(текст, предел) {
        const t = String(текст || '').replace(/\s+/g, ' ').trim();
        if (t.length <= предел) return t;
        const край = t.lastIndexOf(' ', предел);
        return t.slice(0, край > предел * 0.6 ? край : предел) + '…';
    }

    /** Полоса «путь писем»: сегмент на каждое состояние, по порядку пути. */
    function путьПисем(порядок, всего, ступень) {
        const полоса = h('div', {
            class: 'path-bar', role: 'img',
            'aria-label': 'Путь писем: ' + порядок.map((item) =>
                item.title + ' — ' + item.count).join(', '),
        });
        порядок.forEach((item, номер) => {
            if (!item.count) return;
            const доля = item.count / всего;
            полоса.appendChild(h('span', {
                class: 'path-seg',
                dataset: { step: String(ступень(item.id) || 1) },
                style: { flexGrow: String(item.count), '--i': String(номер) },
                tabindex: '0',
                onmouseenter: (event) => подсказка(event.currentTarget,
                    item.title, item.count + ' ' + plural(item.count, 'письмо', 'письма', 'писем')
                    + ' · ' + Math.round(доля * 100) + '%'),
                onfocus: (event) => подсказка(event.currentTarget, item.title,
                    item.count + ' · ' + Math.round(доля * 100) + '%'),
                onmouseleave: () => подсказка(null),
                onblur: () => подсказка(null),
            }));
        });
        return полоса;
    }

    /* Одна общая всплывающая подсказка на всё приложение: показывается у
       знака, над которым мышь или фокус, и не мешает ни прокрутке, ни клику. */
    function подсказка(узел, заголовок, текст) {
        let окно = document.getElementById('tip');
        if (!узел) {
            if (окно) окно.hidden = true;
            return;
        }
        if (!окно) {
            окно = h('div', { id: 'tip', class: 'tip', role: 'tooltip', hidden: true });
            document.body.appendChild(окно);
        }
        clear(окно);
        окно.appendChild(h('b', {}, заголовок));
        if (текст) окно.appendChild(h('span', {}, текст));
        окно.hidden = false;
        const где = узел.getBoundingClientRect();
        const ширина = окно.offsetWidth;
        const левее = Math.max(8, Math.min(window.innerWidth - ширина - 8,
            где.left + где.width / 2 - ширина / 2));
        окно.style.left = левее + 'px';
        окно.style.top = Math.max(8, где.top - окно.offsetHeight - 8) + 'px';
    }

    /* Приветствие по времени суток. Утром сводку открывают первой, и
       обращение по имени-отчеству — не украшение: так в отделе принято
       обращаться, и экран, который это знает, воспринимается своим. */
    function приветствие() {
        const час = new Date().getHours();
        const слова = час >= 5 && час < 12 ? 'Доброе утро'
            : час >= 12 && час < 18 ? 'Добрый день'
                : час >= 18 && час < 23 ? 'Добрый вечер' : 'Доброй ночи';
        const имя = имяОтчество(state.user && state.user.full_name);
        return имя ? слова + ', ' + имя : слова;
    }

    /** «Иванов Иван Иванович» → «Иван Иванович»; инициалы — как есть. */
    function имяОтчество(фио) {
        const части = String(фио || '').trim().split(/\s+/);
        if (части.length >= 3 && части[1].length > 2) return части[1] + ' ' + части[2];
        if (части.length === 2 && части[1].length > 2) return части[1];
        return '';
    }

    function сегодняСловами() {
        const дата = new Date();
        const день = дата.toLocaleDateString('ru-RU', { weekday: 'long' });
        return день.charAt(0).toUpperCase() + день.slice(1) + ', '
            + дата.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });
    }

    /* Узор приветствия — орбиты и спутник: тот же мотив, что на окне входа.
       Рисуется встроенным SVG, наружу ни одного обращения. */
    function орбиты() {
        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.setAttribute('class', 'hero-art');
        svg.setAttribute('viewBox', '0 0 320 160');
        svg.setAttribute('aria-hidden', 'true');
        svg.innerHTML =
            '<g fill="none" stroke="currentColor" stroke-width="1">' +
            '<ellipse cx="230" cy="96" rx="150" ry="46" opacity=".22"/>' +
            '<ellipse cx="230" cy="96" rx="104" ry="31" opacity=".30"/>' +
            '<ellipse cx="230" cy="96" rx="60" ry="18" opacity=".38"/></g>' +
            '<circle cx="230" cy="96" r="22" fill="currentColor" opacity=".16"/>' +
            '<circle cx="230" cy="96" r="12" fill="currentColor" opacity=".28"/>' +
            '<g class="hero-sat"><circle cx="126" cy="80" r="4" fill="currentColor"/>' +
            '<path d="M117 80h-8M135 80h8" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></g>';
        return svg;
    }

    async function renderBoard(view) {
        clear(view);
        const page = h('div', { class: 'page' });
        view.appendChild(page);

        const periodSelect = h('select', {
            onchange: (event) => {
                boardState.days = Number(event.target.value) || 30;
                load();
            },
        }, [7, 30, 90, 365].map((days) => h('option', {
            value: String(days), selected: boardState.days === days,
        }, 'за ' + days + ' ' + plural(days, 'день', 'дня', 'дней'))));

        const итогДня = h('div', { class: 'hero-sub' });
        const head = h('section', { class: 'hero' },
            h('div', { class: 'hero-text' },
                h('div', { class: 'hero-date' }, сегодняСловами()),
                h('h2', { class: 'hero-title' }, приветствие()),
                итогДня),
            h('div', { class: 'hero-actions' },
                periodSelect,
                h('button', { class: 'btn btn--glass', onclick: () => load() },
                    icon('refresh'), 'Обновить')),
            орбиты());

        const body = h('div', {});
        append(page, [head, body]);

        async function load() {
            clear(body);
            body.appendChild(loadingBox());
            try {
                boardState.data = await api.get('/api/board?days=' + boardState.days);
                draw();
            } catch (error) {
                clear(body);
                body.appendChild(errorBox(error));
            }
        }

        function draw() {
            const data = boardState.data;
            const totals = data.totals || {};
            clear(body);

            /* Верхний ряд — то, что спрашивают с отдела в первую очередь. */
            tileIndex = 0;
            const всего = sumStatuses(data.statuses);
            const вРаботе = totals.open || 0;
            const доля = (часть, целое) => (целое > 0 ? часть / целое : 0);
            const tiles = h('div', { class: 'tiles' },
                tile(вРаботе, 'писем в работе',
                    'всего зарегистрировано: ' + всего,
                    '#/cases', 'open', '', доля(вРаботе, всего), 'letters'),
                tile(totals.overdue || 0, 'просрочено',
                    totals.overdue ? 'сроки уже прошли' : 'просроченных нет',
                    '#/cases', 'overdue', totals.overdue ? 'bad' : 'ok',
                    доля(totals.overdue || 0, вРаботе), 'alert'),
                tile(totals.soon || 0, 'горят в ближайшие 3 дня', 'по сроку ответа',
                    '#/cases', 'open', totals.soon ? 'warn' : '',
                    доля(totals.soon || 0, вРаботе), 'flame'),
                tile(totals.unassigned || 0, 'без исполнителя',
                    totals.unassigned ? 'нужно распределить' : 'все письма распределены',
                    '#/cases', 'open', totals.unassigned ? 'warn' : 'ok',
                    доля(totals.unassigned || 0, вРаботе), 'users'),
                tile(totals.staff || 0, 'человек в строю',
                    'на дежурстве: ' + (totals.on_duty || 0) + ' · отсутствуют: ' + (totals.away || 0),
                    '', '', 'ok', доля((totals.staff || 0) - (totals.away || 0), totals.staff || 0),
                    'roster'),
                tile((data.movement || {}).sent || 0, 'ответов отправлено',
                    'поступило за период: ' + ((data.movement || {}).came || 0) +
                    ' · проверено, но не отправлено: '
                    + Math.max(0, ((data.movement || {}).checked || 0)
                        - ((data.movement || {}).sent || 0)) +
                    ' · редакций отчётов: ' + ((data.movement || {}).reports || 0),
                    '', '', '', undefined, 'send'));

            const columns = h('div', { class: 'board-cols' },
                h('div', {}, workloadCard(data), movementCard(data)),
                h('div', {}, deadlinesCard(data), dutyCard(data)));

            append(body, [tiles, columns]);
            итогДня.textContent = итогСловами(totals);
        }

        /* Итог дня одной строкой — то, ради чего утром открывают сводку. */
        function итогСловами(totals) {
            const части = [];
            const вРаботе = totals.open || 0;
            части.push(вРаботе
                ? вРаботе + ' ' + plural(вРаботе, 'письмо', 'письма', 'писем') + ' в работе'
                : 'писем в работе нет');
            части.push(totals.overdue
                ? 'просрочено: ' + totals.overdue
                : 'просрочек нет');
            if (totals.soon) части.push('горят: ' + totals.soon);
            if (totals.staff) части.push('в строю ' + Math.max(0, totals.staff - (totals.away || 0))
                + ' из ' + totals.staff);
            return части.join(' · ');
        }

        //: Порядковый номер плитки. По нему идёт задержка появления: плитки
        //: вступают по очереди, и глаз успевает прочитать каждую.
        let tileIndex = 0;

        /**
         * Плитка сводки.
         *
         * `share` — доля от целого, 0…1. Показывается полоской под числом:
         * «3 писем в работе» само по себе ни о чём не говорит, а «3 из 6»
         * говорит, и полоска считается быстрее, чем два числа.
         */
        function tile(value, label, note, href, tab, kind, share, значок) {
            const node = h('a', {
                class: 'tile' + (kind ? ' tile--' + kind : ''),
                href: href,
                style: { '--i': String(tileIndex++) },
                onclick: () => { if (tab) casesState.view = tab; },
            },
                значок ? h('span', { class: 'tile-icon', 'aria-hidden': 'true' }, icon(значок)) : null,
                countUp(h('div', { class: 'tile-value' }), Number(value) || 0),
                h('div', { class: 'tile-label' }, label),
                h('div', { class: 'tile-note' }, note));
            if (typeof share === 'number' && isFinite(share) && share > 0) {
                node.appendChild(h('div', {
                    class: 'tile-meter',
                    role: 'presentation',
                }, h('i', { style: { width: Math.round(Math.min(1, share) * 100) + '%' } })));
            }
            return node;
        }

        function sumStatuses(statuses) {
            return (statuses || []).reduce((sum, item) => sum + (item.count || 0), 0);
        }

        /* Нагрузка по людям: кто сколько ведёт и у кого горит. */
        function workloadCard(data) {
            const people = data.people || [];
            const card = h('div', { class: 'card card-pad' },
                h('div', { class: 'card-title' }, 'Нагрузка и занятость'));
            if (!people.length) {
                card.appendChild(emptyBox('Личный состав не заведён',
                    'Пока в системе нет людей, распределять письма не на кого.',
                    h('a', { class: 'btn btn--sm', href: '#/people' }, 'Завести людей')));
                return card;
            }
            const peak = people.reduce((max, item) => Math.max(max, item.open || 0), 0) || 1;
            const rows = h('tbody', {});

            /* Кто ничем не занят — в конец и под сворачивание. В отделе на
               двадцать человек свободных больше, чем занятых, и сводка
               «кто чем занят» превращалась в две страницы нулей, из-за
               которых не видно тех, у кого горит. Отсутствующих оставляем
               наверху: их отсутствие — тоже занятость. */
            const busy = people.filter((person) =>
                (person.open || 0) > 0 || person.away || person.on_duty
                || person.active === false);
            const idle = people.filter((person) => busy.indexOf(person) === -1);
            let idleShown = false;

            function drawRows() {
                clear(rows);
                busy.forEach(addRow);
                if (idleShown) idle.forEach(addRow);
                // Никто не занят — это ответ, а не пустое место. Одна кнопка
                // «показать свободных» в пустой таблице читалась как поломка.
                if (!busy.length && !idleShown) {
                    rows.appendChild(h('tr', { class: 'row-calm' },
                        h('td', { colSpan: 5 },
                            h('div', { class: 'calm' },
                                h('span', { class: 'calm-mark', 'aria-hidden': 'true' }, icon('check')),
                                h('div', {},
                                    h('b', {}, 'Сейчас никто не загружен письмами'),
                                    h('div', { class: 'small muted' },
                                        'Свободны все ' + idle.length + ' '
                                        + plural(idle.length, 'человек', 'человека', 'человек')
                                        + ' — есть кому поручить новое.'))))));
                }
                if (!idle.length) return;
                rows.appendChild(h('tr', { class: 'row-more' },
                    h('td', { colSpan: 5 },
                        h('button', {
                            class: 'btn btn--sm',
                            onclick: () => { idleShown = !idleShown; drawRows(); },
                        }, idleShown
                            ? 'Скрыть свободных'
                            : 'Показать ещё ' + idle.length + ' '
                                + plural(idle.length, 'свободного', 'свободных', 'свободных')))));
            }

            function addRow(person) {
                rows.appendChild(h('tr', {},
                    h('td', {},
                        h('div', { class: person.active === false ? 'muted' : '' },
                            personLink(person.id, person.full_name)),
                        h('div', { class: 'small faint' },
                            roleShort(person.role) +
                            (person.team ? ' · ' + person.team : ''))),
                    h('td', {}, personState(person)),
                    h('td', { class: 'w-bar' },
                        h('div', { class: 'bar-cell' },
                            h('div', { class: 'bar' },
                                h('span', { style: { width: Math.round((person.open || 0) / peak * 100) + '%' } })),
                            h('b', {}, String(person.open || 0)))),
                    h('td', { class: 'nowrap' }, person.late
                        ? h('span', { class: 'due due--late' }, person.late + ' ' +
                            plural(person.late, 'просрочка', 'просрочки', 'просрочек'))
                        : h('span', { class: 'faint' }, '—')),
                    h('td', { class: 'nowrap small muted' },
                        person.next_deadline ? fmtDate(person.next_deadline) : '—')));
            }

            drawRows();
            card.appendChild(h('div', { class: 'table-scroll' },
                h('table', { class: 'grid' },
                    h('thead', {}, h('tr', {},
                        h('th', {}, 'Военнослужащий'),
                        h('th', {}, 'Чем занят'),
                        h('th', {}, 'Писем в работе'),
                        h('th', {}, 'Сроки'),
                        h('th', {}, 'Ближайший срок'))),
                    rows)));
            return card;
        }

        function personState(person) {
            // Отключённый военнослужащий попадает в список, только пока за ним
            // числятся письма: их надо передать живому человеку. Это
            // важнее и отпуска, и дежурства — потому и первым.
            if (person.active === false) {
                return h('span', { class: 'badge badge--danger', title:
                    'Учётная запись отключена, а письма за ней числятся: '
                    + 'передайте их другому исполнителю' }, 'отключён');
            }
            if (person.away) {
                return h('span', { class: 'badge badge--warn' },
                    person.away_title + (person.away_until ? ' до ' + fmtDate(person.away_until) : ''));
            }
            if (person.on_duty) return h('span', { class: 'badge badge--accent' }, 'на дежурстве');
            if (!person.open) return h('span', { class: 'faint small' }, 'свободен');
            return h('span', { class: 'badge badge--info' }, 'в работе');
        }

        /* Сроки: что уже просрочено и что горит. */
        function deadlinesCard(data) {
            const late = data.overdue || [];
            const soon = data.soon || [];
            const card = h('div', { class: 'card card-pad' },
                h('div', { class: 'card-title' }, 'Сроки'));
            if (!late.length && !soon.length) {
                card.appendChild(emptyBox('Всё в срок',
                    'Ни одного просроченного письма и ни одного с горящим сроком.'));
                return card;
            }
            if (late.length) card.appendChild(deadlineList('Просрочено', late, 'late'));
            if (soon.length) card.appendChild(deadlineList('Ближайшие три дня', soon, 'soon'));
            return card;
        }

        function deadlineList(title, items, kind) {
            return h('div', { class: 'due-group' },
                h('div', { class: 'due-group-title' }, title),
                h('ul', { class: 'due-list' }, items.map((item) => h('li', {},
                    h('a', { href: '#/case/' + item.id }, item.title || item.case_id),
                    h('span', { class: 'due due--' + kind }, fmtDate(item.deadline)),
                    h('span', { class: 'small faint' },
                        item.assignee_name || 'не назначен')))));
        }

        /* Дежурство и отсутствия на сегодня. */
        function dutyCard(data) {
            const duty = data.duty || [];
            const absent = data.absent || [];
            const card = h('div', { class: 'card card-pad' },
                h('div', { class: 'card-title' }, 'Дежурство и отсутствия'),
                h('div', { class: 'kv-line' },
                    h('b', {}, 'На дежурстве: '),
                    duty.length
                        ? duty.map((item) => h('span', { class: 'chip chip--flat' }, item.full_name))
                        : h('span', { class: 'faint' }, 'никто не назначен')));
            if (!absent.length) {
                card.appendChild(h('div', { class: 'muted small' }, 'Отсутствующих сегодня нет.'));
            } else {
                card.appendChild(h('ul', { class: 'plain-list' }, absent.map((item) =>
                    h('li', {},
                        h('b', {}, item.full_name),
                        h('span', { class: 'badge badge--warn' }, item.kind_title),
                        h('span', { class: 'small faint' },
                            'по ' + fmtDate(item.date_to))))));
            }
            if (isAdmin()) {
                card.appendChild(h('div', { class: 'btn-row', style: { marginTop: '10px' } },
                    h('button', {
                        class: 'btn btn--sm',
                        onclick: () => openAbsenceDialog(() => load()),
                    }, 'Отметить дежурство или отпуск')));
            }
            return card;
        }

        /* Движение писем по состояниям. */
        function movementCard(data) {
            const statuses = data.statuses || [];
            const total = sumStatuses(statuses) || 1;
            const card = h('div', { class: 'card card-pad' },
                h('div', { class: 'card-title' }, 'Письма по состояниям'));
            if (!statuses.length) {
                card.appendChild(emptyBox('Писем ещё нет',
                    'Как только письмо зарегистрируют, здесь встанет его путь по состояниям.'));
                return card;
            }
            // Состояния письма — не разные сущности, а ступени одного пути:
            // принято → в работе → на проверке → к отправке → отправлено →
            // в архиве. Поэтому не набор красок, а одна краска от светлой к
            // тёмной: движение по шкале видно само, без легенды.
            const ступень = (id) => CASE_FLOW_ORDER.indexOf(id) + 1;
            // Строки идут по пути письма, а не по алфавиту опознавателя.
            // Иначе шкала от светлого к тёмному ложится вперемешку и
            // перестаёт что-либо значить: краска показывает ступень, а
            // порядок строк обязан показывать её же.
            const порядок = statuses.slice().sort(
                (а, б) => (ступень(а.id) || 99) - (ступень(б.id) || 99));
            // Путь писем одной полосой: где сейчас стоит вся почта отдела.
            // Часть от целого — сложенная полоса, а не кольцо: ступени идут
            // по порядку, и полоса этот порядок сохраняет, а кольцо его
            // замыкает в круг. Краска — та же порядковая шкала, что у строк
            // ниже; строки служат легендой и таблицей, так что состояние не
            // держится на одном цвете.
            card.appendChild(путьПисем(порядок, total, ступень));
            card.appendChild(h('div', { class: 'flow' }, порядок.map((item, номер) =>
                h('div', {
                    class: 'flow-row',
                    dataset: { step: String(ступень(item.id) || 1) },
                    title: item.title + ': ' + item.count + ' из ' + total,
                },
                    h('span', { class: 'flow-name' }, item.title),
                    h('div', { class: 'bar' },
                        h('span', {
                            style: {
                                width: Math.round(item.count / total * 100) + '%',
                                '--i': String(номер),
                            },
                        })),
                    h('b', {}, String(item.count))))));
            return card;
        }

        await load();
    }

    /** Отметить дежурство, отпуск или командировку. */
    async function openAbsenceDialog(after) {
        const staff = await staffList();
        const who = h('select', {}, staff.map((person) => h('option', {
            value: String(person.id),
        }, (person.full_name || person.login) + ' — ' + roleShort(person.role))));
        const kind = h('select', {}, Object.keys(ABSENCE_LABEL).map((key) =>
            h('option', { value: key }, ABSENCE_LABEL[key])));
        const from = h('input', { type: 'date', value: todayIso() });
        const to = h('input', { type: 'date', value: todayIso() });
        const note = h('input', { type: 'text', placeholder: 'необязательно' });

        const save = h('button', { class: 'btn btn--primary', onclick: submit }, 'Отметить');
        const dialog = openModal({
            title: 'Дежурство или отсутствие',
            body: [
                h('div', { class: 'form-grid' },
                    h('label', { class: 'field' }, 'Военнослужащий', who),
                    h('label', { class: 'field' }, 'Вид', kind),
                    h('label', { class: 'field' }, 'С какого числа', from),
                    h('label', { class: 'field' }, 'По какое число', to)),
                h('label', { class: 'field' }, 'Примечание', note),
            ],
            footer: [
                h('span', { class: 'spacer' }),
                h('button', { class: 'btn', onclick: () => dialog.close() }, 'Отмена'),
                save,
            ],
        });

        async function submit() {
            save.disabled = true;
            try {
                await api.post('/api/absences', {
                    user_id: Number(who.value),
                    kind: kind.value,
                    date_from: from.value,
                    date_to: to.value,
                    note: note.value.trim(),
                });
                dialog.close();
                toast('Отмечено', 'ok');
                if (after) after();
            } catch (error) {
                toastError(error);
            } finally {
                save.disabled = false;
            }
        }
    }

    // =====================================================================
    // Разбор потока: этапы вживую
    // =====================================================================

    //: Разбор идёт на сервере заданием; страница спрашивает его состояние, пока
    //: оно не закончится, и показывает этапы и журнал хода по мере появления.
    const разборПотока = { таймер: null };

    function остановитьОпросПотока() {
        if (разборПотока.таймер) {
            clearTimeout(разборПотока.таймер);
            разборПотока.таймер = null;
        }
    }

    const ПРОФИЛИ_РАЗБОРА = [
        ['быстро', 'быстро — до полутора минут'],
        ['обычно', 'обычно — до 10 минут, длинные коды до 1024 бит'],
        ['глубоко', 'глубоко — до часа: коды до 2048 бит, выколотые до 7/8'],
    ];

    const ПРИМЕРЫ_СЛОЁВ = 'Слои, которые вы уже знаете, — по одному в строке, по порядку:\n' +
        'инверсия · сдвиг 5 · nrzi · манчестер · скремблер 3,20 · ' +
        'свёрточный 171/133 K=7 · выколотый 171/133 K=7 шаблон 110110 · ' +
        'перемежение 12 7 · форни 12 17 0 · pdh E2 приток 1 · ' +
        'плоскость 6 (или «плоскость 6 поворот 270° Грей половинами») · ' +
        'синхро 0x1ACFFC1D ошибок 2 · кадры 0x47 длина 1504 · реверс 8 · xor 0xFF · прореживание 2 фаза 1 · ' +
        'фм 3 (или «фм 3 поворот 2 отражение») · метки 2: 0 1 3 2 · биты символа 4: 1 0 3 2 · ' +
        'ldpc ИМЯ выколоты 0-191 укорочены 1000-1023 · ldpc nr-bg1-z384 · ldpc dvb-s2-64800-38880 перемежение 8PSK';

    // -- матрицы над GF(2): окно «Матрицы» рабочего стола (считает сервер — /api/potok/matrix) --

    /** Действия окна «Матрицы»: группа в списке, что нужно вторым (матрица B, вектор b, векторы) и пояснение. */
    const ДЕЙСТВИЯ_МАТРИЦ = [
        { оп: 'гаусс', группа: 'Приведение', имя: 'Метод Гаусса: ступенчатый вид',
            пояснение: 'Прямой ход: под каждой опорной единицей — нули. Ранг и опорные столбцы; у матриц до 16 × 64 — ход по шагам.' },
        { оп: 'жордан', группа: 'Приведение', имя: 'Гаусс — Жордан: приведённый вид',
            пояснение: 'Нули и под, и над опорными единицами. Такой вид у пространства строк единственный.' },
        { оп: 'разложение', группа: 'Приведение', имя: 'PLU-разложение: P·A = L·U',
            пояснение: 'P — перестановка строк, L — нижняя треугольная с единицами на диагонали, U — ступенчатая.' },
        { оп: 'ранг', группа: 'Свойства', имя: 'Ранг', пояснение: 'Сколько строк независимы и какие столбцы опорные.' },
        { оп: 'определитель', группа: 'Свойства', имя: 'Определитель', пояснение: 'У квадратной: 1 — невырождена, 0 — вырождена.' },
        { оп: 'обратная', группа: 'Свойства', имя: 'Обратная матрица', пояснение: 'Гаусс — Жордан над [A | I]; у вырожденной — ранг и сообщение.' },
        { оп: 'решить', группа: 'Системы', имя: 'Решить A·x = b', второе: 'b',
            пояснение: 'Частное решение (свободные неизвестные — нули) и базис решений A·x = 0 — или «несовместна».' },
        { оп: 'ядро', группа: 'Системы', имя: 'Ядро (нуль-пространство)', пояснение: 'Базис всех x с A·xᵀ = 0: n − ранг строк.' },
        { оп: 'проверочная', группа: 'Коды', имя: 'Проверочная H по порождающей G',
            пояснение: 'H·Gᵀ = 0, ранг H = n − k. Строки H порождают двойственный код.' },
        { оп: 'порождающая', группа: 'Коды', имя: 'Порождающая G по проверочной H', пояснение: 'Все слова с нулевым синдромом — ядро H.' },
        { оп: 'систематический', группа: 'Коды', имя: 'Систематический вид G = [I | P]',
            пояснение: 'G = [I | P] и H = [Pᵀ | I]. Если опорные — не первые k столбцов, столбцы переставляются; перестановка — в итоге.' },
        { оп: 'код', группа: 'Коды', имя: 'Код по G: k, n, d, весовой спектр',
            пояснение: 'd — перебором 2^k слов (k ≤ 20) или через двойственный код и тождество Мак-Вильямс (n − k ≤ 20).' },
        { оп: 'синдромы', группа: 'Коды', имя: 'Синдромы векторов по H', второе: 'векторы',
            пояснение: 'H·vᵀ для каждого вектора-строки; нулевой синдром — кодовое слово.' },
        { оп: 'произведение', группа: 'Действия', имя: 'Произведение A·B', второе: 'B', пояснение: 'По модулю 2; столбцов у A — сколько строк у B.' },
        { оп: 'сумма', группа: 'Действия', имя: 'Сумма A + B', второе: 'B', пояснение: 'Поэлементно по модулю 2 (XOR); размеры равны.' },
        { оп: 'транспонирование', группа: 'Действия', имя: 'Транспонирование Aᵀ', пояснение: 'Строки становятся столбцами.' },
    ];

    /**
     * Матрица из текста окна «Матрицы»: строка текста — строка матрицы, 0 и 1 с любыми пробелами
     * (запятые, «_», «|» и скобки тоже пропускаются), строки можно разделять и «;». HEX — с 0x: по
     * 4 бита на цифру, а при ширине w — значение в w бит (слева нули). Итог {строки} или {ошибка}.
     */
    function разобратьМатрицу(текст, ширина) {
        const w = Math.max(0, Math.floor(Number(ширина) || 0));
        const ряды = String(текст || '').split(/\r?\n|;/);
        const строки = [];
        for (let i = 0; i < ряды.length; i += 1) {
            const т = ряды[i].replace(/[\s,_|[\]()]/g, '');
            if (!т) continue;
            let биты = т;
            if (/^0x/i.test(т)) {
                if (!/^0x[0-9a-f]+$/i.test(т)) return { ошибка: 'строка ' + (i + 1) + ': в HEX — только цифры 0–9 и a–f' };
                биты = т.slice(2).split('').map((ц) => parseInt(ц, 16).toString(2).padStart(4, '0')).join('');
                if (w) {
                    if (биты.slice(0, Math.max(0, биты.length - w)).includes('1')) return { ошибка: 'строка ' + (i + 1) + ': ' + т + ' не помещается в ' + w + ' бит' };
                    биты = биты.padStart(w, '0').slice(-w);
                }
            } else if (!/^[01]+$/.test(т)) {
                return { ошибка: 'строка ' + (i + 1) + ': только 0 и 1 (или HEX с 0x)' };
            }
            if (строки.length && биты.length !== строки[0].length) {
                return { ошибка: 'строка ' + (i + 1) + ': ' + биты.length + ' бит, а в первой — ' + строки[0].length };
            }
            строки.push(биты);
        }
        return строки.length ? { строки } : { ошибка: 'матрица пуста' };
    }

    /** Проверочная матрица кода Хэмминга с r проверками: столбец j — двоичная запись j + 1 (все ненулевые векторы). */
    function примерХэмминга(r) {
        const n = (1 << r) - 1;
        return Array.from({ length: r }, (_, i) => Array.from({ length: n }, (__, j) => ((j + 1) >> (r - 1 - i)) & 1).join(''));
    }

    /** Строка матрицы кусками для показа: [текст, опорный] — опорные столбцы отдельно (подсветка),
     *  промежуток каждые «группа» бит (0 — без промежутков). */
    function кускиСтрокиМатрицы(строка, опорные, группа) {
        const куски = [];
        const добавить = (т, о) => {
            const п = куски[куски.length - 1];
            if (п && п[1] === о) п[0] += т;
            else куски.push([т, о]);
        };
        for (let j = 0; j < строка.length; j += 1) {
            if (группа && j && j % группа === 0) добавить(' ', false);
            добавить(строка[j], опорные.has(j));
        }
        return куски;
    }

    /** Линейка номеров столбцов над матрицей: при группах — номер первого столбца группы, без групп — j mod 10. */
    function линейкаМатрицы(n, группа) {
        if (!группа) return Array.from({ length: n }, (_, j) => j % 10).join('');
        let т = '';
        for (let j = 0; j < n; j += группа) т = т.padEnd(j + j / группа, ' ') + j;
        return т;
    }

    /** Перестановка столбцов коротко — только сдвинутые, «место←исходный»: не больше 12, дальше «…». */
    function перестановкаКратко(п) {
        const сдвинутые = п.map((и, место) => [место, и]).filter(([место, и]) => место !== и);
        return сдвинутые.slice(0, 12).map(([место, и]) => место + '←' + и).join(', ') + (сдвинутые.length > 12 ? ', …' : '');
    }

    /** Шаг метода Гаусса словами: опорная строка и столбец, перестановка, к каким строкам прибавлена. */
    function шагГаусса(ш) {
        return 'столбец ' + ш.столбец + ': опорная строка ' + ш.строка +
            (ш.обмен === null ? '' : ' (переставлены строки ' + ш.строка + ' и ' + ш.обмен + ')') +
            (ш.прибавлена_к.length ? '; прибавлена к строкам ' + ш.прибавлена_к.join(', ') : '; прибавлять не к чему');
    }

    /** Какие матрицы показать у итога: [подпись, строки, опорные столбцы для подсветки]. */
    function матрицыИтога(d) {
        const м = [];
        const с = (подпись, строки, опорные) => м.push([подпись, строки, опорные || []]);
        const подряд = (от, до) => Array.from({ length: Math.max(0, до - от) }, (_, i) => от + i);
        switch (d.операция) {
        case 'гаусс': с('Ступенчатый вид', d.матрица, d.опорные); break;
        case 'жордан': с('Приведённый ступенчатый вид', d.матрица, d.опорные); break;
        case 'разложение': с('P — перестановка строк', d.P); с('L — нижняя треугольная', d.L); с('U — ступенчатая', d.U, d.опорные); break;
        case 'обратная': if (!d.вырождена) с('A⁻¹', d.матрица); break;
        case 'решить': if (d.совместна) { с('Частное решение x', [d.частное]); с('Базис решений A·x = 0', d.базис); } break;
        case 'ядро': с('Базис ядра', d.матрица); break;
        case 'проверочная': с('H — проверочная', d.матрица); break;
        case 'порождающая': с('G — порождающая', d.матрица); break;
        case 'систематический': case 'код':
            с('G = [I | P]', d.G, подряд(0, d.k));
            с('H = [Pᵀ | I]', d.H, подряд(d.k, d.n));
            if (d.переставлены) с('H в исходном порядке столбцов', d.H_исходные);
            break;
        case 'синдромы': с('Синдромы — по строке на вектор', d.матрица); break;
        case 'ранг': case 'определитель': break;
        default: с('Итог', d.матрица);
        }
        if (d.A) м.push(['A — кадры массива' + (d.A.length < d.размер[0] ? ' (первые ' + d.A.length + ' из ' + d.размер[0] + ')' : ''), d.A, []]);
        return м;
    }

    /** Сводка итога — строки для окна и журнала: размер, ранг, совместность, k, n, d. */
    function сводкаМатриц(d) {
        const [m, n] = d.размер;
        const с = [];
        if (d.поток) с.push('Из массива: ' + m + ' строк по ' + n + ' бит с бита ' + d.поток.сдвиг + ' — ' + d.поток.вывод);
        const опорные = (о) => о.length ? ' · опорные столбцы ' + (о.length > 24 ? о.slice(0, 24).join(', ') + ', …' : о.join(', ')) : '';
        const итог = (строки) => строки.length + ' × ' + (строки.length ? строки[0].length : 0);
        switch (d.операция) {
        case 'гаусс': case 'жордан': case 'разложение': с.push('A: ' + m + ' × ' + n + ' · ранг ' + d.ранг + опорные(d.опорные)); break;
        case 'ранг': с.push('Ранг ' + d.ранг + (d.полный ? ' — полный' : ' — неполный: меньше ' + Math.min(m, n)) + опорные(d.опорные)); break;
        case 'определитель': с.push('Определитель ' + d.определитель + (d.определитель ? ' — матрица невырождена' : ' — матрица вырождена')); break;
        case 'обратная': с.push(d.вырождена ? 'Матрица вырождена: ранг ' + d.ранг + ' < ' + n + ' — обратной нет' : 'Обратная есть: A·A⁻¹ = I'); break;
        case 'решить': с.push(d.совместна ? 'Совместна · ранг ' + d.ранг + ' · решений 2^' + (n - d.ранг) : 'Несовместна: b не выражается через столбцы A'); break;
        case 'ядро': case 'проверочная': case 'порождающая':
            с.push('Ранг ' + d.ранг + ' из ' + n + ' · ' + (d.операция === 'ядро' ? 'размерность ядра ' : 'строк итога ') + d.размерность); break;
        case 'систематический': case 'код':
            с.push('n = ' + d.n + ', k = ' + d.k + (d.операция === 'код' && d.d !== null ? ', d = ' + d.d + ' · ошибок исправляет ' + d.исправляет +
                ', обнаруживает ' + (d.d - 1) : '') + ' · ' + (d.переставлены ? 'столбцы переставлены (место ← исходный): ' +
                перестановкаКратко(d.перестановка) : 'перестановка не нужна'));
            if (d.способ) с.push('Спектр: ' + d.способ);
            if (d.сообщение) с.push(d.сообщение);
            break;
        case 'синдромы': с.push('Векторов ' + d.матрица.length + ' · нулевых синдромов (кодовых слов) ' + d.нулевых); break;
        default: с.push('Итог ' + итог(d.матрица));
        }
        return с;
    }

    /** Итог текстом — для буфера обмена и журнала: сводка, матрицы (не больше строкДо строк), спектр, шаги. */
    function текстИтогаМатриц(d, строкДо) {
        const т = сводкаМатриц(d).slice();
        матрицыИтога(d).forEach(([подпись, строки]) => {
            т.push('', подпись + ' (' + строки.length + ' × ' + (строки.length ? строки[0].length : 0) + '):');
            строки.slice(0, строкДо).forEach((с_) => т.push(с_));
            if (строки.length > строкДо) т.push('… ещё ' + (строки.length - строкДо) + ' строк');
        });
        if (d.переставлены) т.push('', 'Перестановка столбцов (i-й — исходный): ' + d.перестановка.join(' '));
        if (d.спектр) т.push('', 'Весовой спектр (вес: слов): ' + d.спектр.map(([w, ч]) => w + ': ' + ч).join(', '));
        if (d.шаги) {
            т.push('', 'Ход метода:');
            d.шаги.forEach((ш, i) => т.push((i + 1) + '. ' + шагГаусса(ш)));
        }
        return т.join('\n');
    }

