                    if (i % 2) { ctx.fillStyle = цвет.шапка; ctx.globalAlpha = 0.5; ctx.fillRect(0, y, ш, ВЫС); ctx.globalAlpha = 1; }
                    ctx.fillStyle = цвет.тускло;
